import { ipcMain } from "electron";
import { Logger } from "../modules/shared/logging/Logger";
import { AppError } from "../modules/shared/error/AppError";
import https from "https";

/**
 * Module IPC Handlers - Provides IPC endpoints for production modules
 *
 * Note: The actual module implementations are complex and require
 * specific input types (Item, BrowserLaunchOptions, etc.).
 * This handler provides basic status endpoints and can be extended
 * as needed with specific module initialization in main process.
 */

const logger = new Logger("ModuleIpcHandlers");

/**
 * Fetch free proxies from multiple sources using Node.js https module
 * Browser fetch won't work due to CORS restrictions
 */
async function fetchFreeProxies(): Promise<string[]> {
  const sources = [
    {
      name: "proxy-list.download",
      fetch: async () => {
        return new Promise<string[]>((resolve, reject) => {
          https
            .get(
              "https://www.proxy-list.download/api/v1/get?type=http",
              { timeout: 5000 },
              (res) => {
                let data = "";
                res.on("data", (chunk) => (data += chunk));
                res.on("end", () => {
                  try {
                    const json = JSON.parse(data);
                    if (json.LISTA && Array.isArray(json.LISTA)) {
                      resolve(json.LISTA.slice(0, 10));
                    } else {
                      resolve([]);
                    }
                  } catch (e) {
                    reject(e);
                  }
                });
              },
            )
            .on("error", reject);
        });
      },
    },
    {
      name: "proxyscrape.com",
      fetch: async () => {
        return new Promise<string[]>((resolve, reject) => {
          https
            .get(
              "https://api.proxyscrape.com/v2/?request=getproxies&format=textplain&timeout=5000&ssl=all&anonymity=all",
              { timeout: 5000 },
              (res) => {
                let data = "";
                res.on("data", (chunk) => (data += chunk));
                res.on("end", () => {
                  const proxies = data
                    .split("\n")
                    .filter((p: string) => p.trim().length > 0)
                    .slice(0, 10);
                  resolve(proxies);
                });
              },
            )
            .on("error", reject);
        });
      },
    },
  ];

  for (const source of sources) {
    try {
      const proxies = await source.fetch();
      if (proxies.length > 0) {
        logger.info(
          `Successfully fetched ${proxies.length} proxies from ${source.name}`,
        );
        return proxies;
      }
    } catch (error) {
      logger.warn(`Failed to fetch from ${source.name}:`, error);
    }
  }

  logger.warn("No free proxies available from any source");
  return [];
}

/**
 * Register IPC handlers for production modules
 * Called from main process after modules are initialized
 */
export function registerModuleIpcHandlers(): void {
  logger.info("Registering production module IPC handlers");

  // ============================================================================
  // TRADING MODULE STATUS ENDPOINTS
  // ============================================================================

  ipcMain.handle("trading:health", async () => {
    try {
      return { success: true, status: "trading module ready" };
    } catch (error: any) {
      return { success: false, error: error.message };
    }
  });

  // ============================================================================
  // BROWSER AUTOMATION MODULE STATUS ENDPOINTS
  // ============================================================================

  ipcMain.handle("browser:health", async () => {
    try {
      return { success: true, status: "browser module ready" };
    } catch (error: any) {
      return { success: false, error: error.message };
    }
  });

  // ============================================================================
  // PROXY MANAGEMENT MODULE STATUS ENDPOINTS
  // ============================================================================

  ipcMain.handle("proxy-mgmt:health", async () => {
    try {
      return { success: true, status: "proxy management module ready" };
    } catch (error: any) {
      return { success: false, error: error.message };
    }
  });

  ipcMain.handle("proxy:fetchFreeProxies", async () => {
    try {
      const proxies = await fetchFreeProxies();
      if (proxies.length === 0) {
        return {
          success: false,
          error: "No proxies available from any source",
          proxies: [],
        };
      }
      return { success: true, proxies };
    } catch (error: any) {
      logger.error("Failed to fetch free proxies:", error);
      return { success: false, error: error.message, proxies: [] };
    }
  });

  // ============================================================================
  // NOTE: USERNAME SNIPER HANDLERS ARE MANAGED BY SniperController
  // Do not register sniper handlers here - they are registered in SniperController.ts
  // ============================================================================

  logger.info("Module IPC handlers registered successfully");
}

import { RobloxUserService } from "../users/UserService";
import { RobloxAuthService } from "./RobloxAuthService";
import { storageService } from "../system/StorageService";

/**
 * CookieRefreshService - Manages cookie validation and refreshing
 *
 * Roblox cookies are server-controlled and will expire after inactivity.
 * This service periodically validates cookies and provides methods to:
 * 1. Check if a cookie is still valid
 * 2. Track last active time for accounts
 * 3. Warn users when cookies are about to expire (based on inactivity)
 */
export class CookieRefreshService {
  private validationCache: Map<
    string,
    { lastCheck: number; isValid: boolean }
  > = new Map();
  private cacheValidityMs = 1000 * 60 * 5; // 5 minute cache

  /**
   * Validate a cookie and update account's last active timestamp
   * Returns true if valid, false if expired/invalid
   */
  async validateAndRefresh(cookie: string): Promise<boolean> {
    // Safety check: never validate an empty or null cookie
    if (!cookie || cookie.trim().length === 0) {
      return false;
    }

    try {
      // Check cache first
      const cacheKey = `cookie_${cookie.substring(0, 20)}`;
      const cached = this.validationCache.get(cacheKey);
      if (cached && Date.now() - cached.lastCheck < this.cacheValidityMs) {
        // LRU: move to end on hit
        this.validationCache.delete(cacheKey);
        this.validationCache.set(cacheKey, cached);
        return cached.isValid;
      }

      // Validate with Roblox
      const user = await RobloxUserService.getAuthenticatedUser(cookie);

      if (user && user.id) {
        // Cookie is valid - update last active for this account
        this.updateAccountLastActive(user.id.toString(), cookie);

        // Evict oldest entry if over 200 entries
        if (this.validationCache.size >= 200) {
          const oldestKey = this.validationCache.keys().next().value;
          if (oldestKey !== undefined) this.validationCache.delete(oldestKey);
        }

        // Cache result
        this.validationCache.set(cacheKey, {
          lastCheck: Date.now(),
          isValid: true,
        });

        return true;
      }

      return false;
    } catch (error) {
      // Cache negative result
      const cacheKey = `cookie_${cookie.substring(0, 20)}`;

      // Evict oldest entry if over 200 entries
      if (this.validationCache.size >= 200) {
        const oldestKey = this.validationCache.keys().next().value;
        if (oldestKey !== undefined) this.validationCache.delete(oldestKey);
      }

      this.validationCache.set(cacheKey, {
        lastCheck: Date.now(),
        isValid: false,
      });

      console.error("[CookieRefreshService] Cookie validation failed:", error);
      return false;
    }
  }

  /**
   * Update account's last active timestamp
   * CRITICAL: Only update by exact account match, not by cookie to prevent
   * accidentally marking wrong account as active
   */
  private updateAccountLastActive(userId: string, cookie: string): void {
    try {
      const accounts = storageService.getAccounts() as any[];

      // SAFETY: Only update if userId matches exactly, ignore cookie key
      const updated = accounts.map((acc) => {
        if (acc.userId === userId) {
          return {
            ...acc,
            lastActive: new Date().toISOString(),
          };
        }
        return acc;
      });

      if (JSON.stringify(accounts) !== JSON.stringify(updated)) {
        storageService.setAccounts(updated);
      }
    } catch (error) {
      console.error(
        "[CookieRefreshService] Failed to update last active:",
        error,
      );
    }
  }

  /**
   * Get inactivity duration in milliseconds since last active
   */
  getInactivityDuration(lastActive: string): number {
    if (!lastActive) return Infinity; // Never active
    const lastActiveTime = new Date(lastActive).getTime();
    return Date.now() - lastActiveTime;
  }

  /**
   * Check if account is likely to have expired based on inactivity
   * Roblox typically invalidates cookies after ~30 days of inactivity
   */
  isLikelyExpired(lastActive: string): boolean {
    const inactivityMs = this.getInactivityDuration(lastActive);
    const thirtyDaysMs = 1000 * 60 * 60 * 24 * 30;
    return inactivityMs > thirtyDaysMs;
  }

  /**
   * Check if account is approaching expiration (warn users)
   * Returns days until likely expiration
   */
  daysUntilLikelyExpiration(lastActive: string): number {
    const inactivityMs = this.getInactivityDuration(lastActive);
    const thirtyDaysMs = 1000 * 60 * 60 * 24 * 30;
    const daysRemaining = (thirtyDaysMs - inactivityMs) / (1000 * 60 * 60 * 24);
    return Math.max(0, Math.ceil(daysRemaining));
  }

  /**
   * Batch validate multiple cookies
   * Useful for checking account health on app startup
   */
  async validateBatch(cookies: string[]): Promise<Map<string, boolean>> {
    const results = new Map<string, boolean>();

    for (const cookie of cookies) {
      try {
        const isValid = await this.validateAndRefresh(cookie);
        results.set(cookie, isValid);
      } catch (error) {
        results.set(cookie, false);
      }
    }

    return results;
  }

  /**
   * Get a fresh authentication ticket for a cookie
   * Use this before launching games to ensure the cookie is still valid
   */
  async getFreshTicket(cookie: string): Promise<string> {
    try {
      // Validate first
      const isValid = await this.validateAndRefresh(cookie);
      if (!isValid) {
        throw new Error("Cookie is no longer valid");
      }

      // getAuthenticationTicket handles CSRF internally via 403-retry
      const ticket = await RobloxAuthService.getAuthenticationTicket(
        cookie,
        "",
      );

      return ticket;
    } catch (error: any) {
      throw new Error(
        `Failed to get fresh authentication ticket: ${error.message}`,
      );
    }
  }

  /**
   * Clear validation cache (useful for testing or forcing revalidation)
   */
  clearCache(): void {
    this.validationCache.clear();
  }
}

export const cookieRefreshService = new CookieRefreshService();

import {
  BrowserWindow,
  BrowserWindowConstructorOptions,
  session,
  shell,
  BrowserView,
  ipcMain,
} from "electron";
import type { Cookie, Event as ElectronEvent } from "electron";
import { UserAgentService } from "./UserAgentService";

export class RobloxLoginWindowService {
  private static readonly PARTITION = "persist:roblox-login";
  private static readonly ROBLOX_LOGIN_URL = "https://www.roblox.com/login";
  private static readonly PERMITTED_PERMISSIONS = new Set<string>([
    "clipboard-read",
    "display-capture",
    "fullscreen",
    "hid",
    "idle-detection",
    "media",
    "mediaKeySystem",
    "notifications",
    "pointerLock",
    "serial",
    "usb",
  ]);

  private static loginWindow: BrowserWindow | null = null;
  private static pendingPromise: Promise<string> | null = null;

  static async openLoginWindow(): Promise<string> {
    if (this.pendingPromise) {
      return this.pendingPromise;
    }

    this.pendingPromise = new Promise<string>((resolve, reject) => {
      const loginSession = session.fromPartition(this.PARTITION, {
        cache: true,
      });

      let isResolved = false;
      let isPromiseSettled = false;
      let rejectionError: Error | null = null;

      const handleCookieChange = (
        _event: ElectronEvent,
        cookie: Cookie,
        _cause:
          | "explicit"
          | "overwrite"
          | "expired"
          | "evicted"
          | "expired-overwrite",
        removed: boolean,
      ) => {
        if (!removed && cookie.name === ".ROBLOSECURITY") {
          isResolved = true;
          isPromiseSettled = true;
          resolve(cookie.value);
          this.loginWindow?.close();
        }
      };

      const cleanup = async () => {
        loginSession.cookies.removeListener("changed", handleCookieChange);
        loginSession.setPermissionRequestHandler(null);
        try {
          await loginSession.cookies.remove(
            "https://www.roblox.com",
            ".ROBLOSECURITY",
          );
        } catch (error) {
          console.warn(
            "[RobloxLoginWindow] Failed to remove security cookie after finish:",
            error,
          );
        }
        this.loginWindow = null;
        this.pendingPromise = null;
      };

      const start = async () => {
        try {
          await loginSession.cookies.remove(
            "https://www.roblox.com",
            ".ROBLOSECURITY",
          );
        } catch (error) {
          console.warn(
            "[RobloxLoginWindow] Failed to remove previous security cookie:",
            error,
          );
        }

        loginSession.cookies.on("changed", handleCookieChange);
        loginSession.setPermissionRequestHandler(
          (_wc, permission, callback) => {
            if (permission && this.PERMITTED_PERMISSIONS.has(permission))
              callback(true);
            else callback(false);
          },
        );

        const windowOptions: BrowserWindowConstructorOptions = {
          width: 480,
          height: 720,
          title: "Roblox Login",
          autoHideMenuBar: true,
          backgroundColor: "#050505",
          parent: BrowserWindow.getFocusedWindow() ?? undefined,
          modal: false,
          show: false,
          webPreferences: {
            partition: this.PARTITION,
            nodeIntegration: false,
            contextIsolation: true,
            spellcheck: true,
          },
        };

        this.loginWindow = new BrowserWindow(windowOptions);

        const userAgent = this.getRealisticUserAgent();
        if (userAgent) this.loginWindow.webContents.setUserAgent(userAgent);

        this.loginWindow.on("ready-to-show", () => {
          this.loginWindow?.show();
          this.loginWindow?.focus();
        });

        this.loginWindow.webContents.on(
          "render-process-gone",
          (_event, details) => {
            console.error(
              "[RobloxLoginWindow] Renderer process gone:",
              details,
            );
            try {
              if (this.loginWindow && !this.loginWindow.isDestroyed()) {
                this.loginWindow.close();
              }
            } catch (err) {
              console.warn(
                "[RobloxLoginWindow] Error during cleanup after renderer gone:",
                err,
              );
            }
          },
        );

        this.loginWindow.on("unresponsive", () => {
          try {
            if (this.loginWindow && !this.loginWindow.isDestroyed()) {
              this.loginWindow.close();
            }
          } catch {}
        });

        this.loginWindow.on("closed", async () => {
          await cleanup();
          if (!isPromiseSettled) {
            isPromiseSettled = true;
            reject(rejectionError ?? new Error("LOGIN_WINDOW_CLOSED"));
          }
        });

        this.loginWindow.webContents.setWindowOpenHandler(({ url }) => {
          shell.openExternal(url);
          return { action: "deny" };
        });

        try {
          await this.loginWindow.loadURL(this.ROBLOX_LOGIN_URL, {
            httpReferrer: "https://www.roblox.com/",
            userAgent: this.loginWindow.webContents.getUserAgent(),
          });
        } catch (error) {
          rejectionError =
            error instanceof Error
              ? error
              : new Error("Failed to load Roblox login page");
          if (this.loginWindow && !this.loginWindow.isDestroyed()) {
            this.loginWindow.close();
          } else {
            await cleanup();
            if (!isPromiseSettled) {
              isPromiseSettled = true;
              reject(rejectionError);
            }
          }
        }
      };

      void start().catch(async (error) => {
        rejectionError =
          error instanceof Error
            ? error
            : new Error("Failed to open login window");
        if (this.loginWindow && !this.loginWindow.isDestroyed()) {
          this.loginWindow.close();
          return;
        }
        await cleanup();
        if (!isPromiseSettled) {
          isPromiseSettled = true;
          reject(rejectionError);
        }
      });
    });

    return this.pendingPromise;
  }

  static async openBrowserWithAccount(
    cookie: string,
    url: string = "https://www.roblox.com/home",
    windowWidth?: number,
    windowHeight?: number,
  ): Promise<void> {
    const partition = `persist:account-browser-${Date.now()}`;
    const browserSession = session.fromPartition(partition, { cache: true });

    let browserWindow: BrowserWindow | null = null;

    try {
      try {
        await browserSession.cookies.remove(
          "https://www.roblox.com",
          ".ROBLOSECURITY",
        );
      } catch {}

      await browserSession.cookies.set({
        url: "https://www.roblox.com",
        name: ".ROBLOSECURITY",
        value: cookie,
        domain: ".roblox.com",
        path: "/",
        httpOnly: true,
        secure: true,
        expirationDate: Math.floor(Date.now() / 1000) + 31536000,
      });

      const windowOptions: BrowserWindowConstructorOptions = {
        width: windowWidth && windowWidth > 0 ? windowWidth : 1280,
        height: windowHeight && windowHeight > 0 ? windowHeight : 800,
        title: "Roblox Browser",
        autoHideMenuBar: true,
        backgroundColor: "#050505",
        show: true,
        webPreferences: {
          partition,
          nodeIntegration: false,
          contextIsolation: true,
          webviewTag: true,
          spellcheck: true,
        },
      };

      browserWindow = new BrowserWindow(windowOptions);

      const userAgent = this.getRealisticUserAgent();
      if (userAgent) browserWindow.webContents.setUserAgent(userAgent);

      browserWindow.webContents.on("render-process-gone", () => {
        if (browserWindow && !browserWindow.isDestroyed())
          browserWindow.close();
      });

      browserWindow.on("unresponsive", () => {
        if (browserWindow && !browserWindow.isDestroyed())
          browserWindow.close();
      });

      browserWindow.on("closed", async () => {
        browserWindow = null;
        try {
          await browserSession.clearCache();
          await browserSession.cookies.remove(
            "https://www.roblox.com",
            ".ROBLOSECURITY",
          );
        } catch {}
      });

      const toolbarHeight = 40;

      const toolbarView = new BrowserView({
        webPreferences: { nodeIntegration: true, contextIsolation: false },
      });
      const contentView = new BrowserView({
        webPreferences: {
          partition,
          nodeIntegration: false,
          contextIsolation: true,
        },
      });

      browserWindow.setBrowserView(toolbarView);
      browserWindow.addBrowserView(contentView);

      const resizeViews = () => {
        if (!browserWindow || browserWindow.isDestroyed()) return;
        const [w, h] = browserWindow.getContentSize();
        toolbarView.setBounds({ x: 0, y: 0, width: w, height: toolbarHeight });
        contentView.setBounds({
          x: 0,
          y: toolbarHeight,
          width: w,
          height: Math.max(0, h - toolbarHeight),
        });
        toolbarView.setAutoResize({ width: true });
        contentView.setAutoResize({ width: true, height: true });
      };

      resizeViews();
      browserWindow.on("resize", resizeViews);

      const ipcChannel = "sentra-browser-cmd";

      const ipcHandler = (_event: any, cmd: string, payload?: any) => {
        if (!contentView?.webContents) return;
        switch (cmd) {
          case "back":
            if (contentView.webContents.canGoBack())
              contentView.webContents.goBack();
            break;
          case "forward":
            if (contentView.webContents.canGoForward())
              contentView.webContents.goForward();
            break;
          case "reload":
            contentView.webContents.reload();
            break;
          case "load":
            if (typeof payload === "string") {
              let u = payload.trim();
              if (!/^https?:\/\//i.test(u)) u = "https://" + u;
              contentView.webContents.loadURL(u);
            }
            break;
        }
      };

      ipcMain.on(ipcChannel, ipcHandler);

      // Load a minimal toolbar UI into the toolbar BrowserView so navigation controls are visible.
      try {
        const toolbarHTML = `<!doctype html>
          <html>
          <head>
            <meta charset="utf-8" />
            <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline' 'unsafe-eval'; connect-src *;">
            <style>
              :root{ --bg:#0b0b0b; --btn:#1a1a1a; --btn-border:#333; --btn-hover:#252525; --text:#ddd; --accent:75,140,255 }
              body { margin:0; background:var(--bg); color:var(--text); font-family:Inter, Arial, Helvetica, sans-serif; -webkit-font-smoothing:antialiased }
              .bar { height:40px; display:flex; align-items:center; gap:8px; padding:6px; box-sizing:border-box; opacity:0; transform:translateY(-6px); animation:toolbarFade 220ms ease forwards }
              button{ background:var(--btn); border:1px solid var(--btn-border); color:var(--text); padding:6px 10px; border-radius:8px; cursor:pointer; transition:transform 140ms cubic-bezier(.2,.9,.2,1), background-color 140ms, box-shadow 140ms; box-shadow:0 3px 8px rgba(0,0,0,0.35); display:inline-flex; align-items:center; justify-content:center; font-weight:600 }
              button:hover{ transform:translateY(-2px); background:var(--btn-hover); box-shadow:0 8px 20px rgba(0,0,0,0.45) }
              button:active{ transform:translateY(0) scale(0.985) }
              button:disabled{ opacity:.45; transform:none; cursor:not-allowed; box-shadow:none }
              input{ flex:1; padding:8px 10px; border-radius:10px; border:1px solid #2b2b2b; background:#0f0f0f; color:#fff; transition:box-shadow 140ms, border-color 140ms, transform 140ms; outline:none }
              input:focus{ box-shadow:0 6px 24px rgba(var(--accent),0.12); border-color: rgba(75,140,255,0.6); transform:translateY(-1px) }
              @keyframes toolbarFade{ to{ opacity:1; transform:translateY(0) } }
            </style>
          </head>
          <body>
            <div class="bar">
              <button id="back">◀</button>
              <button id="forward">▶</button>
              <button id="reload">⟳</button>
              <input id="url" placeholder="https://example.com" />
              <button id="go">Go</button>
            </div>
            <script>
              const { ipcRenderer } = require('electron')
              const $ = (id) => document.getElementById(id)
              $('back').addEventListener('click', () => ipcRenderer.send('${ipcChannel}', 'back'))
              $('forward').addEventListener('click', () => ipcRenderer.send('${ipcChannel}', 'forward'))
              $('reload').addEventListener('click', () => ipcRenderer.send('${ipcChannel}', 'reload'))
              $('go').addEventListener('click', () => { const v = $('url').value || ''; ipcRenderer.send('${ipcChannel}', 'load', v) })
              $('url').addEventListener('keydown', (e) => { if (e.key === 'Enter') $('go').click() })
            </script>
          </body>
          </html>`;

        await toolbarView.webContents.loadURL(
          "data:text/html;charset=utf-8," + encodeURIComponent(toolbarHTML),
        );
      } catch (err) {
        // Non-fatal: if toolbar fails to load, continue without it
        console.warn("[RobloxLoginWindow] Failed to load toolbar UI", err);
      }

      // Update toolbar button enabled state when navigation events occur in the content view
      const updateToolbarButtons = async () => {
        try {
          if (!toolbarView?.webContents || !contentView?.webContents) return;
          const canBack = await contentView.webContents.canGoBack();
          const canForward = await contentView.webContents.canGoForward();
          await toolbarView.webContents.executeJavaScript(
            `document.getElementById('back').disabled = ${!canBack}`,
          );
          await toolbarView.webContents.executeJavaScript(
            `document.getElementById('forward').disabled = ${!canForward}`,
          );
          const currentUrl = contentView.webContents.getURL() || "";
          await toolbarView.webContents.executeJavaScript(
            `document.getElementById('url').value = ${JSON.stringify(currentUrl)}`,
          );
        } catch {}
      };

      if (contentView?.webContents) {
        contentView.webContents.on("did-navigate", updateToolbarButtons);
        contentView.webContents.on(
          "did-navigate-in-page",
          updateToolbarButtons,
        );
        contentView.webContents.on("did-finish-load", updateToolbarButtons);
      }

      browserWindow.on("closed", () => {
        ipcMain.removeListener(ipcChannel, ipcHandler);
      });

      // Handle popup / new tab requests from content page - open in external browser
      contentView.webContents.setWindowOpenHandler(({ url }) => {
        shell.openExternal(url);
        return { action: "deny" };
      });

      // Handle navigation failures gracefully - only close on truly fatal errors
      contentView.webContents.on(
        "did-fail-load",
        (_event, errorCode, errorDescription, validatedURL, isMainFrame) => {
          // Ignore common non-fatal error codes:
          // -3 = ERR_ABORTED (navigation cancelled, e.g. redirect)
          // -6 = ERR_FILE_NOT_FOUND (url paste mid-type)
          // -102 = ERR_CONNECTION_REFUSED (temp network issue)
          const nonFatalCodes = new Set([-3, -6, -102, -105, -106, -118]);
          if (isMainFrame && !nonFatalCodes.has(errorCode)) {
            console.warn(
              `[Browser] Load failed (${errorCode}): ${errorDescription} @ ${validatedURL}`,
            );
          }
          // Never close the window on load failure - let user retry
        },
      );

      try {
        await contentView.webContents.loadURL(url, {
          httpReferrer: "https://www.roblox.com/",
          userAgent: browserWindow.webContents.getUserAgent(),
        });
      } catch (loadError) {
        // Non-fatal: URL load errors shouldn't close the browser window
        // The user can still navigate using the toolbar
        console.warn(
          "[Browser] Initial URL load error (window still open):",
          loadError,
        );
      }
    } catch (error) {
      if (browserWindow && !browserWindow.isDestroyed()) browserWindow.close();
      try {
        await browserSession.clearCache();
        await browserSession.cookies.remove(
          "https://www.roblox.com",
          ".ROBLOSECURITY",
        );
      } catch {}
      throw error instanceof Error
        ? error
        : new Error("Failed to open browser with account");
    }
  }

  /**
   * Open signup browser with custom toolbar for account generation
   * Returns the BrowserWindow and allows Playwright to interact with it
   */
  static async openSignupBrowser(
    windowWidth?: number,
    windowHeight?: number,
  ): Promise<{
    browserWindow: BrowserWindow;
    pageUrl: string;
    webContents: any;
    partition: string;
  }> {
    const partition = `persist:signup-${Date.now()}`;
    const signupSession = session.fromPartition(partition, { cache: true });

    let browserWindow: BrowserWindow | null = null;

    try {
      const windowOptions: BrowserWindowConstructorOptions = {
        width: windowWidth && windowWidth > 0 ? windowWidth : 1280,
        height: windowHeight && windowHeight > 0 ? windowHeight : 800,
        title: "Roblox Signup",
        autoHideMenuBar: true,
        backgroundColor: "#050505",
        show: true,
        webPreferences: {
          partition,
          nodeIntegration: false,
          contextIsolation: true,
          webviewTag: true,
          spellcheck: true,
        },
      };

      browserWindow = new BrowserWindow(windowOptions);

      const userAgent = this.getRealisticUserAgent();
      if (userAgent) browserWindow.webContents.setUserAgent(userAgent);

      browserWindow.webContents.on("render-process-gone", () => {
        if (browserWindow && !browserWindow.isDestroyed())
          browserWindow.close();
      });

      browserWindow.on("unresponsive", () => {
        if (browserWindow && !browserWindow.isDestroyed())
          browserWindow.close();
      });

      browserWindow.on("closed", async () => {
        browserWindow = null;
        try {
          await signupSession.clearCache();
        } catch {}
      });

      const toolbarHeight = 40;
      const toolbarView = new BrowserView({
        webPreferences: { nodeIntegration: true, contextIsolation: false },
      });
      const contentView = new BrowserView({
        webPreferences: {
          partition,
          nodeIntegration: false,
          contextIsolation: true,
        },
      });

      browserWindow.setBrowserView(toolbarView);
      browserWindow.addBrowserView(contentView);

      const resizeViews = () => {
        if (!browserWindow || browserWindow.isDestroyed()) return;
        const [w, h] = browserWindow.getContentSize();
        toolbarView.setBounds({ x: 0, y: 0, width: w, height: toolbarHeight });
        contentView.setBounds({
          x: 0,
          y: toolbarHeight,
          width: w,
          height: Math.max(0, h - toolbarHeight),
        });
        toolbarView.setAutoResize({ width: true });
        contentView.setAutoResize({ width: true, height: true });
      };

      resizeViews();
      browserWindow.on("resize", resizeViews);

      const ipcChannel = "sentra-signup-browser-cmd";

      const ipcHandler = (_event: any, cmd: string, payload?: any) => {
        if (!contentView?.webContents) return;
        switch (cmd) {
          case "back":
            if (contentView.webContents.canGoBack())
              contentView.webContents.goBack();
            break;
          case "forward":
            if (contentView.webContents.canGoForward())
              contentView.webContents.goForward();
            break;
          case "reload":
            contentView.webContents.reload();
            break;
          case "load":
            if (typeof payload === "string") {
              let u = payload.trim();
              if (!/^https?:\/\//i.test(u)) u = "https://" + u;
              contentView.webContents.loadURL(u);
            }
            break;
        }
      };

      ipcMain.on(ipcChannel, ipcHandler);

      // Load toolbar UI (same as openBrowserWithAccount)
      try {
        const toolbarHTML = `<!doctype html>
          <html>
          <head>
            <meta charset="utf-8" />
            <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline' 'unsafe-eval'; connect-src *;">
            <style>
              :root{ --bg:#0b0b0b; --btn:#1a1a1a; --btn-border:#333; --btn-hover:#252525; --text:#ddd; --accent:75,140,255 }
              body { margin:0; background:var(--bg); color:var(--text); font-family:Inter, Arial, Helvetica, sans-serif; -webkit-font-smoothing:antialiased }
              .bar { height:40px; display:flex; align-items:center; gap:8px; padding:6px; box-sizing:border-box; opacity:0; transform:translateY(-6px); animation:toolbarFade 220ms ease forwards }
              button{ background:var(--btn); border:1px solid var(--btn-border); color:var(--text); padding:6px 10px; border-radius:8px; cursor:pointer; transition:transform 140ms cubic-bezier(.2,.9,.2,1), background-color 140ms, box-shadow 140ms; box-shadow:0 3px 8px rgba(0,0,0,0.35); display:inline-flex; align-items:center; justify-content:center; font-weight:600 }
              button:hover{ transform:translateY(-2px); background:var(--btn-hover); box-shadow:0 8px 20px rgba(0,0,0,0.45) }
              button:active{ transform:translateY(0) scale(0.985) }
              button:disabled{ opacity:.45; transform:none; cursor:not-allowed; box-shadow:none }
              input{ flex:1; padding:8px 10px; border-radius:10px; border:1px solid #2b2b2b; background:#0f0f0f; color:#fff; transition:box-shadow 140ms, border-color 140ms, transform 140ms; outline:none }
              input:focus{ box-shadow:0 6px 24px rgba(var(--accent),0.12); border-color: rgba(75,140,255,0.6); transform:translateY(-1px) }
              @keyframes toolbarFade{ to{ opacity:1; transform:translateY(0) } }
            </style>
          </head>
          <body>
            <div class="bar">
              <button id="back">◀</button>
              <button id="forward">▶</button>
              <button id="reload">⟳</button>
              <input id="url" placeholder="https://example.com" />
              <button id="go">Go</button>
            </div>
            <script>
              const { ipcRenderer } = require('electron')
              const $ = (id) => document.getElementById(id)
              $('back').addEventListener('click', () => ipcRenderer.send('${ipcChannel}', 'back'))
              $('forward').addEventListener('click', () => ipcRenderer.send('${ipcChannel}', 'forward'))
              $('reload').addEventListener('click', () => ipcRenderer.send('${ipcChannel}', 'reload'))
              $('go').addEventListener('click', () => { const v = $('url').value || ''; ipcRenderer.send('${ipcChannel}', 'load', v) })
              $('url').addEventListener('keydown', (e) => { if (e.key === 'Enter') $('go').click() })
            </script>
          </body>
          </html>`;

        await toolbarView.webContents.loadURL(
          "data:text/html;charset=utf-8," + encodeURIComponent(toolbarHTML),
        );
      } catch (err) {
        console.warn("[RobloxSignupBrowser] Failed to load toolbar UI", err);
      }

      // Update toolbar buttons
      const updateToolbarButtons = async () => {
        try {
          if (!toolbarView?.webContents || !contentView?.webContents) return;
          const canBack = await contentView.webContents.canGoBack();
          const canForward = await contentView.webContents.canGoForward();
          await toolbarView.webContents.executeJavaScript(
            `document.getElementById('back').disabled = ${!canBack}`,
          );
          await toolbarView.webContents.executeJavaScript(
            `document.getElementById('forward').disabled = ${!canForward}`,
          );
          const currentUrl = contentView.webContents.getURL() || "";
          await toolbarView.webContents.executeJavaScript(
            `document.getElementById('url').value = ${JSON.stringify(currentUrl)}`,
          );
        } catch {}
      };

      if (contentView?.webContents) {
        contentView.webContents.on("did-navigate", updateToolbarButtons);
        contentView.webContents.on(
          "did-navigate-in-page",
          updateToolbarButtons,
        );
        contentView.webContents.on("did-finish-load", updateToolbarButtons);
      }

      browserWindow.on("closed", () => {
        ipcMain.removeListener(ipcChannel, ipcHandler);
      });

      // Load signup page in content view
      await contentView.webContents.loadURL("https://www.roblox.com/signup", {
        httpReferrer: "https://www.roblox.com/",
        userAgent: browserWindow.webContents.getUserAgent(),
      });

      console.log(
        "[RobloxSignupBrowser] Signup browser opened with custom toolbar",
      );

      return {
        browserWindow,
        pageUrl: "https://www.roblox.com/signup",
        webContents: contentView.webContents,
        partition,
      };
    } catch (error) {
      if (browserWindow && !browserWindow.isDestroyed()) browserWindow.close();
      try {
        await signupSession.clearCache();
      } catch {}
      throw error instanceof Error
        ? error
        : new Error("Failed to open signup browser");
    }
  }

  private static getRealisticUserAgent(): string {
    return UserAgentService.getCurrentUserAgent();
  }
}

import { ipcMain, WebContents } from "electron";

export function promptTwoFactor(
  webContents: WebContents,
  payload: { accountId?: string; message?: string },
  timeoutMs = 5 * 60 * 1000,
): Promise<string | null> {
  return new Promise((resolve) => {
    let resolved = false;

    const onResponse = (_event: any, code: string | null) => {
      if (resolved) return;
      resolved = true;
      cleanup();
      resolve(code ?? null);
    };

    const cleanup = () => {
      try {
        ipcMain.removeListener("two-factor-response", onResponse as any);
      } catch {}
      if (timeout) clearTimeout(timeout as NodeJS.Timeout);
    };

    // Listen once for the response
    ipcMain.once("two-factor-response", onResponse as any);

    // Send request to renderer to show prompt
    try {
      webContents.send("prompt-two-factor", payload);
    } catch (err) {
      cleanup();
      resolve(null);
      return;
    }

    // Setup timeout
    const timeout = setTimeout(() => {
      if (resolved) return;
      resolved = true;
      cleanup();
      resolve(null);
    }, timeoutMs);
  });
}

export default promptTwoFactor;

/**
 * Form Automation Service - Handles form filling and submission.
 */

import { EventEmitter } from "events";
import { Logger } from "../../shared/logging/Logger";
import {
  AppError,
  ErrorCode,
  ErrorSeverity,
} from "../../shared/error/AppError";
import { FormConfig, FormField, IBrowserInstance } from "../types/BrowserTypes";
import { IFormAutomationService } from "../interfaces/BrowserInterfaces";

export class FormAutomationService
  extends EventEmitter
  implements IFormAutomationService
{
  private logger: Logger;
  private browser: IBrowserInstance | null = null;

  constructor(browser: IBrowserInstance) {
    super();
    this.logger = new Logger("FormAutomationService");
    this.browser = browser;
  }

  /**
   * Fill form with provided configuration.
   */
  public async fillForm(config: FormConfig): Promise<void> {
    if (!this.browser) {
      throw new AppError(
        "Browser instance not available",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
      );
    }

    try {
      this.logger.info("Starting form fill", {
        fieldCount: config.fields.length,
      });

      for (const field of config.fields) {
        await this.fillField(field);
      }

      // Execute custom actions
      if (config.customActions) {
        for (const customAction of config.customActions) {
          try {
            this.logger.info("Executing custom action", {
              action: customAction.name,
            });
            await customAction.action(this.browser);
          } catch (error) {
            this.logger.error("Custom action failed", error as Error, {
              action: customAction.name,
            });
            throw new AppError(
              `Custom action failed: ${customAction.name}`,
              ErrorCode.BROWSER_FORM_ERROR,
              "FormAutomationService",
              ErrorSeverity.MEDIUM,
              { action: customAction.name },
            );
          }
        }
      }

      this.logger.info("Form fill completed");
      this.emit("formFilled", { fields: config.fields.length });
    } catch (error) {
      const appError = new AppError(
        "Form fill failed",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
        ErrorSeverity.MEDIUM,
        { error },
      );
      this.logger.error("Form fill error", error as Error);
      throw appError;
    }
  }

  /**
   * Submit form.
   */
  public async submitForm(selector: string): Promise<void> {
    if (!this.browser) {
      throw new AppError(
        "Browser instance not available",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
      );
    }

    try {
      this.logger.info("Submitting form", { selector });
      await this.browser.click(selector);
      this.logger.info("Form submitted");
      this.emit("formSubmitted");
    } catch (error) {
      const appError = new AppError(
        "Form submission failed",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
        ErrorSeverity.MEDIUM,
        { selector },
      );
      this.logger.error("Form submission error", error as Error);
      throw appError;
    }
  }

  /**
   * Extract form data.
   */
  public async extractFormData(selector: string): Promise<Record<string, any>> {
    if (!this.browser) {
      throw new AppError(
        "Browser instance not available",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
      );
    }

    try {
      const data = await this.browser.evaluate((formSelector: string) => {
        const form = document.querySelector(formSelector);
        if (!form) {
          return {};
        }

        const result: Record<string, any> = {};
        const inputs = form.querySelectorAll("input, textarea, select");

        inputs.forEach((input: any) => {
          const name = input.name || input.id;
          if (name) {
            if (input.type === "checkbox" || input.type === "radio") {
              result[name] = input.checked;
            } else {
              result[name] = input.value;
            }
          }
        });

        return result;
      }, selector);

      this.logger.info("Form data extracted", { selector });
      return data;
    } catch (error) {
      const appError = new AppError(
        "Failed to extract form data",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
        ErrorSeverity.MEDIUM,
        { selector },
      );
      this.logger.error("Form data extraction error", error as Error);
      throw appError;
    }
  }

  /**
   * Wait for form submission (page navigation or success indicator).
   */
  public async waitForFormSubmission(timeout: number = 30000): Promise<void> {
    if (!this.browser) {
      throw new AppError(
        "Browser instance not available",
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
      );
    }

    try {
      this.logger.info("Waiting for form submission");

      await this.withTimeout(
        this.browser.waitForSelector(".success, [data-success], .loading"),
        timeout,
      );

      this.logger.info("Form submission detected");
      this.emit("formSubmissionDetected");
    } catch (error) {
      const appError = new AppError(
        "Timeout waiting for form submission",
        ErrorCode.BROWSER_TIMEOUT_ERROR,
        "FormAutomationService",
      );
      this.logger.error("Form submission wait timeout");
      throw appError;
    }
  }

  /**
   * Fill individual field.
   */
  private async fillField(field: FormField): Promise<void> {
    if (!this.browser) {
      return;
    }

    try {
      this.logger.debug("Filling field", {
        selector: field.selector,
        type: field.type,
      });

      // Wait for field visibility if configured
      if (field.waitForVisible) {
        await this.browser.waitForSelector(field.selector, {
          timeout: 10000,
        });
      }

      if (field.clearFirst) {
        await this.browser.evaluate((selector: string) => {
          const el = document.querySelector(selector) as HTMLInputElement;
          if (el) {
            el.value = "";
            el.dispatchEvent(new Event("change", { bubbles: true }));
          }
        }, field.selector);
      }

      switch (field.type) {
        case "text":
        case "email":
        case "password":
        case "number":
          if (field.value !== undefined) {
            await this.browser.fill(field.selector, String(field.value));
          }
          break;

        case "select":
          if (field.value !== undefined) {
            await this.browser.select(field.selector, String(field.value));
          }
          break;

        case "checkbox":
        case "radio":
          if (field.value === "true" || field.value === true) {
            await this.browser.click(field.selector);
          }
          break;

        case "custom":
          // Custom handling defined in form config
          break;

        default:
          this.logger.warn("Unknown field type", { type: field.type });
      }

      this.emit("fieldFilled", { selector: field.selector });
    } catch (error) {
      this.logger.error("Failed to fill field", error as Error, {
        selector: field.selector,
      });

      throw new AppError(
        `Failed to fill field: ${field.selector}`,
        ErrorCode.BROWSER_FORM_ERROR,
        "FormAutomationService",
        ErrorSeverity.MEDIUM,
        { selector: field.selector },
      );
    }
  }

  /**
   * Execute with timeout.
   */
  private withTimeout<T>(promise: Promise<T>, timeout: number): Promise<T> {
    return Promise.race<T>([
      promise,
      new Promise<T>((_, reject) =>
        setTimeout(() => {
          reject(
            new AppError(
              "Operation timeout",
              ErrorCode.BROWSER_TIMEOUT_ERROR,
              "FormAutomationService",
            ),
          );
        }, timeout),
      ),
    ]);
  }
}

import { z } from "zod";
import { handle } from "../core/utils/handle";
import { catalogDatabaseService } from "./CatalogDatabaseService";

/**
 * Registers catalog database IPC handlers
 */
export const registerCatalogDatabaseHandlers = (): void => {
  // Get database status (exists, downloading, error)
  handle("get-catalog-db-status", z.tuple([]), async () => {
    return catalogDatabaseService.getStatus();
  });

  // Download the database if not present
  handle("download-catalog-db", z.tuple([]), async () => {
    return catalogDatabaseService.downloadDatabase();
  });

  // Get all items for search indexing
  handle("get-all-catalog-items", z.tuple([]), async () => {
    return catalogDatabaseService.getAllItems();
  });

  // Get exported catalog index (built in a worker thread)
  handle("get-catalog-index-export", z.tuple([]), async () => {
    return catalogDatabaseService.getExportedIndex();
  });

  // Search items by name
  handle(
    "search-catalog-db",
    z.tuple([z.string(), z.number().optional()]),
    async (_, query, limit) => {
      return catalogDatabaseService.searchByName(query, limit);
    },
  );

  // Get item by ID
  handle(
    "get-catalog-item-by-id",
    z.tuple([z.number()]),
    async (_, assetId) => {
      return catalogDatabaseService.getItemById(assetId);
    },
  );

  // Get sales data for a single asset
  handle("get-sales-data", z.tuple([z.number()]), async (_, assetId) => {
    try {
      return await catalogDatabaseService.getSalesData(assetId);
    } catch (error) {
      // Database not available, return null gracefully
      return null;
    }
  });

  // Get batch sales data for multiple assets
  handle(
    "get-batch-sales-data",
    z.tuple([z.array(z.number())]),
    async (_, assetIds) => {
      try {
        return await catalogDatabaseService.getBatchSalesData(assetIds);
      } catch (error) {
        // Database not available, return empty object gracefully
        return {};
      }
    },
  );

  // Get total item count
  handle("get-catalog-item-count", z.tuple([]), async () => {
    return catalogDatabaseService.getItemCount();
  });
};

