const getClientSettingsPaths = (
  installPath: string,
): { dir: string; file: string } => {
  if (process.platform === "darwin") {
    const dir = path.join(
      os.homedir(),
      "Library",
      "Application Support",
      "Roblox",
      "ClientSettings",
    );
    return { dir, file: path.join(dir, "ClientAppSettings.json") };
  }

  const dir = path.join(installPath, "ClientSettings");
  return { dir, file: path.join(dir, "ClientAppSettings.json") };
};

const readMacBundleVersion = (bundlePath: string): string | null => {
  try {
    const infoPlistPath = path.join(bundlePath, "Contents", "Info.plist");
    if (!fs.existsSync(infoPlistPath)) return null;
    const plist = fs.readFileSync(infoPlistPath, "utf8");
    const match = plist.match(
      /<key>CFBundleShortVersionString<\/key>\s*<string>(?<ver>[^<]+)<\/string>/i,
    );
    return match?.groups?.ver?.trim() || null;
  } catch (e) {
    console.warn(
      "[RobloxInstallService] Failed to read mac bundle version:",
      e,
    );
    return null;
  }
};

export class RobloxInstallService {
  private static historyCache: Record<string, string[]> | null = null;
  private static lastHistoryFetch = 0;
  private static readonly CACHE_DURATION = 1000 * 60 * 15; // 15 minutes
  private static installationStartTime = 0; // Track when installation begins

  static async getDeployHistory(
    forceRefresh = false,
  ): Promise<Record<string, string[]>> {
    const now = Date.now();
    if (
      !forceRefresh &&
      this.historyCache &&
      now - this.lastHistoryFetch < this.CACHE_DURATION
    ) {
      return this.historyCache;
    }

    try {
      const types = Object.keys(BINARY_TYPES);
      const results: Record<string, string[]> = {};
      const CHANNELS = ["live", "zflag"]; // Query multiple channels to provide a history list

      await Promise.all(
        types.map(async (typ) => {
          results[typ] = [];
          for (const channel of CHANNELS) {
            try {
              const url = `https://clientsettings.roblox.com/v2/client-version/${typ}/channel/${channel}`;
              const res = await safeFetchText(url);
              const json = JSON.parse(res);

              let hash = json.clientVersionUpload;
              if (hash && hash.startsWith("version-")) {
                hash = hash.replace("version-", "");
              }
              if (hash && !results[typ].includes(hash)) {
                results[typ].push(hash);
              }
            } catch (e) {
              // Ignore channel fetch errors
            }
          }
        }),
      );

      const validatedHistory = deployHistorySchema.parse(results);

      this.historyCache = validatedHistory;
      this.lastHistoryFetch = now;

      return validatedHistory;
    } catch (e) {
      console.error("[RobloxInstallService] Failed to fetch deploy history", e);
      return this.historyCache || {};
    }
  }

  static async downloadAndInstall(
    binaryType: string,
    version: string,
    installPath: string,
    onProgress: (status: string, progress: number, detail?: string) => void,
  ): Promise<boolean> {
    if (!BINARY_TYPES[binaryType]) {
      onProgress("Invalid binary type", 0);
      return false;
    }

    this.installationStartTime = Date.now();

    try {
      const blobDir = BINARY_TYPES[binaryType].blobDir;
      const verTag = version.startsWith("version-")
        ? version
        : `version-${version}`;
      const base = `${AWS_MIRROR}${blobDir}${verTag}-`;

      let pkgs: string[] = [];
      const isMac = binaryType.startsWith("Mac");

      if (isMac) {
        // Mac uses single app zips instead of manifest
        pkgs =
          binaryType === "MacPlayer"
            ? ["RobloxPlayer.zip"]
            : ["RobloxStudioApp.zip"];
      } else {
        onProgress("Fetching manifest for version: " + verTag, 0);
        let manifest = "";
        try {
          manifest = await safeFetchText(base + "rbxPkgManifest.txt");
          if (!manifest || manifest.length === 0) {
            throw new Error("Manifest is empty - version may not exist");
          }
        } catch (e: any) {
          const errorMsg = e?.message || String(e);
          console.error(
            `[InstallService] Manifest fetch failed for ${verTag}:`,
            errorMsg,
          );
          onProgress(`Version not found: ${verTag}`, 0, errorMsg);
          return false;
        }

        const pkgsRaw = manifest
          .split(/\r?\n/)
          .map((l) => l.trim())
          .filter((l) => l.endsWith(".zip"));
        pkgs = [...new Set(pkgsRaw)];
      }

      if (pkgs.length === 0) {
        onProgress("No packages found", 0);
        return false;
      }

      let roots: Record<string, string> = {};
      if (!isMac) {
        roots = pkgs.includes("RobloxApp.zip")
          ? EXTRACT_ROOTS["player"]
          : EXTRACT_ROOTS["studio"];
      } else {
        roots = {
          "RobloxPlayer.zip": "",
          "RobloxStudioApp.zip": "",
        };
      }

      if (!fs.existsSync(installPath)) {
        fs.mkdirSync(installPath, { recursive: true });
      }

      const appSettingsPath = path.join(installPath, "AppSettings.xml");
      const appSettingsContent = `<?xml version="1.0" encoding="UTF-8"?>
<Settings>
\t<ContentFolder>content</ContentFolder>
\t<BaseUrl>http://www.roblox.com</BaseUrl>
</Settings>
`;
      fs.writeFileSync(appSettingsPath, appSettingsContent);

      let completed = 0;
      const total = pkgs.length;
      const concurrency = 8;

      completed = 0;
      const queue = [...pkgs];

      const { spawn, move } = await import("multithreading");

      const processPackage = async (pkg: string) => {
        const url = base + pkg;
        const zipPath = path.join(installPath, pkg);
        const rootDir = roots[pkg];

        // Pass all necessary data to the worker
        const workerData = {
          url,
          zipPath,
          installPath,
          rootDir,
          pkg,
        };

        return spawn(move(workerData), async (data) => {
          const fs = await import("fs");
          const path = await import("path");
          const { pipeline } = await import("stream");
          const { promisify } = await import("util");
          const https = await import("https");
          const yauzl = await import("yauzl");

          const streamPipeline = promisify(pipeline);

          const downloadFile = (url: string, dest: string): Promise<void> => {
            return new Promise((resolve, reject) => {
              const dir = path.dirname(dest);
              if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

              const file = fs.createWriteStream(dest);

              const request = https.get(url, (response) => {
                if (response.statusCode !== 200) {
                  reject(
                    new Error(
                      `Failed to download ${url}: ${response.statusCode}`,
                    ),
                  );
                  return;
                }
                response.pipe(file);
                file.on("finish", () => {
                  file.close(() => resolve());
                });
              });

              request.on("error", (err) => {
                fs.unlink(dest, () => {});
                reject(err);
              });
            });
          };

          const extractZip = (
            zipPath: string,
            extractPath: string,
          ): Promise<void> => {
            const normalizedRoot = path.resolve(extractPath);
            const rootWithSep = normalizedRoot.endsWith(path.sep)
              ? normalizedRoot
              : normalizedRoot + path.sep;

            return new Promise((resolve, reject) => {
              let finished = false;
              const finish = (err?: Error) => {
                if (finished) return;
                finished = true;
                if (err) reject(err);
                else resolve();
              };

              yauzl.open(
                zipPath,
                {
                  lazyEntries: true,
                  validateEntrySizes: false,
                  decodeStrings: false,
                },
                (err, zipFile) => {
                  if (err || !zipFile) {
                    finish(err ?? new Error(`Failed to open zip ${zipPath}`));
                    return;
                  }

                  const openReadStream = (entry: any) =>
                    new Promise<NodeJS.ReadableStream>(
                      (resolveStream, rejectStream) => {
                        zipFile.openReadStream(
                          entry,
                          (streamErr, readStream) => {
                            if (streamErr || !readStream) {
                              rejectStream(
                                streamErr ?? new Error(`Failed to open stream`),
                              );
                            } else {
                              resolveStream(readStream);
                            }
                          },
                        );
                      },
                    );

                  const processEntry = async (entry: any) => {
                    let fileName = entry.fileName;
                    if (Buffer.isBuffer(fileName)) {
                      const isUtf8 =
                        (entry.generalPurposeBitFlag & 0x800) !== 0;
                      fileName = fileName.toString(isUtf8 ? "utf8" : "latin1");
                    }
                    const fileNameStr = fileName as string;
                    const sanitizedName = fileNameStr.replace(/^([/\\])+/, "");
                    if (!sanitizedName) {
                      zipFile.readEntry();
                      return;
                    }

                    const normalizedEntryPath = path.resolve(
                      normalizedRoot,
                      sanitizedName,
                    );
                    if (
                      normalizedEntryPath !== normalizedRoot &&
                      !normalizedEntryPath.startsWith(rootWithSep)
                    ) {
                      // escape
                    } else {
                      if (
                        fileNameStr.endsWith("/") ||
                        fileNameStr.endsWith("\\")
                      ) {
                        await fs.promises.mkdir(normalizedEntryPath, {
                          recursive: true,
                        });
                      } else {
                        await fs.promises.mkdir(
                          path.dirname(normalizedEntryPath),
                          {
                            recursive: true,
                          },
                        );
                        const readStream = await openReadStream(entry);
                        const writeStream =
                          fs.createWriteStream(normalizedEntryPath);
                        await streamPipeline(readStream, writeStream);
                      }
                    }
                    zipFile.readEntry();
                  };

                  zipFile.on("entry", (entry) => {
                    processEntry(entry).catch(finish);
                  });
                  zipFile.on("end", () => finish());
                  zipFile.on("error", (err) => finish(err));
                  zipFile.readEntry();
                },
              );
            });
          };

          await downloadFile(data.url, data.zipPath);

          if (data.rootDir !== undefined) {
            const targetExtractPath =
              data.rootDir === ""
                ? data.installPath
                : path.join(data.installPath, data.rootDir);
            if (!fs.existsSync(targetExtractPath)) {
              fs.mkdirSync(targetExtractPath, { recursive: true });
            }
            await extractZip(data.zipPath, targetExtractPath);

            // Cleanup
            try {
              await fs.promises.unlink(data.zipPath);
            } catch {
              // Ignore cleanup failures
            }
          }

          return { success: true, pkg: data.pkg };
        });
      };

      const activeWorkers: Promise<any>[] = [];
      let hasError = false;
      let errorMessage = "";

      // Initial fill
      while (queue.length > 0 && activeWorkers.length < concurrency) {
        const pkg = queue.shift()!;
        const workerPromise = processPackage(pkg).then((handle) =>
          handle.join(),
        );
        // We need to track the promise itself to remove it from the pool
        const trackedPromise = workerPromise
          .then(() => {
            activeWorkers.splice(activeWorkers.indexOf(trackedPromise), 1);
            completed++;
            onProgress(
              "Installing...",
              Math.floor((completed / total) * 100),
              pkg,
            );
          })
          .catch((err) => {
            activeWorkers.splice(activeWorkers.indexOf(trackedPromise), 1);
            hasError = true;
            errorMessage = `Failed to install ${pkg}: ${err?.message || String(err)}`;
            console.error("[RobloxInstallService]", errorMessage);
            throw err;
          });
        activeWorkers.push(trackedPromise);
      }

      // Replenish
      while (activeWorkers.length > 0) {
        try {
          await Promise.race(activeWorkers);
        } catch (err) {
          if (hasError) {
            throw new Error(errorMessage);
          }
        }
        while (queue.length > 0 && activeWorkers.length < concurrency) {
          const pkg = queue.shift()!;
          const workerPromise = processPackage(pkg).then((handle) =>
            handle.join(),
          );
          const trackedPromise = workerPromise
            .then(() => {
              activeWorkers.splice(activeWorkers.indexOf(trackedPromise), 1);
              completed++;
              onProgress(
                "Installing...",
                Math.floor((completed / total) * 100),
                pkg,
              );
            })
            .catch((err) => {
              activeWorkers.splice(activeWorkers.indexOf(trackedPromise), 1);
              hasError = true;
              errorMessage = `Failed to install ${pkg}: ${err?.message || String(err)}`;
              console.error("[RobloxInstallService]", errorMessage);
              throw err;
            });
          activeWorkers.push(trackedPromise);
        }
      }

      if (hasError) {
        throw new Error(errorMessage);
      }

      onProgress("Complete", 100);
      return true;
    } catch (e) {
      console.error("Installation failed", e);
      return false;
    }
  }

  static async launch(installPath: string): Promise<void> {
    if (process.platform === "darwin") {
      let appPath = "";

      if (installPath.endsWith(".app") && fs.existsSync(installPath)) {
        appPath = installPath;
      } else {
        const playerApp = path.join(installPath, "RobloxPlayer.app");
        const studioApp = path.join(installPath, "RobloxStudio.app");

        if (fs.existsSync(playerApp)) {
          appPath = playerApp;
        } else if (fs.existsSync(studioApp)) {
          appPath = studioApp;
        }
      }

      if (!appPath) {
        throw new Error("Could not find Roblox app bundle in " + installPath);
      }

      const child = spawn("open", [appPath], {
        detached: true,
        stdio: "ignore",
      });
      child.unref();
    } else {
      const playerExe = path.join(installPath, "RobloxPlayerBeta.exe");
      const studioExe = path.join(installPath, "RobloxStudioBeta.exe");

      let exePath = "";
      if (fs.existsSync(playerExe)) {
        exePath = playerExe;
      } else if (fs.existsSync(studioExe)) {
        exePath = studioExe;
      } else {
        throw new Error("Could not find executable in " + installPath);
      }

      const child = spawn(exePath, [], {
        detached: true,
        cwd: installPath,
        stdio: "ignore",
      });
      child.unref();
    }
  }

  static async uninstall(installPath: string): Promise<void> {
    if (fs.existsSync(installPath)) {
      await fs.promises.rm(installPath, { recursive: true, force: true });
    }
  }

  static async openFolder(installPath: string): Promise<void> {
    await shell.openPath(installPath);
  }

  static async checkForUpdates(
    binaryType: string,
    currentVersionHash: string,
  ): Promise<{ hasUpdate: boolean; latestVersion: string }> {
    const history = await this.getDeployHistory(true);
    const versions = history[binaryType];

    if (!versions || versions.length === 0) {
      throw new Error(`No version history found for ${binaryType}`);
    }

    const latestVersion = versions[0];
    return {
      hasUpdate: latestVersion !== currentVersionHash,
      latestVersion,
    };
  }

  static async getFFlags(installPath: string): Promise<Record<string, any>> {
    const { file: clientSettingsPath } = getClientSettingsPaths(installPath);
    try {
      if (!fs.existsSync(clientSettingsPath)) {
        return {};
      }
      const content = await fs.promises.readFile(clientSettingsPath, "utf8");
      const raw = JSON.parse(content);
      return fflagsSchema.parse(raw);
    } catch (e) {
      console.error("Failed to read FFlags", e);
      return {};
    }
  }

  static async setFFlags(
    installPath: string,
    flags: Record<string, any>,
  ): Promise<void> {
    fflagsSchema.parse(flags);

    const { dir: clientSettingsDir, file: clientSettingsPath } =
      getClientSettingsPaths(installPath);
    try {
      if (!fs.existsSync(clientSettingsDir)) {
        await fs.promises.mkdir(clientSettingsDir, { recursive: true });
      }
      await fs.promises.writeFile(
        clientSettingsPath,
        JSON.stringify(flags, null, 4),
        "utf8",
      );
    } catch (e) {
      console.error("Failed to write FFlags", e);
      throw e;
    }
  }

  static async installFont(
    installPath: string,
    fontPath: string,
  ): Promise<void> {
    if (!fs.existsSync(fontPath)) {
      throw new Error("Font file not found: " + fontPath);
    }

    const fontsDir = path.join(installPath, "content", "fonts");
    if (!fs.existsSync(fontsDir)) {
      if (process.platform === "darwin") {
        const macFontsDir = path.join(
          installPath,
          "Contents",
          "Resources",
          "content",
          "fonts",
        );
        if (fs.existsSync(macFontsDir)) {
          await this.replaceFontsInDir(macFontsDir, fontPath);
          return;
        }
      }
      throw new Error("Roblox fonts directory not found in " + installPath);
    }

    await this.replaceFontsInDir(fontsDir, fontPath);
  }

  private static async replaceFontsInDir(
    fontsDir: string,
    sourceFontPath: string,
  ): Promise<void> {
    const targetFonts = [
      "Arial.ttf",
      "SourceSansPro-Regular.ttf",
      "SourceSansPro-Bold.ttf",
      "SourceSansPro-Light.ttf",
      "SourceSansPro-SemiBold.ttf",
    ];

    for (const target of targetFonts) {
      await fs.promises.copyFile(sourceFontPath, path.join(fontsDir, target));
    }
  }

  static async installCursor(
    installPath: string,
    cursorPath: string,
  ): Promise<void> {
    if (!fs.existsSync(cursorPath)) {
      throw new Error("Cursor file not found: " + cursorPath);
    }

    let cursorDir = path.join(
      installPath,
      "content",
      "textures",
      "Cursors",
      "KeyboardMouse",
    );

    if (process.platform === "darwin") {
      const macCursorDir = path.join(
        installPath,
        "Contents",
        "Resources",
        "content",
        "textures",
        "Cursors",
        "KeyboardMouse",
      );
      if (fs.existsSync(macCursorDir)) {
        cursorDir = macCursorDir;
      }
    }

    if (!fs.existsSync(cursorDir)) {
      throw new Error("Roblox cursor directory not found in " + installPath);
    }

    const targets = ["ArrowCursor.png", "ArrowFarCursor.png"];
    for (const target of targets) {
      await fs.promises.copyFile(cursorPath, path.join(cursorDir, target));
    }
  }

  static async setActive(installPath: string): Promise<void> {
    if (process.platform === "darwin") {
      console.log(
        "[RobloxInstallService] setActive is not supported on macOS - using system Roblox",
      );
      return;
    }

    const playerExe = path.join(installPath, "RobloxPlayerBeta.exe");
    if (!fs.existsSync(playerExe)) {
      throw new Error("RobloxPlayerBeta.exe not found in " + installPath);
    }

    // We need to set registry keys for roblox-player protocol
    // HKCU\Software\Classes\roblox-player
    //   (Default) = "URL: Roblox Protocol"
    //   "URL Protocol" = ""
    //   DefaultIcon
    //     (Default) = "path\to\exe,0"
    //   shell\open\command
    //     (Default) = "path\to\exe" "%1"

    const cmds = [
      [
        "add",
        "HKCU\\Software\\Classes\\roblox-player",
        "/ve",
        "/t",
        "REG_SZ",
        "/d",
        "URL: Roblox Protocol",
        "/f",
      ],
      [
        "add",
        "HKCU\\Software\\Classes\\roblox-player",
        "/v",
        "URL Protocol",
        "/t",
        "REG_SZ",
        "/d",
        "",
        "/f",
      ],
      [
        "add",
        "HKCU\\Software\\Classes\\roblox-player\\DefaultIcon",
        "/ve",
        "/t",
        "REG_SZ",
        "/d",
        `${playerExe},0`,
        "/f",
      ],
      [
        "add",
        "HKCU\\Software\\Classes\\roblox-player\\shell\\open\\command",
        "/ve",
        "/t",
        "REG_SZ",
        "/d",
        `"${playerExe}" "%1"`,
        "/f",
      ],
    ];

    for (const args of cmds) {
      await new Promise<void>((resolve, reject) => {
        const child = spawn("reg", args, {
          stdio: "ignore",
          windowsHide: true,
        });
        child.on("close", (code) => {
          if (code === 0) resolve();
          else reject(new Error(`reg command failed with code ${code}`));
        });
        child.on("error", reject);
      });
    }
  }

  static async removeActive(): Promise<void> {
    if (process.platform === "darwin") {
      return;
    }

    const keyPath = "HKCU\\Software\\Classes\\roblox-player";

    return new Promise<void>((resolve) => {
      const child = spawn("reg", ["delete", keyPath, "/f"], {
        stdio: "ignore",
        windowsHide: true,
      });
      child.on("close", (code) => {
        if (code !== 0) {
          console.warn(
            `[RobloxInstallService] Registry delete exited with code ${code}`,
          );
        }
        resolve();
      });
      child.on("error", (err) => {
        console.error("Failed to delete registry key", err);
        resolve();
      });
    });
  }

  static async getActiveInstallPath(): Promise<string | null> {
    if (process.platform === "darwin") {
      return null;
    }

    return new Promise((resolve) => {
      const child = spawn(
        "reg",
        ["query", "HKCU\\Software\\Classes\\roblox-player\\DefaultIcon", "/ve"],
        { windowsHide: true },
      );
      let stdout = "";

      child.stdout.on("data", (data) => {
        stdout += data.toString();
      });

      child.on("close", (code) => {
        if (code !== 0) {
          resolve(null);
          return;
        }

        // Output looks like:
        // HKEY_CURRENT_USER\Software\Classes\roblox-player\DefaultIcon
        //    (Default)    REG_SZ    C:\Path\To\RobloxPlayerBeta.exe,0

        const match = stdout.match(/REG_SZ\s+([^\r\n]+),0/);
        if (match && match[1]) {
          const exePath = match[1].trim();

          resolve(path.dirname(exePath));
        } else {
          resolve(null);
        }
      });

      child.on("error", (err) => {
        console.error("[RobloxInstallService] Registry query error:", err);
        resolve(null);
      });
    });
  }

  static async launchWithProtocol(
    installPath: string,
    protocolUrl: string,
  ): Promise<void> {
    if (process.platform === "darwin") {
      const openArgs: string[] = [];

      // If a specific app path is provided, attempt to target it
      if (installPath && fs.existsSync(installPath)) {
        let appPath = installPath.endsWith(".app") ? installPath : "";

        if (!appPath) {
          const playerApp = path.join(installPath, "RobloxPlayer.app");
          const studioApp = path.join(installPath, "RobloxStudio.app");
          const legacyApp = path.join(installPath, "Roblox.app");

          if (fs.existsSync(playerApp)) appPath = playerApp;
          else if (fs.existsSync(studioApp)) appPath = studioApp;
          else if (fs.existsSync(legacyApp)) appPath = legacyApp;
        }

        if (appPath && fs.existsSync(appPath)) {
          openArgs.push("-a", appPath);
        }
      }

      openArgs.push(protocolUrl);

      const child = spawn("open", openArgs, {
        detached: true,
        stdio: "ignore",
      });
      child.unref();
    } else {
      const playerExe = path.join(installPath, "RobloxPlayerBeta.exe");
      if (!fs.existsSync(playerExe)) {
        throw new Error("RobloxPlayerBeta.exe not found in " + installPath);
      }

      const child = spawn(playerExe, [protocolUrl], {
        detached: true,
        cwd: installPath,
        stdio: "ignore",
      });
      child.unref();
    }
  }

  /**
   * Detects default Roblox installations from the standard Roblox Versions directory
   * Windows: C:\Users\<user>\AppData\Local\Roblox\Versions\
   * macOS: /Applications/Roblox.app or ~/Applications/Roblox.app
   */
  static async detectDefaultInstallations(): Promise<DetectedInstallation[]> {
    const detected: DetectedInstallation[] = [];

    try {
      if (process.platform === "darwin") {
        const possiblePaths = [
          "/Applications/Roblox.app",
          path.join(os.homedir(), "Applications", "Roblox.app"),
        ];

        for (const robloxAppPath of possiblePaths) {
          if (fs.existsSync(robloxAppPath)) {
            const version = readMacBundleVersion(robloxAppPath) || "system";
            const execPath = path.join(
              robloxAppPath,
              "Contents",
              "MacOS",
              "RobloxPlayer",
            );
            detected.push({
              path: robloxAppPath,
              version,
              binaryType: "MacPlayer",
              exePath: execPath,
            });
            break;
          }
        }
        return detected;
      }

      const robloxVersionsPath = path.join(
        os.homedir(),
        "AppData",
        "Local",
        "Roblox",
        "Versions",
      );

      if (!fs.existsSync(robloxVersionsPath)) {
        return detected;
      }

      const entries = await fs.promises.readdir(robloxVersionsPath, {
        withFileTypes: true,
      });

      for (const entry of entries) {
        if (!entry.isDirectory() || !entry.name.startsWith("version-")) {
          continue;
        }

        const versionDir = path.join(robloxVersionsPath, entry.name);
        const versionHash = entry.name.replace("version-", "");

        const playerExe = path.join(versionDir, "RobloxPlayerBeta.exe");
        if (fs.existsSync(playerExe)) {
          detected.push({
            path: versionDir,
            version: versionHash,
            binaryType: "WindowsPlayer",
            exePath: playerExe,
          });
          continue;
        }

        const studioExe = path.join(versionDir, "RobloxStudioBeta.exe");
        if (fs.existsSync(studioExe)) {
          detected.push({
            path: versionDir,
            version: versionHash,
            binaryType: "WindowsStudio",
            exePath: studioExe,
          });
        }
      }
    } catch (e) {
      console.error(
        "[RobloxInstallService] Failed to detect default installations:",
        e,
      );
    }

    return detected;
  }
}

import { shell } from "electron";
import { exec } from "child_process";
import { promisify } from "util";
import { randomUUID } from "crypto";
import { RobloxAuthService } from "../auth/RobloxAuthService";
import { RobloxInstallService } from "./InstallService";
import { cookieRefreshService } from "../auth/CookieRefreshService";
import { RobloxUserService } from "../users/UserService";
import { storageService } from "../system/StorageService";

import { ProcessMonitor } from "../watcher/ProcessMonitor";

const execAsync = promisify(exec);

export class RobloxLauncherService {
  public static activeLaunches = new Map<string, string>(); // browserTrackerId -> username

  private static async getRobloxProcessCount(): Promise<number> {
    try {
      const pids = await ProcessMonitor.getRobloxProcessPids();
      return pids.length;
    } catch (error) {
      return 0;
    }
  }

  private static async syncFFlags(installPath: string): Promise<void> {
    try {
      const existingFlags = await RobloxInstallService.getFFlags(installPath);
      const settings = storageService.getRobloxSettings();

      const mergedFlags = { ...existingFlags };

      // Map global settings to FFlags
      if (settings.useDirectX12) {
        mergedFlags["FFlagDebugGraphicsPreferD3D11"] = "True";
      }

      if (settings.lowEndGraphics) {
        mergedFlags["DFIntDebugFRMQualityLevelOverride"] = 1;
        mergedFlags["FIntRenderShadowIntensity"] = 0;
        mergedFlags["FFlagDisablePostFx"] = "True";
      }

      if (settings.framerateCapEnabled && settings.framerateCapValue) {
        mergedFlags["DFIntTaskSchedulerTargetFps"] = settings.framerateCapValue;
      }

      await RobloxInstallService.setFFlags(installPath, mergedFlags);
    } catch (err) {
      console.error("[LauncherService] Failed to sync FFlags:", err);
    }
  }

  static async launchGame(
    cookie: string,
    placeId: number | string,
    jobId?: string,
    friendId?: string | number,
    installPath?: string,
  ) {
    try {
      // getAuthenticationTicket automatically handles CSRF validation and retry.
      // We pass an empty string initially, which triggers a 403, grabs the token, and retries.
      const ticket = await RobloxAuthService.getAuthenticationTicket(
        cookie,
        "",
      );

      const nowMs = Date.now();
      const browserTrackerId =
        Date.now().toString() + Math.floor(Math.random() * 10000);
      const joinAttemptId = randomUUID();

      let placeLauncherUrl: string;

      if (friendId) {
        placeLauncherUrl =
          `https://www.roblox.com/Game/PlaceLauncher.ashx?` +
          `request=RequestFollowUser` +
          `&browserTrackerId=${browserTrackerId}` +
          `&userId=${friendId}` +
          `&isPlayTogetherGame=false` +
          `&joinAttemptId=${joinAttemptId}` +
          `&joinAttemptOrigin=followUser`;
      } else if (jobId) {
        placeLauncherUrl =
          `https://www.roblox.com/Game/PlaceLauncher.ashx?` +
          `request=RequestGameJob` +
          `&browserTrackerId=${browserTrackerId}` +
          `&placeId=${placeId}` +
          `&gameId=${jobId}` +
          `&isPlayTogetherGame=false` +
          `&joinAttemptId=${joinAttemptId}` +
          `&joinAttemptOrigin=publicServerListJoin`;
      } else {
        placeLauncherUrl =
          `https://www.roblox.com/Game/PlaceLauncher.ashx?` +
          `request=RequestGame` +
          `&browserTrackerId=${browserTrackerId}` +
          `&placeId=${placeId}` +
          `&isPlayTogetherGame=false` +
          `&joinAttemptId=${joinAttemptId}` +
          `&joinAttemptOrigin=PlayButton`;
      }

      const protocolLaunchCommand =
        `roblox-player:1+launchmode:play` +
        `+gameinfo:${ticket}` +
        `+launchtime:${nowMs}` +
        `+placelauncherurl:${encodeURIComponent(placeLauncherUrl)}` +
        `+browsertrackerid:${browserTrackerId}` +
        `+robloxLocale:en_us` +
        `+gameLocale:en_us` +
        `+channel:` +
        `+LaunchExp:InApp`;

      const initialCount = await this.getRobloxProcessCount();

      if (installPath) {
        await this.syncFFlags(installPath);
        await RobloxInstallService.launchWithProtocol(
          installPath,
          protocolLaunchCommand,
        );
      } else {
        // No install path specified - use system default via protocol handler
        // On Windows, try to find a default installation first for multi-instance support
        if (process.platform === "win32") {
          try {
            const installations =
              await RobloxInstallService.detectDefaultInstallations();
            if (installations.length > 0) {
              await this.syncFFlags(installations[0].path);
              await RobloxInstallService.launchWithProtocol(
                installations[0].path,
                protocolLaunchCommand,
              );
            } else {
              // Fallback to protocol handler if no install found
              await shell.openExternal(protocolLaunchCommand);
            }
          } catch (error) {
            // Fallback to protocol handler on error
            await shell.openExternal(protocolLaunchCommand);
          }
        } else {
          await shell.openExternal(protocolLaunchCommand);
        }
      }

      // Poll for process start in background - don't block the caller
      // This allows multiple accounts to launch concurrently
      const pollForProcess = async () => {
        const startTime = Date.now();
        const timeout = 30000;

        while (Date.now() - startTime < timeout) {
          await new Promise((resolve) => setTimeout(resolve, 500));
          const currentCount = await this.getRobloxProcessCount();

          if (currentCount > initialCount) {
            return true;
          }
        }
        return false;
      };

      // Fire-and-forget process polling (don't await - return immediately)
      pollForProcess().catch((err) =>
        console.warn("[LauncherService] Process poll error:", err),
      );

      // Register the launch for window renaming
      RobloxUserService.getAuthenticatedUser(cookie)
        .then((user) => {
          if (user && user.name) {
            this.activeLaunches.set(browserTrackerId, user.name);
            // Limit map size to prevent memory leaks
            if (this.activeLaunches.size > 100) {
              const keys = Array.from(this.activeLaunches.keys());
              for (let i = 0; i < 50; i++) this.activeLaunches.delete(keys[i]);
            }
          }
        })
        .catch(() => {});

      // Return success immediately after sending the launch command
      // The game may still be starting up
      return { success: true };
    } catch (error: any) {
      console.error("Failed to launch Roblox:", error);
      throw new Error(`Failed to launch Roblox: ${error.message}`);
    }
  }

  /**
   * Launch a private server with access code
   * Based on C# JoinServer logic for private servers
   */
  static async launchPrivateServer(
    cookie: string,
    placeId: number | string,
    accessCode: string,
    linkCode?: string,
    installPath?: string,
  ) {
    try {
      // getAuthenticationTicket handles CSRF internally
      const ticket = await RobloxAuthService.getAuthenticationTicket(
        cookie,
        "",
      );

      const nowMs = Date.now();
      const browserTrackerId =
        Date.now().toString() + Math.floor(Math.random() * 10000);
      const joinAttemptId = randomUUID();

      // Private server uses RequestPrivateGame
      const placeLauncherUrl =
        `https://www.roblox.com/Game/PlaceLauncher.ashx?` +
        `request=RequestPrivateGame` +
        `&browserTrackerId=${browserTrackerId}` +
        `&placeId=${placeId}` +
        `&accessCode=${encodeURIComponent(accessCode)}` +
        (linkCode ? `&linkCode=${encodeURIComponent(linkCode)}` : "") +
        `&isPlayTogetherGame=false` +
        `&joinAttemptId=${joinAttemptId}` +
        `&joinAttemptOrigin=joinPrivateGameButton`;

      const protocolLaunchCommand =
        `roblox-player:1+launchmode:play` +
        `+gameinfo:${ticket}` +
        `+launchtime:${nowMs}` +
        `+placelauncherurl:${encodeURIComponent(placeLauncherUrl)}` +
        `+browsertrackerid:${browserTrackerId}` +
        `+robloxLocale:en_us` +
        `+gameLocale:en_us` +
        `+channel:` +
        `+LaunchExp:InApp`;

      const initialCount = await this.getRobloxProcessCount();

      if (installPath) {
        await this.syncFFlags(installPath);
        await RobloxInstallService.launchWithProtocol(
          installPath,
          protocolLaunchCommand,
        );
      } else {
        if (process.platform === "win32") {
          try {
            const installations =
              await RobloxInstallService.detectDefaultInstallations();
            if (installations.length > 0) {
              await this.syncFFlags(installations[0].path);
              await RobloxInstallService.launchWithProtocol(
                installations[0].path,
                protocolLaunchCommand,
              );
            } else {
              await shell.openExternal(protocolLaunchCommand);
            }
          } catch (error) {
            await shell.openExternal(protocolLaunchCommand);
          }
        } else {
          await shell.openExternal(protocolLaunchCommand);
        }
      }

      // Poll for process start in background - don't block the caller
      const pollForProcess = async () => {
        const startTime = Date.now();
        const timeout = 30000;

        while (Date.now() - startTime < timeout) {
          await new Promise((resolve) => setTimeout(resolve, 500));
          const currentCount = await this.getRobloxProcessCount();

          if (currentCount > initialCount) {
            return true;
          }
        }
        return false;
      };

      // Fire-and-forget process polling
      pollForProcess().catch((err) =>
        console.warn(
          "[LauncherService] Private server process poll error:",
          err,
        ),
      );

      // Register the launch for window renaming
      RobloxUserService.getAuthenticatedUser(cookie)
        .then((user) => {
          if (user && user.name) {
            this.activeLaunches.set(browserTrackerId, user.name);
            if (this.activeLaunches.size > 100) {
              const keys = Array.from(this.activeLaunches.keys());
              for (let i = 0; i < 50; i++) this.activeLaunches.delete(keys[i]);
            }
          }
        })
        .catch(() => {});

      // Return success immediately
      return { success: true };
    } catch (error: any) {
      console.error("Failed to launch private server:", error);
      throw new Error(`Failed to launch private server: ${error.message}`);
    }
  }

  /**
   * Extract access code from private server link code
   * Makes request to Roblox to get the actual access code from link code
   */
  static async extractAccessCodeFromLinkCode(
    cookie: string,
    placeId: number | string,
    linkCode: string,
  ): Promise<string> {
    try {
      // This would require making an HTTP request to Roblox
      // For now, return the link code as-is (Roblox may accept it directly)
      // In production, you'd need to parse the response from PlaceLauncher to extract the access code
      return linkCode;
    } catch (error: any) {
      console.error("Failed to extract access code from link code:", error);
      throw new Error(`Failed to extract access code: ${error.message}`);
    }
  }

  /**
   * Launch game with private server link
   * Extracts link code from URL, gets access code, and launches
   */
  static async launchWithPrivateServerLink(
    cookie: string,
    placeId: number | string,
    privateServerUrl: string,
    installPath?: string,
  ) {
    try {
      // Extract link code from the private server invite URL
      // Format: https://www.roblox.com/games/[placeId]?privateServerLinkCode=[linkCode]
      const linkCodeMatch = privateServerUrl.match(
        /privateServerLinkCode=([^&]+)/,
      );
      if (!linkCodeMatch) {
        throw new Error(
          "Invalid private server link - missing privateServerLinkCode parameter",
        );
      }

      const linkCode = decodeURIComponent(linkCodeMatch[1]);

      // Use link code as access code (simpler approach)
      // In a more complex implementation, you'd make a request to extract the actual access code
      return await this.launchPrivateServer(
        cookie,
        placeId,
        linkCode,
        linkCode,
        installPath,
      );
    } catch (error: any) {
      console.error("Failed to launch with private server link:", error);
      throw new Error(
        `Failed to launch with private server link: ${error.message}`,
      );
    }
  }
}

import { ipcMain } from "electron";
import { macroService, Macro } from "./MacroService";

export function registerMacroHandlers(): void {
  console.log("[MacroController] Registering handlers...");

  // Start recording
  ipcMain.handle("macro:start-recording", () => {
    console.log("[MacroController] start-recording called");
    macroService.startRecording();
    return { success: true };
  });

  // Stop recording
  ipcMain.handle("macro:stop-recording", () => {
    const events = macroService.stopRecording();
    return { success: true, events };
  });

  // Record mouse move
  ipcMain.handle("macro:record-mouse-move", (_event, x: number, y: number) => {
    macroService.recordMouseMove(x, y);
    return { success: true };
  });

  // Record click
  ipcMain.handle("macro:record-click", (_event, button?: string) => {
    macroService.recordClick((button || "left") as any);
    return { success: true };
  });

  // Record key press
  ipcMain.handle("macro:record-keypress", (_event, key: string) => {
    macroService.recordKeyPress(key);
    return { success: true };
  });

  // Save macro
  ipcMain.handle(
    "macro:save",
    (_event, name: string, events: any[], description?: string) => {
      const macro = macroService.saveMacro(name, events, description);
      return { success: true, macro };
    },
  );

  // Load macro
  ipcMain.handle("macro:load", (_event, macroId: string) => {
    const macro = macroService.loadMacro(macroId);
    return macro
      ? { success: true, macro }
      : { success: false, error: "Macro not found" };
  });

  // List macros
  ipcMain.handle("macro:list", () => {
    const macros = macroService.listMacros();
    return { success: true, macros };
  });

  // Delete macro
  ipcMain.handle("macro:delete", (_event, macroId: string) => {
    const success = macroService.deleteMacro(macroId);
    return { success };
  });

  // Play macro
  ipcMain.handle("macro:play", (_event, macroId: string, speed?: number) => {
    const macro = macroService.loadMacro(macroId);
    if (!macro) {
      return { success: false, error: "Macro not found" };
    }

    macroService.playMacro(macro, undefined, speed || 1.0).catch((err) => {
      console.error("[Macro] Playback error:", err);
    });

    return { success: true };
  });

  // Get recording status
  ipcMain.handle("macro:is-recording", () => {
    return { isRecording: macroService.isCurrentlyRecording() };
  });

  // Get recording progress
  ipcMain.handle("macro:get-recording-progress", () => {
    return macroService.getRecordingProgress();
  });

  console.log("[MacroController] All handlers registered successfully");
}

import { EventEmitter } from "events";
import { writeFileSync, readFileSync, existsSync } from "fs";
import { join } from "path";
import { getDataFile } from "../../utils/paths";

export type MacroEvent = {
  type: "mousemove" | "click" | "keypress";
  x?: number;
  y?: number;
  button?: "left" | "right" | "middle";
  key?: string;
  delay?: number;
};

export type Macro = {
  id: string;
  name: string;
  description?: string;
  events: MacroEvent[];
  createdAt: number;
  updatedAt: number;
  timing: {
    totalDuration: number;
    eventCount: number;
  };
};

export class MacroService extends EventEmitter {
  private isRecording = false;
  private currentEvents: MacroEvent[] = [];
  private recordingStartTime = 0;
  private lastEventTime = 0;
  private macrosDir = getDataFile("macros");
  private builtInMacrosInitialized = false;

  constructor() {
    super();
    this.ensureMacrosDir();
    // Don't initialize built-in macros here - do it lazily on first access
  }

  private ensureMacrosDir() {
    const fs = require("fs");
    if (!fs.existsSync(this.macrosDir)) {
      fs.mkdirSync(this.macrosDir, { recursive: true });
    }
  }

  /**
   * Built-in macro definitions for common Roblox actions
   * Work on all platforms including macOS where recording doesn't work well
   */
  private static readonly BUILT_IN_MACROS = [
    {
      name: "Jump",
      description: "Press spacebar to jump",
      events: [
        { type: "keypress" as const, key: "space", delay: 50 },
        { type: "keypress" as const, key: "space", delay: 0 },
      ],
    },
    {
      name: "Move Forward",
      description: "Press W to move forward",
      events: [
        { type: "keypress" as const, key: "w", delay: 100 },
        { type: "keypress" as const, key: "w", delay: 0 },
      ],
    },
    {
      name: "Move Back",
      description: "Press S to move back",
      events: [
        { type: "keypress" as const, key: "s", delay: 100 },
        { type: "keypress" as const, key: "s", delay: 0 },
      ],
    },
    {
      name: "Move Left",
      description: "Press A to move left",
      events: [
        { type: "keypress" as const, key: "a", delay: 100 },
        { type: "keypress" as const, key: "a", delay: 0 },
      ],
    },
    {
      name: "Move Right",
      description: "Press D to move right",
      events: [
        { type: "keypress" as const, key: "d", delay: 100 },
        { type: "keypress" as const, key: "d", delay: 0 },
      ],
    },
    {
      name: "Sprint",
      description: "Hold Shift for sprint",
      events: [
        { type: "keypress" as const, key: "shift", delay: 500 },
        { type: "keypress" as const, key: "shift", delay: 0 },
      ],
    },
    {
      name: "Crouch",
      description: "Press C to crouch",
      events: [
        { type: "keypress" as const, key: "c", delay: 100 },
        { type: "keypress" as const, key: "c", delay: 0 },
      ],
    },
    {
      name: "Emote Dance 1",
      description: "Press E for first emote",
      events: [
        { type: "keypress" as const, key: "e", delay: 100 },
        { type: "keypress" as const, key: "e", delay: 0 },
      ],
    },
  ];

  /**
   * Initialize built-in macros for common Roblox actions (lazy initialization)
   * CRITICAL FIX: Reads filesystem directly instead of calling listMacros() to avoid infinite recursion
   */
  private ensureBuiltInMacros(): void {
    if (this.builtInMacrosInitialized) {
      return;
    }

    const fs = require("fs");
    const existingNames = new Set<string>();

    // Read existing macro names directly from filesystem (NOT via listMacros())
    if (fs.existsSync(this.macrosDir)) {
      try {
        const files = fs.readdirSync(this.macrosDir);
        for (const file of files) {
          if (file.endsWith(".json")) {
            try {
              const data = readFileSync(join(this.macrosDir, file), "utf-8");
              const macro = JSON.parse(data) as Macro;
              existingNames.add(macro.name);
            } catch (err) {
              // Silently ignore parse errors
            }
          }
        }
      } catch (err) {
        console.warn("[Macro] Error reading macros directory:", err);
      }
    }

    // Save any missing built-in macros
    for (const builtIn of MacroService.BUILT_IN_MACROS) {
      if (!existingNames.has(builtIn.name)) {
        console.log(`[Macro] Creating built-in macro: ${builtIn.name}`);
        this.saveMacro(builtIn.name, builtIn.events, builtIn.description);
      }
    }

    this.builtInMacrosInitialized = true;
  }

  /**
   * Start recording a macro
   */
  startRecording(): void {
    if (this.isRecording) {
      console.warn("[Macro] Already recording");
      return;
    }

    this.isRecording = true;
    this.currentEvents = [];
    this.recordingStartTime = Date.now();
    this.lastEventTime = this.recordingStartTime;

    console.log("[Macro] Recording started");
    this.emit("recording-started");
  }

  /**
   * Stop recording and return recorded events
   */
  stopRecording(): MacroEvent[] {
    if (!this.isRecording) {
      console.warn("[Macro] Not recording");
      return [];
    }

    this.isRecording = false;
    const events = [...this.currentEvents];
    this.currentEvents = [];

    console.log(`[Macro] Recording stopped with ${events.length} events`);
    this.emit("recording-stopped", events);

    return events;
  }

  /**
   * Record a mouse movement
   */
  recordMouseMove(x: number, y: number): void {
    if (!this.isRecording) return;

    const now = Date.now();
    const delay = Math.max(0, now - this.lastEventTime);
    this.lastEventTime = now;

    this.currentEvents.push({
      type: "mousemove",
      x,
      y,
      delay,
    });
  }

  /**
   * Record a mouse click
   */
  recordClick(button: "left" | "right" | "middle" = "left"): void {
    if (!this.isRecording) return;

    const now = Date.now();
    const delay = Math.max(0, now - this.lastEventTime);
    this.lastEventTime = now;

    this.currentEvents.push({
      type: "click",
      button,
      delay,
    });
  }

  /**
   * Record a key press
   */
  recordKeyPress(key: string): void {
    if (!this.isRecording) return;

    const now = Date.now();
    const delay = Math.max(0, now - this.lastEventTime);
    this.lastEventTime = now;

    this.currentEvents.push({
      type: "keypress",
      key,
      delay,
    });
  }

  /**
   * Save a macro to file
   */
  saveMacro(name: string, events: MacroEvent[], description?: string): Macro {
    const id = `macro_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const now = Date.now();

    const totalDuration = events.reduce(
      (sum, evt) => sum + (evt.delay || 0),
      0,
    );

    const macro: Macro = {
      id,
      name,
      description,
      events,
      createdAt: now,
      updatedAt: now,
      timing: {
        totalDuration,
        eventCount: events.length,
      },
    };

    const filePath = join(this.macrosDir, `${id}.json`);
    writeFileSync(filePath, JSON.stringify(macro, null, 2));

    console.log(
      `[Macro] Saved macro "${name}" (${events.length} events, ${totalDuration}ms)`,
    );
    this.emit("macro-saved", macro);

    return macro;
  }

  /**
   * Load a macro by ID
   */
  loadMacro(macroId: string): Macro | null {
    const filePath = join(this.macrosDir, `${macroId}.json`);

    if (!existsSync(filePath)) {
      console.warn(`[Macro] Macro not found: ${macroId}`);
      return null;
    }

    try {
      const data = readFileSync(filePath, "utf-8");
      const macro = JSON.parse(data) as Macro;
      console.log(`[Macro] Loaded macro "${macro.name}"`);
      return macro;
    } catch (err) {
      console.error(`[Macro] Failed to load macro:`, err);
      return null;
    }
  }

  /**
   * List all saved macros (including built-in macros on first call)
   */
  listMacros(): Macro[] {
    // Ensure built-in macros are created on first access
    this.ensureBuiltInMacros();

    const fs = require("fs");

    if (!fs.existsSync(this.macrosDir)) {
      return [];
    }

    const files = fs.readdirSync(this.macrosDir);
    const macros: Macro[] = [];

    for (const file of files) {
      if (file.endsWith(".json")) {
        try {
          const data = readFileSync(join(this.macrosDir, file), "utf-8");
          const macro = JSON.parse(data) as Macro;
          macros.push(macro);
        } catch (err) {
          console.error(`[Macro] Failed to parse ${file}:`, err);
        }
      }
    }

    return macros;
  }

  /**
   * Delete a macro by ID
   */
  deleteMacro(macroId: string): boolean {
    const fs = require("fs");
    const filePath = join(this.macrosDir, `${macroId}.json`);

    if (!fs.existsSync(filePath)) {
      console.warn(`[Macro] Macro not found: ${macroId}`);
      return false;
    }

    try {
      fs.unlinkSync(filePath);
      console.log(`[Macro] Deleted macro: ${macroId}`);
      this.emit("macro-deleted", macroId);
      return true;
    } catch (err) {
      console.error(`[Macro] Failed to delete macro:`, err);
      return false;
    }
  }

  /**
   * Play a macro to multiple windows
   * Note: Requires robotjs or similar library for actual input simulation
   */
  async playMacro(
    macro: Macro,
    targetWindowIds?: number[],
    speed: number = 1.0,
  ): Promise<void> {
    console.log(
      `[Macro] Starting playback: "${macro.name}" at ${speed}x speed`,
    );
    this.emit("macro-started", macro.id);

    try {
      for (const event of macro.events) {
        const delayMs = Math.max(0, Math.round((event.delay || 0) / speed));

        // Simulate the input
        await this.simulateInput(event);

        // Wait before next event
        if (delayMs > 0) {
          await new Promise((resolve) => setTimeout(resolve, delayMs));
        }
      }

      console.log(`[Macro] Completed playback: "${macro.name}"`);
      this.emit("macro-completed", macro.id);
    } catch (err) {
      console.error(`[Macro] Playback error:`, err);
      this.emit("macro-error", { macroId: macro.id, error: String(err) });
    }
  }

