  private static async runCpuOptimization(pids: number[]) {
    try {
      console.log(
        `[PerformanceService] Optimizing CPU Affinity for ${pids.length} processes...`,
      );

      // other project inspired CPU Affinity & QoS adjustment.
      // - Disables CPU Boost on process by setting Power Throttling / Priority
      // - Sets Process Affinity to leave system headroom
      const psScript = `
Add-Type @"
  using System;
  using System.Runtime.InteropServices;
  public class Win32 {
    [DllImport("kernel32.dll")]
    public static extern bool SetProcessAffinityMask(IntPtr hProcess, UIntPtr dwProcessAffinityMask);
    [DllImport("kernel32.dll")]
    public static extern bool GetProcessAffinityMask(IntPtr hProcess, out UIntPtr lpProcessAffinityMask, out UIntPtr lpSystemAffinityMask);
    [DllImport("kernel32.dll")]
    public static extern bool SetPriorityClass(IntPtr hProcess, uint dwPriorityClass);
  }
"@
$pids = @(${pids.join(",")})
$IDLE_PRIORITY_CLASS = 0x00000040

foreach ($p in $pids) {
  try {
    $proc = Get-Process -Id $p -ErrorAction Stop
    [Win32]::SetPriorityClass($proc.Handle, $IDLE_PRIORITY_CLASS) | Out-Null

    [UIntPtr]$procMask = [UIntPtr]::Zero
    [UIntPtr]$sysMask = [UIntPtr]::Zero
    if ([Win32]::GetProcessAffinityMask($proc.Handle, [ref]$procMask, [ref]$sysMask)) {
      # Calculate logical cores. Leave at least 2 cores for system if possible (sentra logic).
      $sysMaskVal = $sysMask.ToUInt64()
      $logicalCores = 0
      for ($i = 0; $i -lt 64; $i++) {
        if (($sysMaskVal -band (1 -shl $i)) -ne 0) {
          $logicalCores++
        }
      }

      $useCores = $logicalCores
      if ($logicalCores -gt 4) {
        $useCores = $logicalCores - 2
      } elseif ($logicalCores -gt 2) {
        $useCores = $logicalCores - 1
      }

      if ($useCores -lt $logicalCores) {
        $newMask = 0
        for ($i = 0; $i -lt $useCores; $i++) {
          $newMask = $newMask -bor (1 -shl $i)
        }
        [Win32]::SetProcessAffinityMask($proc.Handle, [UIntPtr]$newMask) | Out-Null
      }
    }
  } catch {}
}
`;
      await execAsync(
        `powershell -NoProfile -NonInteractive -Command "${psScript.replace(/"/g, '\\"')}"`,
      );
    } catch (err) {
      console.error("[PerformanceService] CPU Optimization error:", err);
    }
  }

  private static async runWindowRenamer(pids: number[]) {
    try {
      console.log(
        `[PerformanceService] Renaming windows for ${pids.length} processes...`,
      );

      const psScript = `
Add-Type @"
  using System;
  using System.Runtime.InteropServices;
  public class Win32 {
    [DllImport("user32.dll", SetLastError = true)]
    public static extern IntPtr GetWindowThreadProcessId(IntPtr hWnd, out uint processId);
    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc enumProc, IntPtr lParam);
    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    public static extern bool SetWindowText(IntPtr hWnd, string lpString);
    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  }
"@

$pids = @(${pids.join(",")})
$browserTrackerMap = @{}

# Try to extract browserTrackerId from command line
foreach ($p in $pids) {
  try {
    $wmi = Get-CimInstance Win32_Process -Filter "ProcessId = $p"
    if ($wmi) {
      $cmd = $wmi.CommandLine
      if ($cmd -match 'browsertrackerid:(\\d+)') {
        $browserTrackerMap["$p"] = $matches[1]
      }
    }
  } catch {}
}

$browserTrackerMap | ConvertTo-Json -Compress
`;
      const { stdout } = await execAsync(
        `powershell -NoProfile -NonInteractive -Command "${psScript.replace(/"/g, '\\"')}"`,
      );

      try {
        const trackerMap = JSON.parse(stdout.trim());

        // If trackerMap is empty, fall back to assigning recent active launches
        // to current pids in order. This helps when the commandline doesn't
        // expose the browserTrackerId for a process but we still want to
        // provide a reasonable window rename behavior.
        const entries = Object.entries(trackerMap || {});

        const pidToUsername: Record<string, string> = {};
        if (entries.length === 0) {
          const recentUsernames = Array.from(
            RobloxLauncherService.activeLaunches.values(),
          ).slice(-pids.length);
          for (let i = 0; i < pids.length; i++) {
            const pidStr = String(pids[i]);
            const username = recentUsernames[i] || null;
            if (username) pidToUsername[pidStr] = username;
          }
        } else {
          for (const [pidStr, trackerId] of entries) {
            const username = RobloxLauncherService.activeLaunches.get(
              trackerId as string,
            );
            if (username) pidToUsername[pidStr] = username;
          }
        }

        if (Object.keys(pidToUsername).length === 0) return;

        let renameScript = `
Add-Type @"
  using System;
  using System.Runtime.InteropServices;
  public class Win32 {
    [DllImport("user32.dll", SetLastError = true)]
    public static extern IntPtr GetWindowThreadProcessId(IntPtr hWnd, out uint processId);
    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc enumProc, IntPtr lParam);
    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    public static extern bool SetWindowText(IntPtr hWnd, string lpString);
    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    public static extern int GetWindowTextLength(IntPtr hWnd);
    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    public static extern int GetWindowText(IntPtr hWnd, System.Text.StringBuilder lpString, int nMaxCount);
    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  }
"@

$renameMap = @{
`;
        let hasRenames = false;
        for (const [pidStr, username] of Object.entries(pidToUsername)) {
          renameScript += `  "${pidStr}" = "${username}"\n`;
          hasRenames = true;
        }

        renameScript += `}

        [Win32]::EnumWindows({
  param([IntPtr]$hWnd, [IntPtr]$lParam)
  [uint]$processId = 0
  [Win32]::GetWindowThreadProcessId($hWnd, [ref]$processId)
  $pidStr = $processId.ToString()

  if ($renameMap.ContainsKey($pidStr)) {
    try {
      # Try to rename windows for this pid regardless of title length to be more robust
      [Win32]::SetWindowText($hWnd, $renameMap[$pidStr]) | Out-Null
    } catch {}
  }
  return $true
}, [IntPtr]::Zero)
`;
        if (hasRenames) {
          await execAsync(
            `powershell -NoProfile -NonInteractive -Command "${renameScript.replace(/"/g, '\\"')}"`,
          );
        }
      } catch (err) {}
    } catch (err) {
      console.error("[PerformanceService] Window Renamer error:", err);
    }
  }
}

