        this.data.watcherConfig?.clientTimeoutSeconds ?? 3600, // 1 hour default
      enableCPULimiter: this.data.watcherConfig?.enableCPULimiter ?? false,
      cpuLimitPercent: this.data.watcherConfig?.cpuLimitPercent ?? 80,
