export const ColorPickerFormat = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => {
  const {
    hue,
    saturation,
    lightness,
    mode,
    setHue,
    setSaturation,
    setLightness,
    setAlpha,
  } = useColorPicker();
  const color = Color.hsl(hue, saturation, lightness);
  const [hexValue, setHexValue] = useState(color.hex());
  const [cssValue, setCssValue] = useState(
    `rgb(${color
      .rgb()
      .array()
      .map((v) => Math.round(v))
      .join(", ")})`,
  );

  // Update local state when color changes from outside
  useEffect(() => {
    if (mode === "hex") {
      setHexValue(color.hex());
    } else if (mode === "css") {
      const rgb = color
        .rgb()
        .array()
        .map((v) => Math.round(v));
      setCssValue(`rgb(${rgb.join(", ")})`);
    } else if (mode === "hsl") {
      // For HSL mode, we don't store a separate state since we have hue, saturation, lightness
      // but we need to ensure the picker reflects the current values
    }
  }, [color, mode]);

  const handleHexChange = (value: string) => {
    setHexValue(value);
    try {
      const newColor = Color(value);
      setHue(newColor.hue());
      setSaturation(newColor.saturationl());
      setLightness(newColor.lightness());
    } catch (error) {
      console.error("Invalid hex color input:", error);
    }
  };

  const handleHexBlur = () => {
    // Reset to valid color on blur if invalid
    try {
      Color(hexValue);
    } catch (error) {
      console.error("Invalid hex color in blur:", error);
      setHexValue(color.hex());
    }
  };

  const handleRgbChange = (index: number, value: string) => {
    try {
      const num = parseInt(value);
      if (isNaN(num) || num < 0 || num > 255) return;
      const rgb = color.rgb().array();
      rgb[index] = num;
      const newColor = Color.rgb(rgb[0], rgb[1], rgb[2]);
      setHue(newColor.hue());
      setSaturation(newColor.saturationl());
      setLightness(newColor.lightness());
    } catch (error) {
      console.error("Invalid RGB color input:", error);
    }
  };

  const handleCssChange = (value: string) => {
    setCssValue(value);
    try {
      // Try to parse rgb(...) or rgba(...) format
      const match = value.match(
        /rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/,
      );
      if (match) {
        const r = parseInt(match[1]);
        const g = parseInt(match[2]);
        const b = parseInt(match[3]);
        const a = match[4] ? parseFloat(match[4]) : undefined;
        if (r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255) {
          const newColor = Color.rgb(r, g, b);
          setHue(newColor.hue());
          setSaturation(newColor.saturationl());
          setLightness(newColor.lightness());
          if (a !== undefined && a >= 0 && a <= 1) {
            setAlpha(a);
          }
        }
      }
    } catch (error) {
      console.error("Invalid CSS color input:", error);
    }
  };

  const handleCssBlur = () => {
    // Reset to valid color on blur if invalid
    try {
      const match = cssValue.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
      if (match) {
        const r = parseInt(match[1]);
        const g = parseInt(match[2]);
        const b = parseInt(match[3]);
        if (r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255) {
          return; // Valid
        }
      }
    } catch (error) {
      console.error("Error parsing CSS color on blur:", error);
    }
    const rgb = color
      .rgb()
      .array()
      .map((v) => Math.round(v));
    setCssValue(`rgb(${rgb.join(", ")})`);
  };

  const handleHslChange = (index: number, value: string) => {
    try {
      const num = parseFloat(value);
      if (isNaN(num)) return;
      if (index === 0) {
        // Hue: 0-360
        if (num >= 0 && num <= 360) {
          setHue(num);
        }
      } else if (index === 1) {
        // Saturation: 0-100
        if (num >= 0 && num <= 100) {
          setSaturation(num);
        }
      } else if (index === 2) {
        // Lightness: 0-100
        if (num >= 0 && num <= 100) {
          setLightness(num);
        }
      }
    } catch (error) {
      console.error("Invalid HSL color input:", error);
    }
  };

  if (mode === "hex") {
    return (
      <div className={cn("flex w-full items-center", className)} {...props}>
        <Input
          className="h-10 rounded-md bg-[var(--color-surface)] px-3 text-xs shadow-none font-mono"
          type="text"
          value={hexValue}
          onChange={(e) => handleHexChange(e.target.value)}
          onBlur={handleHexBlur}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.currentTarget.blur();
            }
          }}
        />
      </div>
    );
  }

  if (mode === "rgb") {
    const rgb = color
      .rgb()
      .array()
      .map((v) => Math.round(v));
    return (
      <div className={cn("flex items-center w-full", className)} {...props}>
        <Input
          className="h-10 rounded-r-none rounded-l-md bg-[var(--color-surface)] px-1 text-xs text-center shadow-none border-r-0"
          value={rgb[0]}
          onChange={(e) => handleRgbChange(0, e.target.value)}
        />
        <Input
          className="h-10 rounded-none bg-[var(--color-surface)] px-1 text-xs text-center shadow-none border-r-0 border-l-0"
          value={rgb[1]}
          onChange={(e) => handleRgbChange(1, e.target.value)}
        />
        <Input
          className="h-10 rounded-none rounded-r-md bg-[var(--color-surface)] px-1 text-xs text-center shadow-none border-l-0"
          value={rgb[2]}
          onChange={(e) => handleRgbChange(2, e.target.value)}
        />
      </div>
    );
  }

  if (mode === "css") {
    return (
      <div className={cn("w-full", className)} {...props}>
        <Input
          className="h-10 bg-[var(--color-surface)] px-3 text-xs shadow-none font-mono"
          value={cssValue}
          onChange={(e) => handleCssChange(e.target.value)}
          onBlur={handleCssBlur}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.currentTarget.blur();
            }
          }}
        />
      </div>
    );
  }

  if (mode === "hsl") {
    const hsl = color
      .hsl()
      .array()
      .map((v) => Math.round(v));
    return (
      <div className={cn("flex items-center w-full", className)} {...props}>
        <Input
          className="h-10 rounded-r-none rounded-l-md bg-[var(--color-surface)] px-1 text-xs text-center shadow-none border-r-0"
          value={hsl[0]}
          onChange={(e) => handleHslChange(0, e.target.value)}
        />
        <Input
          className="h-10 rounded-none bg-[var(--color-surface)] px-1 text-xs text-center shadow-none border-r-0 border-l-0"
          value={hsl[1]}
          onChange={(e) => handleHslChange(1, e.target.value)}
        />
        <Input
          className="h-10 rounded-none rounded-r-md bg-[var(--color-surface)] px-1 text-xs text-center shadow-none border-l-0"
          value={hsl[2]}
          onChange={(e) => handleHslChange(2, e.target.value)}
        />
      </div>
    );
  }

  return null;
};

import { useMemo } from "react";
import {
  Info,
  Edit3,
  RefreshCw,
  Trash2,
  Home,
  ExternalLink,
  Copy,
  Receipt,
} from "lucide-react";
import { Account } from "@renderer/types";
import GenericContextMenu, { ContextMenuSection } from "./GenericContextMenu";

interface ContextMenuProps {
  activeMenu: { id: string; x: number; y: number } | null;
  accounts: Account[];
  onViewDetails: (account: Account) => void;
  onEditNote: (id: string) => void;
  onReauth: (id: string) => void;
  onOpenBrowserHome: (id: string) => void;
  onOpenBrowserCustom: (id: string) => void;
  onGetCookie?: (id: string) => void;
  onRemove: (id: string) => void;
  selectedIds?: Set<string>;
  onBulkOpenBrowsers?: () => void;
  onBulkCopyCookies?: () => void;
  onBulkRemove?: () => void;
  onBulkOpenBrowserCustom?: () => void;
  onBulkEditNote?: () => void;
  onBulkReauth?: () => void;
  onChangeDisplayName?: (id: string) => void;
  onBulkChangeDisplayName?: () => void;
  onClose?: () => void;
}

const ContextMenu = ({
  activeMenu,
  accounts,
  onViewDetails,
  onEditNote,
  onReauth,
  onOpenBrowserHome,
  onOpenBrowserCustom,
  onGetCookie,
  onRemove,
  selectedIds,
  onBulkOpenBrowsers,
  onBulkCopyCookies,
  onBulkRemove,
  onBulkOpenBrowserCustom,
  onBulkEditNote,
  onBulkReauth,
  onChangeDisplayName,
  onBulkChangeDisplayName,
  onClose = () => {},
}: ContextMenuProps) => {
  const sections: ContextMenuSection[] = useMemo(() => {
    if (!activeMenu) return [];

    const account = accounts.find((a) => a.id === activeMenu.id);

    // If the right-clicked account is part of a multiple selection, show Bulk Actions
    if (selectedIds && selectedIds.size > 1 && selectedIds.has(activeMenu.id)) {
      return [
        {
          items: [
            {
              label: `Open Browsers (${selectedIds.size})`,
              icon: <ExternalLink size={16} />,
              onClick: () => onBulkOpenBrowsers?.(),
            },
            {
              label: `Open Custom Browsers (${selectedIds.size})`,
              icon: <ExternalLink size={16} />,
              onClick: () => onBulkOpenBrowserCustom?.(),
            },
            {
              label: `Copy Cookies (${selectedIds.size})`,
              icon: <Copy size={16} />,
              onClick: () => onBulkCopyCookies?.(),
            },
            {
              label: `Edit Notes (${selectedIds.size})`,
              icon: <Edit3 size={16} />,
              onClick: () => onBulkEditNote?.(),
            },
            {
              label: `Change Display Names (${selectedIds.size})`,
              icon: <Edit3 size={16} />,
              onClick: () => onBulkChangeDisplayName?.(),
            },
            {
              label: `Reauthenticate (${selectedIds.size})`,
              icon: <RefreshCw size={16} />,
              onClick: () => onBulkReauth?.(),
            },
          ],
        },
        {
          items: [
            {
              label: `Remove Selected (${selectedIds.size})`,
              icon: <Trash2 size={16} />,
              onClick: () => onBulkRemove?.(),
              variant: "danger" as const,
            },
          ],
        },
      ];
    }

    // Always show single-account options when right-clicking (independent of selection state)
    // This allows users to right-click any account to get its options without needing to select it
    return [
      {
        items: [
          {
            label: "View Details",
            icon: <Info size={16} />,
            onClick: () => account && onViewDetails(account),
          },
          {
            label: "Open Home",
            icon: <Home size={16} />,
            onClick: () => onOpenBrowserHome(activeMenu.id),
          },
          {
            label: "Open Custom",
            icon: <ExternalLink size={16} />,
            onClick: () => onOpenBrowserCustom(activeMenu.id),
          },
          {
            label: "Get Cookie",
            icon: <Copy size={16} />,
            onClick: () => onGetCookie?.(activeMenu.id),
          },
          {
            label: "Change Display Name",
            icon: <Edit3 size={16} />,
            onClick: () => onChangeDisplayName?.(activeMenu.id),
          },
          {
            label: "Copy Username",
            icon: <Copy size={16} />,
            onClick: () => {
              if (account?.username) {
                navigator.clipboard.writeText(account.username);
              }
            },
          },
          {
            label: "Edit Note",
            icon: <Edit3 size={16} />,
            onClick: () => onEditNote(activeMenu.id),
          },
          {
            label: "Re-authenticate",
            icon: <RefreshCw size={16} />,
            onClick: () => onReauth(activeMenu.id),
          },
        ],
      },
      {
        items: [
          {
            label: "Remove Account",
            icon: <Trash2 size={16} />,
            onClick: () => onRemove(activeMenu.id),
            variant: "danger" as const,
          },
        ],
      },
    ];
  }, [
    activeMenu,
    accounts,
    onViewDetails,
    onEditNote,
    onReauth,
    onOpenBrowserHome,
    onOpenBrowserCustom,
    onGetCookie,
    onRemove,
    selectedIds,
    onBulkOpenBrowsers,
    onBulkCopyCookies,
    onBulkRemove,
    onBulkOpenBrowserCustom,
    onBulkEditNote,
    onBulkReauth,
    onChangeDisplayName,
    onBulkChangeDisplayName,
    onClose,
  ]);
  return (
    <GenericContextMenu
      position={activeMenu ? { x: activeMenu.x, y: activeMenu.y } : null}
      sections={sections}
      onClose={onClose}
      width={172}
    />
  );
};

export default ContextMenu;

import React, { useState, useRef, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronUp, LogOut, Ticket, ArrowRightLeft, Heart } from "lucide-react";
import { Account } from "@renderer/types";
import {
  useAccountsManager,
  useAccountStats,
} from "../../../features/auth/api/useAccounts";
import { formatNumber } from "@renderer/utils/numberUtils";
import { useClickOutside } from "../../../hooks/useClickOutside";
import { RobuxIcon } from "@renderer/components/UI/icons/RobuxIcon";
import { SlidingNumber } from "@renderer/components/UI/specialized/SlidingNumber";
import CreditsDialog from "../dialogs/CreditsDialog";
import RedeemCodeDialog from "../dialogs/RedeemCodeDialog";

export interface ProfileCardProps {
  account: Account;
  selectedAccounts?: Account[];
  isCollapsed: boolean;
  privacyMode: boolean;
  onTransactionsClick: () => void;
  direction?: "up" | "down";
  variant?: "sidebar" | "topnav";
}

export const ProfileCard = ({
  account,
  selectedAccounts = [],
  isCollapsed,
  privacyMode,
  onTransactionsClick,
  direction = "up",
  variant = "sidebar",
}: ProfileCardProps) => {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isCreditsOpen, setIsCreditsOpen] = useState(false);
  const [isRedeemOpen, setIsRedeemOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const { removeAccount } = useAccountsManager();
  const { data: accountStats } = useAccountStats(account.cookie);

  const robuxBalance = useMemo(() => {
    if (selectedAccounts.length > 1) {
      return selectedAccounts.reduce(
        (total, acc) => total + (acc.robuxBalance || 0),
        0,
      );
    }
    return accountStats?.robuxBalance ?? account.robuxBalance;
  }, [selectedAccounts, accountStats?.robuxBalance, account.robuxBalance]);

  const isMultiSelect = selectedAccounts.length > 1;
  useClickOutside(containerRef, () => setIsDropdownOpen(false));

  const handleCardClick = () => setIsDropdownOpen((open) => !open);

  const handleSignOut = () => {
    removeAccount(account.id);
    setIsDropdownOpen(false);
  };

  const dropdownGroups = [
    [
      {
        icon: ArrowRightLeft,
        label: "Transactions",
        onClick: () => {
          onTransactionsClick();
          setIsDropdownOpen(false);
        },
      },
      {
        icon: Ticket,
        label: "Redeem Code",
        onClick: () => {
          setIsRedeemOpen(true);
          setIsDropdownOpen(false);
        },
      },
    ],
    [
      {
        icon: Heart,
        label: "Credits",
        onClick: () => {
          setIsCreditsOpen(true);
          setIsDropdownOpen(false);
        },
      },
    ],
    [
      {
        icon: LogOut,
        label: "Sign out",
        onClick: handleSignOut,
        danger: true,
      },
    ],
  ];

  const dropdownVariants = {
    initial: { opacity: 0, y: direction === "up" ? 8 : -8, scale: 0.95 },
    animate: { opacity: 1, y: 0, scale: 1 },
    exit: { opacity: 0, y: direction === "up" ? 8 : -8, scale: 0.95 },
  };

  const dropdownPositionClasses =
    direction === "up" ? "bottom-full mb-2" : "top-full mt-2";

  const profileLabel = isMultiSelect
    ? `${selectedAccounts.length} Accounts`
    : privacyMode
      ? "••••••"
      : account.displayName || account.username;

  const profileMeta = isMultiSelect
    ? "Multiple Selected"
    : `@${account.username}`;

  const avatarStyle = privacyMode ? { filter: "blur(16px)" } : undefined;

  const renderDropdown = () => (
    <AnimatePresence>
      {isDropdownOpen && (
        <motion.div
          initial="initial"
          animate="animate"
          exit="exit"
          variants={dropdownVariants}
          transition={{ duration: 0.15, ease: "easeOut" }}
          className={`absolute ${variant === "topnav" ? "right-0 left-auto" : "left-3 right-3"} w-56 bg-[var(--color-surface-strong)] border border-[var(--color-border)] rounded-[var(--menu-radius)] shadow-2xl z-50 overflow-hidden ${dropdownPositionClasses}`}
        >
          <div className="p-3 border-b border-[var(--color-border)]">
            <div className="flex items-center gap-2.5">
              <img
                className="h-8 w-8 rounded-full bg-[var(--color-surface)] object-cover border border-[var(--color-border)]"
                src={account.avatarUrl}
                alt={privacyMode ? "" : account.displayName}
                style={avatarStyle}
              />
              <div className="flex-1 min-w-0">
                <div
                  className="font-semibold text-sm text-[var(--color-text-primary)] truncate"
                  style={avatarStyle}
                >
                  {profileLabel}
                </div>
                <div
                  className="text-[var(--color-text-muted)] text-xs truncate"
                  style={
                    privacyMode && !isMultiSelect ? avatarStyle : undefined
                  }
                >
                  {profileMeta}
                </div>
              </div>
            </div>
            {!isMultiSelect && (
              <div className="mt-2 flex items-center gap-1.5 text-sm">
                <RobuxIcon className="w-3.5 h-3.5 text-emerald-400" />
                <SlidingNumber
                  number={robuxBalance}
                  formatter={formatNumber}
                  className="font-semibold text-[var(--color-text-primary)]"
                />
              </div>
            )}
          </div>

          <div className="p-1.5">
            {dropdownGroups.map((group, groupIndex) => (
              <div
                key={groupIndex}
                className={
                  groupIndex > 0
                    ? "mt-1 pt-1 border-t border-[var(--color-border)]"
                    : ""
                }
              >
                {group.map((item, index) => (
                  <button
                    key={index}
                    onClick={item.onClick}
                    className={`w-full flex items-center gap-2.5 px-3 py-2 text-sm rounded-[calc(var(--menu-radius)-6px)] transition-colors ${
                      item.danger
                        ? "text-red-400 hover:bg-red-500/10 hover:text-red-300"
                        : "text-[var(--color-text-secondary)] hover:bg-[var(--color-surface-hover)] hover:text-[var(--color-text-primary)]"
                    }`}
                  >
                    <item.icon size={16} />
                    <span className="font-medium">{item.label}</span>
                  </button>
                ))}
              </div>
            ))}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );

  if (isCollapsed) {
    if (variant === "topnav") {
      return (
        <>
          <div className="relative" ref={containerRef}>
            <button
              onClick={handleCardClick}
              className={`h-10 flex items-center gap-0 border transition-all duration-200 group ${
                isDropdownOpen
                  ? "border-[var(--color-border-strong)] bg-[var(--color-surface-hover)] shadow-md"
                  : "border-[var(--color-border)] bg-[var(--color-surface-muted)] hover:bg-[var(--color-surface-hover)] hover:border-[var(--color-border-strong)]"
              }`}
              style={{ borderRadius: 0 }}
            >
              <span
                className="pl-3 pr-1.5 text-xs font-semibold text-[var(--color-text-primary)] whitespace-nowrap tracking-tight"
                style={privacyMode ? { filter: "blur(10px)" } : undefined}
              >
                {profileLabel}
              </span>

              <img
                className={`h-7 w-7 bg-[var(--color-surface)] object-cover border-2 m-0.5 transition-all duration-200 flex-shrink-0 ${
                  isDropdownOpen
                    ? "border-[var(--accent-color-border)]"
                    : "border-[var(--color-border)] group-hover:border-[var(--color-border-strong)]"
                }`}
                src={account.avatarUrl}
                alt={privacyMode ? "" : account.displayName}
                style={{
                  borderRadius: "calc(var(--control-radius) - 2px)",
                  ...(avatarStyle ?? {}),
                }}
              />
            </button>
            {renderDropdown()}
          </div>
          <CreditsDialog
            isOpen={isCreditsOpen}
            onClose={() => setIsCreditsOpen(false)}
          />
          <RedeemCodeDialog
            isOpen={isRedeemOpen}
            onClose={() => setIsRedeemOpen(false)}
            account={account}
          />
        </>
      );
    }

