// ─── Top Nav ──────────────────────────────────────────────────────────────────
interface TopNavProps {
  selectedAccounts?: Account[];
  primaryAccount?: Account | null;
  selectedAccount: Account | null;
  showProfileCard: boolean;
  privacyMode: boolean;
  tabOrder: TabId[];
  hiddenTabs: TabId[];
  onOpenCommandPalette: () => void;
  onOpenTransactions: () => void;
  onOpenUserProfile: (userId: string) => void;
}

const TopNav = ({
  selectedAccounts = [],
  primaryAccount,
  selectedAccount,
  showProfileCard,
  privacyMode,
  tabOrder,
  hiddenTabs,
  onOpenCommandPalette,
  onOpenTransactions,
  onOpenUserProfile,
}: TopNavProps) => {
  const activeTab = useActiveTab();
  const setActiveTab = useTabTransition();

  const normalizedOrder = useMemo(
    () => sanitizeSidebarOrder(tabOrder),
    [tabOrder],
  );
  const normalizedHiddenTabs = useMemo(
    () => sanitizeSidebarHidden(hiddenTabs),
    [hiddenTabs],
  );
  const visibleTabs = useMemo(
    () => getVisibleSidebarTabs(normalizedOrder, normalizedHiddenTabs),
    [normalizedHiddenTabs, normalizedOrder],
  );
  const navTabs = useMemo(
    () =>
      visibleTabs
        .map((tabId) => SIDEBAR_TAB_DEFINITION_MAP[tabId])
        .filter(Boolean) as SidebarTabDefinition[],
    [visibleTabs],
  );

  const accountForProfile =
    selectedAccounts.length > 0
      ? selectedAccounts[0]
      : selectedAccount || primaryAccount;

  return (
    <TooltipProvider>
      <header
        className="flex-shrink-0 z-30 relative flex items-center bg-[var(--color-surface-strong)] border-b border-[var(--color-border)]"
        style={
          {
            height: isMac ? "72px" : "52px",
            paddingTop: isMac ? "28px" : "0px",
            // On Windows the native window control buttons sit in the top-right corner
            // and can overlap app controls. Add extra right padding on non-mac platforms
            // to avoid overlap.
            paddingRight: isMac ? undefined : "140px",
            WebkitAppRegion: "drag",
          } as React.CSSProperties
        }
      >
        {/* Left: Logo */}
        <div
          className="flex items-center gap-2 px-4 shrink-0"
          style={{ WebkitAppRegion: "no-drag" } as React.CSSProperties}
        >
          <SentraLogo className="h-7 w-7 shrink-0" />
          <span className="font-bold text-base tracking-tight text-[var(--color-text-primary)] hidden sm:block">
            Sentra
          </span>
        </div>

        {/* Separator */}
        <div className="w-px h-5 bg-[var(--color-border)] mx-1" />

        {/* Center: Nav Items */}
        <nav
          className="flex-1 flex items-center gap-0.5 px-2 overflow-x-auto scrollbar-hide"
          style={{ WebkitAppRegion: "no-drag" } as React.CSSProperties}
        >
          {navTabs.map((tab, index) => {
            const previous = navTabs[index - 1] as
              | SidebarTabDefinition
              | undefined;
            const showSeparator = previous && previous.section !== tab.section;
            return (
              <React.Fragment key={tab.id}>
                {showSeparator && (
                  <div className="w-px h-5 bg-[var(--color-border)] mx-1 shrink-0" />
                )}
                <TopNavItem
                  icon={tab.icon}
                  label={tab.label}
                  isActive={activeTab === tab.id}
                  onClick={() => setActiveTab(tab.id)}
                />
              </React.Fragment>
            );
          })}
        </nav>

        {/* Right: Actions */}
        <div
          className="flex items-center gap-1.5 px-3 shrink-0"
          style={{ WebkitAppRegion: "no-drag" } as React.CSSProperties}
        >
          {showProfileCard && accountForProfile && (
            <ProfileCard
              account={accountForProfile}
              selectedAccounts={selectedAccounts}
              isCollapsed={true}
              privacyMode={privacyMode}
              onTransactionsClick={onOpenTransactions}
              direction="down"
              variant="topnav"
            />
          )}

          <button
            onClick={(e) => {
              e.stopPropagation();
              onOpenCommandPalette();
            }}
            className="flex h-10 w-10 items-center justify-center rounded-lg text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-surface-hover)] transition-all"
            title="Search (Ctrl+K)"
          >
            <Search size={17} />
          </button>

          <NotificationTray onOpenUserProfile={onOpenUserProfile} />
        </div>
      </header>
    </TooltipProvider>
  );
};

export default TopNav;

import React, { useState, useRef, useEffect, useCallback, memo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Lock, AlertTriangle } from "lucide-react";
import { useQueryClient } from "@tanstack/react-query";
import { queryKeys } from "@shared/queryKeys";

interface PinLockScreenProps {
  onUnlock: () => void;
}

// Memoized PIN input field to prevent unnecessary re-renders
const PinInputField = memo(
  React.forwardRef<
    HTMLInputElement,
    {
      digit: string;
      index: number;
      disabled: boolean;
      error: boolean;
      isLocked: boolean;
      onChange: (index: number, value: string) => void;
      onKeyDown: (
        index: number,
        e: React.KeyboardEvent<HTMLInputElement>,
      ) => void;
    }
  >(({ digit, index, disabled, error, isLocked, onChange, onKeyDown }, ref) => (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.1 + index * 0.05 }}
    >
      <input
        ref={ref}
        type="password"
        inputMode="numeric"
        maxLength={1}
        value={digit}
        onChange={(e) => onChange(index, e.target.value)}
        onKeyDown={(e) => onKeyDown(index, e)}
        disabled={disabled}
        className={`w-10 h-12 sm:w-12 sm:h-14 text-center text-xl sm:text-2xl font-mono rounded-lg border-2 bg-[var(--color-surface)] text-[var(--color-text-primary)] focus:outline-none transition-all ${
          isLocked
            ? "border-red-800 bg-red-900/10 cursor-not-allowed opacity-50"
            : error
              ? "border-red-500 bg-red-500/10"
              : digit
                ? "border-[var(--accent-color)] bg-[var(--accent-color)]/5"
                : "border-[var(--color-border-strong)] focus:border-[var(--accent-color)]"
        }`}
      />
    </motion.div>
  )),
);

PinInputField.displayName = "PinInputField";

const PinLockScreen: React.FC<PinLockScreenProps> = ({ onUnlock }) => {
  const queryClient = useQueryClient();
  const [pin, setPin] = useState<string[]>(Array(6).fill(""));
  const [error, setError] = useState<string | null>(null);
  const [shake, setShake] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(false);
  const [lockoutSeconds, setLockoutSeconds] = useState(0);
  const [remainingAttempts, setRemainingAttempts] = useState(5);
  const [isCheckingLockout, setIsCheckingLockout] = useState(true);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
  const lastVerifiedPinRef = useRef<string>(""); // Track last verified PIN to prevent duplicate calls
  useEffect(() => {
    const checkLockoutStatus = async () => {
      try {
        const status = await window.api.getPinLockoutStatus();
        if (status.locked && status.lockoutSeconds) {
          setIsLocked(true);
          setLockoutSeconds(status.lockoutSeconds);
          setRemainingAttempts(0);
          setError("Too many failed attempts. Please wait.");
        } else {
          setRemainingAttempts(status.remainingAttempts);
        }
      } catch (err) {
        console.error("Failed to check lockout status:", err);
      } finally {
        setIsCheckingLockout(false);
      }
    };
    checkLockoutStatus();
  }, []);

  // Focus first input on mount
  useEffect(() => {
    if (!isLocked && !isCheckingLockout) {
      inputRefs.current[0]?.focus();
    }
  }, [isLocked, isCheckingLockout]);

  // Countdown timer for lockout
  useEffect(() => {
    if (!isLocked || lockoutSeconds <= 0) return;

    const timer = setInterval(() => {
      setLockoutSeconds((prev) => {
        const next = prev - 1;
        if (next <= 0) {
          setIsLocked(false);
          setError(null);
          setRemainingAttempts(5);
          return 0;
        }
        return next;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [isLocked]);

  const verifyPin = useCallback(
    async (enteredPin: string) => {
      setIsVerifying(true);
      setError(null);

      try {
        const result = await window.api.verifyPin(enteredPin);

        if (result.success) {
          // verifyPin returns accounts directly in the response — use them immediately
          // so the cache is populated before onUnlock() triggers a re-render
          const accounts = result.accounts;
          queryClient.setQueryData(
            queryKeys.accounts.list(),
            Array.isArray(accounts) ? accounts : [],
          );

          // The main process just decrypted the settings, force a refetch
          queryClient.invalidateQueries({
            queryKey: queryKeys.settings.snapshot(),
          });

          onUnlock();
        } else if (result.locked) {
          setIsLocked(true);
          setLockoutSeconds(result.lockoutSeconds || 300);
          setError(`Too many failed attempts. Please wait.`);
          setShake(true);
          setTimeout(() => {
            setShake(false);
            setPin(Array(6).fill(""));
            lastVerifiedPinRef.current = "";
          }, 500);
        } else {
          setRemainingAttempts(result.remainingAttempts);
          setError(
            result.remainingAttempts === 1
              ? "Incorrect PIN. 1 attempt remaining!"
              : `Incorrect PIN. ${result.remainingAttempts} attempts remaining.`,
          );
          setShake(true);
          setTimeout(() => {
            setShake(false);
            setPin(Array(6).fill(""));
            lastVerifiedPinRef.current = "";
            inputRefs.current[0]?.focus();
          }, 500);
        }
      } catch (err) {
        console.error("PIN verification error:", err);
        setError("An error occurred. Please try again.");
        setPin(Array(6).fill(""));
        lastVerifiedPinRef.current = "";
      } finally {
        setIsVerifying(false);
      }
    },
    [onUnlock, queryClient],
  );

  // Verify PIN when all digits are entered
  useEffect(() => {
    const enteredPin = pin.join("");
    if (
      enteredPin.length === 6 &&
      !isVerifying &&
      !isLocked &&
      enteredPin !== lastVerifiedPinRef.current
    ) {
      lastVerifiedPinRef.current = enteredPin; // Mark this PIN as being verified
      verifyPin(enteredPin);
    }
  }, [pin, isVerifying, isLocked, verifyPin]);

  const handleInputChange = useCallback(
    (index: number, value: string) => {
      if (isLocked || isVerifying) return;

      // Only allow single digit
      const digit = value.slice(-1);
      if (!/^\d?$/.test(digit)) return;

      setPin((prev) => {
        const newPin = [...prev];
        newPin[index] = digit;
        return newPin;
      });

      // Move to next input if digit entered
      if (digit && index < 5) {
        inputRefs.current[index + 1]?.focus();
      }
    },
    [isLocked, isVerifying],
  );

  const handleKeyDown = useCallback(
    (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
      if (isLocked || isVerifying) return;

      if (e.key === "Backspace") {
        if (!pin[index] && index > 0) {
          // Move to previous input if current is empty
          inputRefs.current[index - 1]?.focus();
          setPin((prev) => {
            const newPin = [...prev];
            newPin[index - 1] = "";
            return newPin;
          });
        } else {
          setPin((prev) => {
            const newPin = [...prev];
            newPin[index] = "";
            return newPin;
          });
        }
      } else if (e.key === "ArrowLeft" && index > 0) {
        inputRefs.current[index - 1]?.focus();
      } else if (e.key === "ArrowRight" && index < 5) {
        inputRefs.current[index + 1]?.focus();
      }
    },
    [pin, isLocked, isVerifying],
  );

  // Numpad removed — input is keyboard-only. Keyboard handlers remain.

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0, scale: 1.1, filter: "blur(10px)" }}
      transition={{ duration: 0.5, ease: "easeInOut" }}
      className="fixed inset-0 z-[9999] flex items-center justify-center bg-black"
    >
      {/* Background gradient */}
      <div className="absolute inset-0 bg-gradient-to-br from-neutral-900 via-black to-neutral-900" />

      {/* Loading state while checking lockout */}
      {isCheckingLockout ? (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="relative z-10 flex flex-col items-center"
        >
          <div className="mb-4 p-4 rounded-full bg-[var(--color-surface)] border border-[var(--color-border)]">
            <Lock className="w-8 h-8 text-[var(--color-text-secondary)]" />
          </div>
          <p className="text-[var(--color-text-muted)] text-sm">
            Checking security status...
          </p>
        </motion.div>
      ) : (
        /* Content */
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="relative z-10 flex flex-col items-center w-full max-w-md px-4"
        >
          {/* Lock Icon */}
          <motion.div
            className={`mb-6 p-4 rounded-full border ${
              isLocked
                ? "bg-red-900/20 border-red-800"
                : "bg-[var(--color-surface)] border-[var(--color-border)]"
            }`}
            initial={{ y: -20 }}
            animate={{ y: 0 }}
            transition={{ delay: 0.1 }}
          >
            {isLocked ? (
              <AlertTriangle className="w-8 h-8 text-red-500" />
            ) : (
              <Lock className="w-8 h-8 text-[var(--color-text-secondary)]" />
            )}
          </motion.div>

          {/* Title */}
          <motion.h1
            className="text-2xl font-bold text-[var(--color-text-primary)] mb-2"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2 }}
          >
            {isLocked ? "Account Locked" : "Enter PIN"}
          </motion.h1>
          <motion.p
            className="text-[var(--color-text-muted)] text-sm mb-8 text-center max-w-xs"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3 }}
          >
            {isLocked
              ? `Too many failed attempts. Try again in ${formatTime(lockoutSeconds)}`
              : "Enter your 6-digit PIN to unlock"}
          </motion.p>

          {/* PIN Input */}
          <motion.div
            className="flex gap-2 sm:gap-3 mb-6 justify-center w-full"
            animate={shake ? { x: [0, -10, 10, -10, 10, 0] } : {}}
            transition={{ duration: 0.4 }}
          >
            {pin.map((digit, index) => (
              <PinInputField
                key={index}
                ref={(el) => {
                  inputRefs.current[index] = el;
                }}
                digit={digit}
                index={index}
                disabled={isLocked || isVerifying}
                error={!!error}
                isLocked={isLocked}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
              />
            ))}
          </motion.div>

          {/* Error/Info Message */}
          <AnimatePresence mode="wait">
            {error && (
              <motion.div
                key="error"
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className={`text-sm mb-4 px-4 py-2 rounded-lg ${
                  isLocked
                    ? "text-red-400 bg-red-500/10 border border-red-500/20"
                    : "text-yellow-400 bg-yellow-500/10 border border-yellow-500/20"
                }`}
              >
                {error}
              </motion.div>
            )}
          </AnimatePresence>

          {/* Remaining Attempts Indicator */}
          {!isLocked && remainingAttempts < 5 && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="flex gap-1 mb-4"
            >
              {Array.from({ length: 5 }).map((_, i) => (
                <div
                  key={i}
                  className={`w-2 h-2 rounded-full transition-colors ${
                    i < remainingAttempts
                      ? "bg-yellow-500"
                      : "bg-[var(--color-surface-hover)]"
                  }`}
                />
              ))}
            </motion.div>
          )}

          {/* Numpad removed — keyboard input only */}

          {/* Security note */}
          <motion.p
            className="text-[var(--color-text-muted)] text-xs mt-8 text-center max-w-xs"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
          >
            Your PIN is securely hashed and encrypted.
            {!isLocked &&
              remainingAttempts === 5 &&
              " 5 attempts before lockout."}
          </motion.p>
        </motion.div>
      )}
    </motion.div>
  );
};

export default PinLockScreen;

