import React, { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Play,
  Square,
  CheckCircle2,
  AlertCircle,
  Loader2,
  ChevronDown,
} from "lucide-react";
import { Account, AccountStatus } from "@renderer/types";
import { Button } from "@renderer/components/UI/buttons/Button";
import { useNotification } from "@renderer/features/system/stores/useSnackbarStore";
import CustomDropdown, {
  DropdownOption,
} from "@renderer/components/UI/menus/CustomDropdown";

interface BatchOperationsPanelProps {
  accounts: Account[];
  selectedIds: Set<string>;
}

type BatchOperation = "launch" | "validate" | "terminate";

export const BatchOperationsPanel = ({
  accounts,
  selectedIds,
}: BatchOperationsPanelProps) => {
  const { showNotification } = useNotification();
  const [isExpanded, setIsExpanded] = useState(false);
  const [isOperationRunning, setIsOperationRunning] = useState(false);
  const [currentOperation, setCurrentOperation] =
    useState<BatchOperation | null>(null);
  const [placeId, setPlaceId] = useState("");
  const [launchGap, setLaunchGap] = useState(500);
  const [progress, setProgress] = useState<{
    current: number;
    total: number;
  } | null>(null);

  const selectedAccounts = accounts.filter((a) => selectedIds.has(a.id));

  const handleLaunchBatch = useCallback(async () => {
    if (selectedAccounts.length === 0) {
      showNotification("No accounts selected", "warning");
      return;
    }

    if (!placeId) {
      showNotification("Please enter a Place ID", "warning");
      return;
    }

    setIsOperationRunning(true);
    setCurrentOperation("launch");
    setProgress({ current: 0, total: selectedAccounts.length });

    try {
      for (let i = 0; i < selectedAccounts.length; i++) {
        const account = selectedAccounts[i];
        if (!account.cookie) {
          console.warn(`Skipping ${account.username} - no cookie`);
          continue;
        }

        try {
          await window.electron.ipcRenderer.invoke("games:launch-game", {
            cookie: account.cookie,
            placeId: Number(placeId),
            accountId: account.id,
            username: account.displayName || account.username,
          });
        } catch (err) {
          console.error(`Failed to launch ${account.username}:`, err);
        }

        setProgress((prev) =>
          prev
            ? { ...prev, current: i + 1 }
            : { current: i + 1, total: selectedAccounts.length },
        );

        if (i < selectedAccounts.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, launchGap));
        }
      }

      showNotification(
        `Launched ${selectedAccounts.length} account(s) to place ${placeId}`,
        "success",
      );
    } catch (err) {
      showNotification("Error during batch launch", "error");
      console.error(err);
    } finally {
      setIsOperationRunning(false);
      setCurrentOperation(null);
      setProgress(null);
    }
  }, [selectedAccounts, placeId, launchGap, showNotification]);

  const handleValidateBatch = useCallback(async () => {
    if (selectedAccounts.length === 0) {
      showNotification("No accounts selected", "warning");
      return;
    }

    setIsOperationRunning(true);
    setCurrentOperation("validate");
    setProgress({ current: 0, total: selectedAccounts.length });

    let validCount = 0;
    let invalidCount = 0;

    try {
      for (let i = 0; i < selectedAccounts.length; i++) {
        const account = selectedAccounts[i];
        if (!account.cookie) {
          invalidCount++;
          continue;
        }

        try {
          await window.api.validateCookie(account.cookie);
          validCount++;
        } catch (err) {
          invalidCount++;
          console.error(`Validation failed for ${account.username}:`, err);
        }

        setProgress((prev) =>
          prev
            ? { ...prev, current: i + 1 }
            : { current: i + 1, total: selectedAccounts.length },
        );

        if (i < selectedAccounts.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, 100));
        }
      }

      showNotification(
        `Validation complete. ${validCount} valid, ${invalidCount} invalid.`,
        invalidCount > 0 ? "warning" : "success",
      );
    } catch (err) {
      showNotification("Error during batch validation", "error");
      console.error(err);
    } finally {
      setIsOperationRunning(false);
      setCurrentOperation(null);
      setProgress(null);
    }
  }, [selectedAccounts, showNotification]);

  const handleTerminateBatch = useCallback(async () => {
    if (selectedAccounts.length === 0) {
      showNotification("No accounts selected", "warning");
      return;
    }

    if (!confirm(`Terminate ${selectedAccounts.length} client(s)?`)) return;

    setIsOperationRunning(true);
    setCurrentOperation("terminate");
    setProgress({ current: 0, total: selectedAccounts.length });

    let terminatedCount = 0;

    try {
      for (let i = 0; i < selectedAccounts.length; i++) {
        const account = selectedAccounts[i];

        try {
          if (typeof (window.api as any)?.terminateAccount === "function") {
            await (window.api as any).terminateAccount(account.id);
            terminatedCount++;
          } else {
            console.warn("terminateAccount API not available");
          }
        } catch (err) {
          console.error(`Failed to terminate ${account.username}:`, err);
        }

        setProgress((prev) =>
          prev
            ? { ...prev, current: i + 1 }
            : { current: i + 1, total: selectedAccounts.length },
        );

        if (i < selectedAccounts.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, 100));
        }
      }

      showNotification(`Terminated ${terminatedCount} client(s)`, "success");
    } catch (err) {
      showNotification("Error during batch termination", "error");
      console.error(err);
    } finally {
      setIsOperationRunning(false);
      setCurrentOperation(null);
      setProgress(null);
    }
  }, [selectedAccounts, showNotification]);

  if (selectedAccounts.length === 0) return null;

  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: "auto" }}
      exit={{ opacity: 0, height: 0 }}
      className="bg-[var(--color-surface)] border border-[var(--color-border)] rounded-xl overflow-hidden"
    >
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full px-4 py-3 flex items-center gap-3 hover:bg-[var(--color-surface-hover)] transition-colors border-b border-[var(--color-border)]"
      >
        <ChevronDown
          size={16}
          className={`transition-transform ${isExpanded ? "rotate-180" : ""}`}
        />
        <span className="text-sm font-semibold text-[var(--color-text-primary)]">
          Batch Operations
        </span>
        <span className="ml-auto text-xs bg-[var(--accent-color)] text-[var(--accent-color-foreground)] px-2 py-1 rounded">
          {selectedAccounts.length} selected
        </span>
      </button>

      <AnimatePresence>
        {isExpanded && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="p-4 space-y-4 border-t border-[var(--color-border)]"
          >
            {/* Launch to Place */}
            <div className="space-y-2">
              <label className="text-xs font-semibold text-[var(--color-text-secondary)]">
                Launch All to Place
              </label>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={placeId}
                  onChange={(e) => setPlaceId(e.target.value)}
                  placeholder="Place ID"
                  disabled={isOperationRunning}
                  className="flex-1 h-8 rounded-lg bg-[var(--color-surface)] border border-[var(--color-border)] px-3 text-sm text-[var(--color-text-primary)] focus:outline-none focus:border-[var(--accent-color)] disabled:opacity-50"
                />
                <div className="text-xs text-[var(--color-text-muted)] flex items-center px-2">
                  Gap: {launchGap}ms
                </div>
              </div>
              <input
                type="range"
                min="100"
                max="5000"
                step="100"
                value={launchGap}
                onChange={(e) => setLaunchGap(Number(e.target.value))}
                disabled={isOperationRunning}
                className="w-full"
              />
              <Button
                onClick={handleLaunchBatch}
                disabled={isOperationRunning || !placeId}
                className="w-full gap-2 bg-blue-600 hover:bg-blue-700 text-white"
              >
                {currentOperation === "launch" ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Play className="h-4 w-4" />
                )}
                Launch All
              </Button>
            </div>

            {/* Validate All */}
            <Button
              onClick={handleValidateBatch}
              disabled={isOperationRunning}
              className="w-full gap-2 bg-purple-600 hover:bg-purple-700 text-white"
            >
              {currentOperation === "validate" ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <CheckCircle2 className="h-4 w-4" />
              )}
              Validate All Cookies
            </Button>

            {/* Terminate All */}
            <Button
              onClick={handleTerminateBatch}
              disabled={isOperationRunning}
              className="w-full gap-2 bg-red-600 hover:bg-red-700 text-white"
            >
              {currentOperation === "terminate" ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Square className="h-4 w-4" />
              )}
              Terminate All Clients
            </Button>

            {/* Progress Bar */}
            {progress && (
              <div className="bg-[var(--color-surface-muted)] rounded-lg p-3 space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="text-[var(--color-text-secondary)]">
                    {currentOperation?.toUpperCase()} PROGRESS
                  </span>
                  <span className="text-[var(--color-text-muted)]">
                    {progress.current} / {progress.total}
                  </span>
                </div>
                <div className="h-2 bg-[var(--color-surface-hover)] rounded-full overflow-hidden">
                  <motion.div
                    className="h-full bg-[var(--accent-color)]"
                    animate={{
                      width: `${(progress.current / progress.total) * 100}%`,
                    }}
                    transition={{ duration: 0.3 }}
                  />
                </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

import React, { useState, useEffect } from "react";
import {
  TrendingUp,
  TrendingDown,
  DollarSign,
  X,
  Loader2,
  AlertCircle,
  Calendar,
  ChevronDown,
} from "lucide-react";
import { Dialog, DialogContent } from "../../components/UI/dialogs/Dialog";
import type { Account } from "../../types";

interface AccountTotals {
  accountId: string;
  username: string;
  incomingRobux: number;
  outgoingRobux: number;
  salesTotal: number;
  purchasesTotal: number;
  error?: string;
}

type TimeFrame = "Day" | "Week" | "Month" | "Year";

const TIME_FRAME_OPTIONS: { value: TimeFrame; label: string }[] = [
  { value: "Day", label: "Today" },
  { value: "Week", label: "This Week" },
  { value: "Month", label: "This Month" },
  { value: "Year", label: "This Year" },
];

interface BulkTransactionsModalProps {
  isOpen: boolean;
  onClose: () => void;
  accounts: Account[];
  selectedIds: Set<string>;
}

const BulkTransactionsModal: React.FC<BulkTransactionsModalProps> = ({
  isOpen,
  onClose,
  accounts,
  selectedIds,
}) => {
  const [results, setResults] = useState<AccountTotals[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [completedCount, setCompletedCount] = useState(0);
  const [timeFrame, setTimeFrame] = useState<TimeFrame>("Month");
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  useEffect(() => {
    if (!isOpen) {
      setResults([]);
      setProgress(0);
      setIsDropdownOpen(false);
      return;
    }

    setResults([]); // Clear previous results when fetching new timeframe
    setProgress(0);
    let isActive = true;

    const fetchTotals = async () => {
      setIsLoading(true);
      const selectedAccounts = accounts.filter(
        (a) => selectedIds.has(a.id) && a.cookie,
      );
      if (selectedAccounts.length === 0) {
        setResults([]);
        setProgress(100);
        setIsLoading(false);
        return;
      }

      let currentCompleted = 0;
      setCompletedCount(0);

      const updateProgress = () => {
        currentCompleted += 1;
        if (!isActive) return;
        setCompletedCount(currentCompleted);
        setProgress(
          Math.round((currentCompleted / selectedAccounts.length) * 100),
        );
      };

      const totals: AccountTotals[] = [];

      // Process in small batches of 3 to avoid hammering the Roblox API (Rate Limits)
      const batchSize = 3;
      for (let i = 0; i < selectedAccounts.length; i += batchSize) {
        if (!isActive) return;

        const batch = selectedAccounts.slice(i, i + batchSize);
        const batchResults = await Promise.all(
          batch.map(async (account) => {
            try {
              const data = await window.api.getTransactionTotals(
                account.cookie!,
                timeFrame,
              );
              return {
                accountId: account.id,
                username: account.username,
                incomingRobux: data.incomingRobuxTotal ?? 0,
                outgoingRobux: data.outgoingRobuxTotal ?? 0,
                salesTotal: data.salesTotal ?? 0,
                purchasesTotal: data.purchasesTotal ?? 0,
              };
            } catch (err) {
              console.error(
                `Failed to fetch transactions for ${account.username}:`,
                err,
              );
              return {
                accountId: account.id,
                username: account.username,
                incomingRobux: 0,
                outgoingRobux: 0,
                salesTotal: 0,
                purchasesTotal: 0,
                error: "Failed to fetch (Invalid or Rate Limited)",
              };
            } finally {
              updateProgress();
            }
          }),
        );
        totals.push(...batchResults);

        // Add a small delay between batches to respect rate limits
        if (i + batchSize < selectedAccounts.length) {
          await new Promise((resolve) => setTimeout(resolve, 800));
        }
      }

      if (!isActive) return;
      setResults(totals);
      setIsLoading(false);
    };

    void fetchTotals();

    return () => {
      isActive = false;
    };
  }, [isOpen, accounts, selectedIds, timeFrame]);

  const totalIncoming = results.reduce((sum, r) => sum + r.incomingRobux, 0);
  const totalOutgoing = results.reduce((sum, r) => sum + r.outgoingRobux, 0);
  const totalSales = results.reduce((sum, r) => sum + r.salesTotal, 0);
  const totalPurchases = results.reduce((sum, r) => sum + r.purchasesTotal, 0);
  const net = totalIncoming - totalOutgoing;

  const fmt = (n: number) => n.toLocaleString();

  return (
    <Dialog isOpen={isOpen} onClose={isLoading ? () => {} : onClose}>
      <DialogContent className="max-w-2xl bg-[#0e0e10] border border-white/10 shadow-2xl p-0 overflow-hidden">
        {/* Header */}
        <div className="relative p-6 pb-4 border-b border-white/10">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-emerald-500/10 text-emerald-400">
              <DollarSign size={22} />
            </div>
            <div>
              <h2 className="text-xl font-bold text-[var(--color-text-primary)]">
                Transaction Totals
              </h2>
              <p className="text-sm text-[var(--color-text-secondary)] mt-0.5">
                {selectedIds.size} account{selectedIds.size !== 1 ? "s" : ""}
              </p>
            </div>
          </div>

          <div
            className="absolute top-5 right-16 z-50"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => setIsDropdownOpen(!isDropdownOpen)}
              disabled={isLoading}
              className="flex items-center gap-2 px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-xs font-medium text-[var(--color-text-secondary)] hover:bg-white/10 hover:text-[var(--color-text-primary)] transition-colors disabled:opacity-50"
            >
              <Calendar size={14} className="text-[var(--color-text-muted)]" />
              <span>
                {TIME_FRAME_OPTIONS.find((o) => o.value === timeFrame)?.label ||
                  "This Month"}
              </span>
              <ChevronDown
                size={12}
                className={`text-[var(--color-text-muted)] transition-transform ${isDropdownOpen ? "rotate-180" : ""}`}
              />
            </button>
            {isDropdownOpen && (
              <div className="absolute right-0 mt-1.5 w-36 bg-[#1a1a1c] border border-white/10 rounded-xl shadow-xl overflow-hidden">
                <div className="p-1">
                  {TIME_FRAME_OPTIONS.map((option) => (
                    <button
                      key={option.value}
                      onClick={() => {
                        setTimeFrame(option.value);
                        setIsDropdownOpen(false);
                      }}
                      className={`w-full text-left px-3 py-2 text-xs rounded-lg transition-colors ${
                        timeFrame === option.value
                          ? "bg-[var(--accent-color)] text-[var(--accent-color-foreground)] font-bold"
                          : "text-[var(--color-text-secondary)] hover:bg-white/5 hover:text-[var(--color-text-primary)]"
                      }`}
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          <button
            onClick={onClose}
            disabled={isLoading}
            className="absolute top-5 right-5 rounded-lg p-1.5 text-[var(--color-text-muted)] transition hover:bg-white/10 hover:text-[var(--color-text-primary)] disabled:opacity-40"
          >
            <X size={18} />
          </button>
        </div>

        {/* Loading state */}
        {isLoading && (
          <div className="p-8 flex flex-col items-center gap-4 text-center">
            <Loader2 className="h-8 w-8 animate-spin text-emerald-400" />
            <div className="space-y-1.5">
              <p className="text-[var(--color-text-primary)] font-medium">
                Fetching transaction data…
              </p>
              <p className="text-sm text-[var(--color-text-secondary)]">
                {progress}% complete ({completedCount}/{selectedIds.size}{" "}
                accounts)
              </p>
            </div>
            <div className="w-full max-w-xs bg-white/5 rounded-full h-1.5 overflow-hidden">
              <div
                className="bg-emerald-500 h-full rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {/* Results */}
        {!isLoading && results.length > 0 && (
          <div className="flex flex-col">
            {/* Summary cards */}
            <div className="grid grid-cols-2 gap-3 p-6 pb-4 md:grid-cols-4">
              <div className="rounded-xl bg-white/5 border border-white/5 p-4">
                <p className="text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)] mb-1">
                  Incoming
                </p>
                <p className="text-xl font-bold text-emerald-400">
                  {fmt(totalIncoming)}
                </p>
              </div>
              <div className="rounded-xl bg-white/5 border border-white/5 p-4">
                <p className="text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)] mb-1">
                  Outgoing
                </p>
                <p className="text-xl font-bold text-red-400">
                  {fmt(totalOutgoing)}
                </p>
              </div>
              <div className="rounded-xl bg-white/5 border border-white/5 p-4">
                <p className="text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)] mb-1">
                  Net
                </p>
                <p
                  className={`text-xl font-bold ${net >= 0 ? "text-emerald-400" : "text-red-400"}`}
                >
                  {net >= 0 ? "+" : ""}
                  {fmt(net)}
                </p>
              </div>
              <div className="rounded-xl bg-white/5 border border-white/5 p-4">
                <p className="text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)] mb-1">
                  Sales
                </p>
                <p className="text-xl font-bold text-[var(--color-text-primary)]">
                  {fmt(totalSales)}
                </p>
              </div>
            </div>

            {/* Per-account table */}
            <div className="mx-6 mb-6 rounded-xl border border-white/5 overflow-hidden">
              <div className="max-h-[280px] overflow-y-auto custom-scrollbar">
                <table className="w-full text-sm">
                  <thead className="bg-white/5 sticky top-0">
                    <tr>
                      <th className="px-4 py-2.5 text-left text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)]">
                        Account
                      </th>
                      <th className="px-4 py-2.5 text-right text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)]">
                        In
                      </th>
                      <th className="px-4 py-2.5 text-right text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)]">
                        Out
                      </th>
                      <th className="px-4 py-2.5 text-right text-xs font-bold uppercase tracking-wider text-[var(--color-text-secondary)]">
                        Net
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                    {results.map((r) => {
                      const rowNet = r.incomingRobux - r.outgoingRobux;
                      return (
                        <tr
                          key={r.accountId}
                          className="hover:bg-white/5 transition-colors"
                        >
                          <td className="px-4 py-3 font-medium text-[var(--color-text-primary)]">
                            {r.error ? (
                              <span className="flex items-center gap-1.5 text-red-400">
                                <AlertCircle size={14} /> {r.username}
                              </span>
                            ) : (
                              r.username
                            )}
                          </td>
                          <td className="px-4 py-3 text-right">
                            <span className="flex items-center justify-end gap-1 text-emerald-400 font-medium">
                              <TrendingUp size={13} /> {fmt(r.incomingRobux)}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-right">
                            <span className="flex items-center justify-end gap-1 text-red-400 font-medium">
                              <TrendingDown size={13} /> {fmt(r.outgoingRobux)}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-right font-bold">
                            <span
                              className={
                                rowNet >= 0
                                  ? "text-emerald-400"
                                  : "text-red-400"
                              }
                            >
                              {rowNet >= 0 ? "+" : ""}
                              {fmt(rowNet)}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* Footer */}
        {!isLoading && (
          <div className="border-t border-white/10 px-6 py-4 flex justify-end">
            <button
              onClick={onClose}
              className="px-5 h-10 rounded-xl bg-white/5 border border-white/10 font-semibold text-[var(--color-text-primary)] text-sm transition hover:bg-white/10"
            >
              Close
            </button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default BulkTransactionsModal;

import React, { useState, useEffect } from "react";
import {
  Plus,
  Cookie,
  ShieldAlert,
  Loader2,
  LogIn,
  Info,
  Copy,
  Check,
  Upload,
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogClose,
} from "@renderer/components/UI/dialogs/Dialog";
import { Tabs } from "@renderer/components/UI/navigation/Tabs";
import { Button } from "@renderer/components/UI/buttons/Button";

interface AddAccountModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (
    cookie: string,
    importedVia?: "browser" | "cookie" | "cookielist",
  ) => Promise<void> | void;
}

const requestRobloxLoginCookie = async (): Promise<string> => {
  if (typeof window.api.openRobloxLoginWindow === "function") {
    return window.api.openRobloxLoginWindow();
  }

  const ipc = (window.electron as any)?.ipcRenderer;
  if (ipc?.invoke) {
    return ipc.invoke("open-roblox-login-window");
  }

  throw new Error("ROBLOX_LOGIN_UNAVAILABLE");
};

const AddAccountModal: React.FC<AddAccountModalProps> = ({
  isOpen,
  onClose,
  onAdd,
}) => {
  const [isLoading, setIsLoading] = useState(false);
  const [method, setMethod] = useState<"cookie" | "bulk" | "browser">("cookie");

  const [cookie, setCookie] = useState("");
  const [isCookieBlurred, setIsCookieBlurred] = useState(true);

  const [bulkCookies, setBulkCookies] = useState("");
  const [isBulkCookiesBlurred, setIsBulkCookiesBlurred] = useState(true);
  const [bulkImportProgress, setBulkImportProgress] = useState<{
    current: number;
    total: number;
    failed: string[];
  } | null>(null);

  const [browserLoginStatus, setBrowserLoginStatus] = useState<
    "idle" | "waiting" | "error"
  >("idle");
  const [browserLoginError, setBrowserLoginError] = useState("");

  const [copiedCookie, setCopiedCookie] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setIsLoading(false);
      setMethod("cookie");
      setBrowserLoginStatus("idle");
      setBrowserLoginError("");
      setIsCookieBlurred(true);
      setIsBulkCookiesBlurred(true);
      setBulkImportProgress(null);
    } else {
      setCookie("");
      setBulkCookies("");
      setIsCookieBlurred(true);
      setIsBulkCookiesBlurred(true);
      setBrowserLoginStatus("idle");
      setBrowserLoginError("");
      setCopiedCookie(false);
    }
  }, [isOpen]);

  useEffect(() => {
    if (method !== "browser") {
      setBrowserLoginStatus("idle");
      setBrowserLoginError("");
    }
  }, [method]);

  const handleBrowserLogin = async () => {
    if (isLoading) return;
    setBrowserLoginError("");
    setBrowserLoginStatus("waiting");
    setIsLoading(true);
    try {
      const cookieValue = await requestRobloxLoginCookie();
      await onAdd(cookieValue, "browser");
      onClose();
    } catch (error) {
      console.error("Failed to capture Roblox login:", error);
      setBrowserLoginStatus("error");
      if (error instanceof Error) {
        if (error.message === "LOGIN_WINDOW_CLOSED") {
          setBrowserLoginError(
            "Login window closed before completing sign-in.",
          );
        } else if (error.message === "ROBLOX_LOGIN_UNAVAILABLE") {
          setBrowserLoginError(
            "This build needs to be restarted to enable Roblox login. Please fully reload the app.",
          );
        } else {
          setBrowserLoginError(
            "Failed to capture the Roblox session. Please try again.",
          );
        }
      } else {
        setBrowserLoginError(
          "Failed to capture the Roblox session. Please try again.",
        );
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkImport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!bulkCookies.trim() || isLoading) return;

    const cookiesToImport = bulkCookies
      .split("\n")
      .map((c) => c.trim())
      .filter((c) => c.length > 0);

    if (cookiesToImport.length === 0) return;

    setIsLoading(true);
    setBulkImportProgress({
      current: 0,
      total: cookiesToImport.length,
      failed: [],
    });

    const failedCookies: string[] = [];
    let successCount = 0;
    for (let i = 0; i < cookiesToImport.length; i++) {
      try {
        setBulkImportProgress((prev) =>
          prev ? { ...prev, current: i + 1 } : null,
        );
        await onAdd(cookiesToImport[i], "cookielist");
        successCount++;
      } catch (error) {
        failedCookies.push(`Cookie ${i + 1}`);
      }
    }

    setBulkImportProgress(null);
    setIsLoading(false);
    setBulkCookies("");
    onClose();
    // Parent will show individual success/failure notifications per account
    // Additional summary is shown here only if there were failures
    if (failedCookies.length > 0 && successCount === 0) {
      // If everything failed, the modal has already closed — parent handles error notifications
      console.warn(`[BulkImport] All ${failedCookies.length} imports failed`);
    }
  };

  const handleCookieSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!cookie.trim() || isLoading) return;

    setIsLoading(true);
    try {
      await onAdd(cookie, "cookie");
      setCookie("");
      onClose(); // Close on success
    } finally {
      setIsLoading(false);
    }
  };

  const handleGetCookie = async () => {
    if (isLoading) return;
    try {
      const cookieValue = await requestRobloxLoginCookie();
      setCookie(cookieValue);
      setIsCookieBlurred(true);
    } catch (error) {
      console.error("Failed to get cookie:", error);
    }
  };

  const handleCopyCookie = async () => {
    if (cookie.trim()) {
      await navigator.clipboard.writeText(cookie);
      setCopiedCookie(true);
      setTimeout(() => setCopiedCookie(false), 2000);
    }
  };

  return (
    <Dialog isOpen={isOpen} onClose={onClose}>
      <DialogContent className="w-full max-w-md bg-[var(--color-app-bg)] border border-[var(--color-border)] rounded-xl shadow-2xl overflow-hidden ring-1 ring-[var(--accent-color-ring)]">
        <div className="flex items-center justify-between p-4 border-b border-[var(--color-border)] bg-[var(--color-app-bg)]">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-[var(--color-surface)] rounded-lg">
              {method === "bulk" ? (
                <Upload
                  size={20}
                  className="text-[var(--color-text-secondary)]"
                />
              ) : method === "cookie" ? (
                <Cookie
                  size={20}
                  className="text-[var(--color-text-secondary)]"
                />
              ) : (
                <LogIn
                  size={20}
                  className="text-[var(--color-text-secondary)]"
                />
              )}
            </div>
            <div>
              <h3 className="text-xl font-semibold text-[var(--color-text-primary)]">
                Add Account
              </h3>
              <p className="text-sm text-[var(--color-text-muted)]">
                {method === "bulk"
                  ? "Bulk Import Cookies"
                  : method === "cookie"
                    ? "Import via Cookie"
                    : "Official Roblox Login"}
              </p>
            </div>
          </div>
          <DialogClose disabled={isLoading} />
        </div>

        {/* Tabs */}
        <div className="flex justify-center px-6">
          <Tabs
            tabs={[
              { id: "cookie", label: "Single Cookie", icon: Cookie },
              { id: "bulk", label: "Bulk Import", icon: Upload },
              { id: "browser", label: "Login / Code", icon: LogIn },
            ]}
            activeTab={method}
            onTabChange={(tabId) =>
              setMethod(tabId as "cookie" | "bulk" | "browser")
            }
            layoutId="addAccountTabIndicator"
            tabClassName="pressable"
          />
        </div>

        <div className="p-6 max-h-[60vh] overflow-y-auto">
          {method === "cookie" ? (
            <form onSubmit={handleCookieSubmit} className="space-y-4">
              <div className="bg-yellow-500/10 border border-yellow-500/20 rounded-lg p-3 flex gap-3 items-start">
                <ShieldAlert
                  className="text-yellow-500 shrink-0 mt-0.5"
                  size={18}
                />
                <p className="text-s text-yellow-200/80 leading-relaxed">
                  Your security is important. Cookies are processed locally and
                  encrypted.
                </p>
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <label
                    htmlFor="cookieInput"
                    className="text-sm font-medium text-[var(--color-text-secondary)]"
                  >
                    .ROBLOSECURITY Cookie
                  </label>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={() => setIsCookieBlurred((prev) => !prev)}
                      className="pressable text-xs text-[var(--color-text-muted)] hover:text-[var(--color-text-secondary)] transition-colors"
                    >
                      {isCookieBlurred ? "Show" : "Hide"}
                    </button>
                    <button
                      type="button"
                      onClick={handleCopyCookie}
                      disabled={!cookie.trim()}
                      className="pressable text-xs text-[var(--color-text-muted)] hover:text-[var(--color-text-secondary)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-1"
                    >
                      {copiedCookie ? (
                        <>
                          <Check size={14} /> Copied
                        </>
                      ) : (
                        <>
                          <Copy size={14} /> Copy
                        </>
                      )}
                    </button>
                  </div>
                </div>
                <textarea
                  id="cookieInput"
                  value={cookie}
                  onChange={(e) => setCookie(e.target.value)}
                  disabled={isLoading}
                  placeholder="_|WARNING:-DO-NOT-SHARE-THIS.--Sharing-this-will-allow-someone-to-log-in-to-your-account-and-steal-your-ROBUX-and-items.|_..."
                  className="w-full bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg px-4 py-3 text-sm text-[var(--color-text-primary)] placeholder:text-[var(--color-text-muted)] focus:outline-none focus:ring-1 focus:ring-[var(--color-border-strong)] focus:border-[var(--accent-color)] transition-all min-h-[120px] resize-none font-mono disabled:opacity-50 disabled:cursor-not-allowed"
                  style={
                    isCookieBlurred
                      ? ({ WebkitTextSecurity: "disc" } as React.CSSProperties)
                      : undefined
                  }
                  autoFocus
                />
              </div>

              <div className="pt-2 flex gap-3 justify-center">
                <Button
                  type="button"
                  onClick={handleGetCookie}
                  disabled={isLoading}
                  variant="secondary"
                  size="sm"
                  className="flex-1"
                >
                  Get Cookie
                </Button>
                <Button
                  type="submit"
                  disabled={!cookie.trim() || isLoading}
                  variant="default"
                  size="sm"
                  className="flex-[2] flex items-center justify-center gap-2"
                >
                  <Plus size={18} />
                  <span>{isLoading ? "Importing..." : "Import Account"}</span>
                </Button>
              </div>
            </form>
          ) : method === "bulk" ? (
            <form onSubmit={handleBulkImport} className="space-y-4">
              <div className="bg-blue-500/10 border border-blue-500/20 rounded-lg p-3 flex gap-3 items-start">
                <Info className="text-blue-400 shrink-0 mt-0.5" size={18} />
                <p className="text-s text-blue-100/80 leading-relaxed">
                  Paste multiple cookies separated by new lines (one cookie per
                  line).
                </p>
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <label
                    htmlFor="bulkInput"
                    className="text-sm font-medium text-[var(--color-text-secondary)]"
                  >
                    Cookies List
                  </label>
                  <button
                    type="button"
                    onClick={() => setIsBulkCookiesBlurred((prev) => !prev)}
                    className="pressable text-xs text-[var(--color-text-muted)] hover:text-[var(--color-text-secondary)] transition-colors"
                  >
                    {isBulkCookiesBlurred ? "Show" : "Hide"}
                  </button>
                </div>
                <textarea
                  id="bulkInput"
                  value={bulkCookies}
                  onChange={(e) => setBulkCookies(e.target.value)}
                  disabled={isLoading}
                  placeholder="Paste cookies here (one per line)..."
                  className="w-full bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg px-4 py-3 text-sm text-[var(--color-text-primary)] placeholder:text-[var(--color-text-muted)] focus:outline-none focus:ring-1 focus:ring-[var(--color-border-strong)] focus:border-[var(--accent-color)] transition-all min-h-[160px] resize-none font-mono disabled:opacity-50 disabled:cursor-not-allowed"
                  style={
                    isBulkCookiesBlurred
                      ? ({ WebkitTextSecurity: "disc" } as React.CSSProperties)
                      : undefined
                  }
                  autoFocus
                />
              </div>

              {bulkImportProgress && (
                <div className="bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg p-4 space-y-2">
                  <p className="text-sm text-[var(--color-text-secondary)] font-medium">
                    Importing {bulkImportProgress.current} of{" "}
                    {bulkImportProgress.total}
                  </p>
                  <div className="w-full bg-[var(--color-surface-hover)] rounded-full h-2 overflow-hidden">
                    <div
                      className="bg-blue-500 h-full transition-all duration-300"
                      style={{
                        width: `${(bulkImportProgress.current / bulkImportProgress.total) * 100}%`,
                      }}
                    />
                  </div>
                </div>
              )}

              <div className="pt-2 flex gap-3 justify-center">
                <Button
                  type="button"
                  onClick={onClose}
                  disabled={isLoading}
                  variant="secondary"
                  size="sm"
                  className="flex-1"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={!bulkCookies.trim() || isLoading}
                  variant="default"
                  size="sm"
