import React, { useState, useEffect } from "react";
import { Edit3, CheckCircle2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogBody,
  DialogFooter,
} from "@renderer/components/UI/dialogs/Dialog";
import { Button } from "@renderer/components/UI/buttons/Button";
import { Account } from "@renderer/types";
import { useNotification } from "@renderer/system/stores/useSnackbarStore";
import { useUIStore } from "@renderer/stores/useUIStore";
import {
  bulkOperationLimiter,
  executeWithRetry,
  isRateLimitError,
  sleep,
} from "@renderer/lib/rateLimiter";

interface ChangeDisplayNameModalProps {
  accounts: Account[];
  selectedIds: Set<string>;
  onAccountsChange: (accounts: Account[]) => void;
}

export const ChangeDisplayNameModal = ({
  accounts,
  selectedIds,
  onAccountsChange,
}: ChangeDisplayNameModalProps) => {
  const isOpen = useUIStore((s) => s.modals.changeDisplayName);
  const closeModal = useUIStore((s) => s.closeModal);
  const { showNotification } = useNotification();

  const [newName, setNewName] = useState("");
  const [useSequential, setUseSequential] = useState(false);
  const [startingNumber, setStartingNumber] = useState(1);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processedCount, setProcessedCount] = useState(0);
  const [failedCount, setFailedCount] = useState(0);
  const [currentAccountLabel, setCurrentAccountLabel] = useState("");
  const [resultMessages, setResultMessages] = useState<string[]>([]);

  useEffect(() => {
    if (isOpen) {
      setNewName("");
      setUseSequential(selectedIds.size > 1);
      setStartingNumber(1);
      setIsProcessing(false);
      setProcessedCount(0);
      setFailedCount(0);
      setCurrentAccountLabel("");
      setResultMessages([]);
    }
  }, [isOpen, selectedIds.size]);

  const handleSave = async () => {
    if (!newName.trim()) {
      showNotification("Please enter a display name", "error");
      return;
    }

    setIsProcessing(true);
    setProcessedCount(0);
    setFailedCount(0);
    setCurrentAccountLabel("");
    setResultMessages([]);
    showNotification("Starting display name update...", "info");

    const updatedAccounts = [...accounts];
    let counter = startingNumber;
    let updateCount = 0;
    let failedCountLocal = 0;
    const resultEntries: string[] = [];

    for (const acc of updatedAccounts) {
      if (!selectedIds.has(acc.id)) continue;

      const nameToApply =
        useSequential && selectedIds.size > 1
          ? `${newName.trim()}_${counter}`
          : newName.trim();

      setCurrentAccountLabel(acc.username || acc.displayName || acc.id);

      if (acc.cookie && acc.cookie.trim().length > 0) {
        try {
          const result = await executeWithRetry(
            bulkOperationLimiter,
            async () => {
              return await window.api.user.setRobloxDisplayName(
                acc.cookie!,
                nameToApply,
              );
            },
            {
              retryCondition: (error) => {
                if (isRateLimitError(error)) return true;
                const maybeError = error as any;
                const message =
                  typeof maybeError?.message === "string"
                    ? maybeError.message
                    : typeof error === "string"
                      ? error
                      : "";
                return /(?:429|rate limit|too many requests)/i.test(message);
              },
            },
          );

          if (result && result.success) {
            const index = updatedAccounts.findIndex((a) => a.id === acc.id);
            if (index !== -1) {
              updatedAccounts[index] = { ...acc, displayName: nameToApply };
            }
            updateCount++;
            resultEntries.push(`✓ ${acc.username || acc.id}`);
          } else {
            failedCountLocal++;
            const errorMessage = result?.error || "Rejected";
            resultEntries.push(`✗ ${acc.username || acc.id}: ${errorMessage}`);
          }
        } catch (err: any) {
          failedCountLocal++;
          resultEntries.push(
            `✗ ${acc.username || acc.id}: ${err?.message || "Unknown error"}`,
          );
        }

        await sleep(1500);
      } else {
        const index = updatedAccounts.findIndex((a) => a.id === acc.id);
        if (index !== -1) {
          updatedAccounts[index] = { ...acc, displayName: nameToApply };
        }
        updateCount++;
        resultEntries.push(`⚠ ${acc.username || acc.id}: local update applied`);
      }

      if (useSequential) counter++;
      setProcessedCount((prev) => prev + 1);
      setFailedCount(failedCountLocal);
      setResultMessages(resultEntries.slice(-5));
    }

    await window.api.account.saveAccounts(updatedAccounts);
    onAccountsChange(updatedAccounts);

    setIsProcessing(false);
    setCurrentAccountLabel("");

    if (failedCountLocal > 0) {
      showNotification(
        `Updated ${updateCount} accounts, ${failedCountLocal} failed. Check results in the modal.`,
        "warning",
      );
    } else {
      showNotification(
        `Successfully updated ${updateCount} account${updateCount === 1 ? "" : "s"}.`,
        "success",
      );
    }

    closeModal("changeDisplayName");
  };

  return (
    <Dialog isOpen={isOpen} onClose={() => closeModal("changeDisplayName")}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-blue-500/10 rounded-xl border border-blue-500/20">
              <Edit3 size={20} className="text-blue-400" />
            </div>
            <div>
              <DialogTitle>Change Display Name</DialogTitle>
              <p className="text-sm text-[var(--color-text-muted)] mt-1">
                Editing profile sync data for {selectedIds.size} account(s)
              </p>
            </div>
          </div>
        </DialogHeader>

        <DialogBody className="space-y-4">
          <div className="space-y-2">
            <label className="text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider">
              New Display Name
            </label>
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="e.g. MyBot"
              disabled={isProcessing}
              className="w-full h-10 bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg px-3 text-sm focus:border-[var(--accent-color)] focus:ring-1 focus:ring-[var(--accent-color)] transition-all placeholder-[var(--color-text-muted)] text-[var(--color-text-primary)] disabled:opacity-60"
              autoFocus
            />
          </div>

          {isProcessing && (
            <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-surface-muted)] p-4 text-sm text-[var(--color-text-primary)] space-y-2">
              <div className="flex items-center justify-between gap-3">
                <span>
                  Processing {processedCount}/{selectedIds.size}
                </span>
                <span className="font-medium text-[var(--accent-color)]">
                  {currentAccountLabel}
                </span>
              </div>
              <div className="h-2 w-full overflow-hidden rounded-full bg-[var(--color-border)]">
                <div
                  className="h-full rounded-full bg-[var(--accent-color)] transition-all"
                  style={{
                    width: `${(processedCount / Math.max(1, selectedIds.size)) * 100}%`,
                  }}
                />
              </div>
              {resultMessages.length > 0 && (
                <div className="max-h-28 overflow-y-auto rounded-lg bg-black/10 p-2 text-xs text-[var(--color-text-secondary)]">
                  {resultMessages.slice(-5).map((message, index) => (
                    <div key={`${message}-${index}`} className="truncate">
                      {message}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {selectedIds.size > 1 && (
            <div className="space-y-3 pt-2">
              <label className="flex items-center gap-2 cursor-pointer group">
                <div className="relative flex items-center justify-center">
                  <input
                    type="checkbox"
                    checked={useSequential}
                    onChange={(e) => setUseSequential(e.target.checked)}
                    className="peer sr-only"
                  />
                  <div className="w-5 h-5 rounded border-2 border-[var(--color-border)] peer-checked:border-[var(--accent-color)] peer-checked:bg-[var(--accent-color)] transition-all"></div>
                  <CheckCircle2
                    size={14}
                    className="absolute text-[var(--color-text-primary)] opacity-0 peer-checked:opacity-100 transition-opacity pointer-events-none"
                    strokeWidth={3}
                  />
                </div>
                <span className="text-sm font-medium text-[var(--color-text-secondary)] group-hover:text-[var(--color-text-primary)] transition-colors">
                  Append sequential numbers (e.g. {newName || "Name"} 1,{" "}
                  {newName || "Name"} 2)
                </span>
              </label>

              {useSequential && (
                <div className="pl-7 space-y-1.5 animate-in slide-in-from-top-2 fade-in duration-200">
                  <label className="text-xs font-semibold text-[var(--color-text-muted)]">
                    Starting Number
                  </label>
                  <input
                    type="number"
                    value={startingNumber}
                    onChange={(e) =>
                      setStartingNumber(parseInt(e.target.value) || 1)
                    }
                    min={1}
                    className="w-full h-9 bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg px-3 text-sm focus:border-[var(--accent-color)] transition-all text-[var(--color-text-primary)]"
                  />
                </div>
              )}
            </div>
          )}
        </DialogBody>

        <DialogFooter>
          <Button
            variant="ghost"
            onClick={() => closeModal("changeDisplayName")}
            disabled={isProcessing}
          >
            Cancel
          </Button>
          <Button
            variant="default"
            onClick={handleSave}
            disabled={isProcessing}
          >
            {isProcessing ? "Updating…" : "Save Changes"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import React, { useState, useCallback, useMemo } from "react";
import { motion } from "framer-motion";
import { Play, Flame, Loader2, Sparkles, X } from "lucide-react";
import { Account } from "@renderer/types";
import { useNotification } from "@renderer/features/system/stores/useSnackbarStore";
import { Button } from "@renderer/components/UI/buttons/Button";

interface WarmingTask {
  id: string;
  name: string;
  enabled: boolean;
  description: string;
}

const DEFAULT_WARMING_TASKS: WarmingTask[] = [
  {
    id: "view_catalog",
    name: "Browse free items",
    description: "Open a few catalog listings and keep the account active.",
    enabled: true,
  },
  {
    id: "equip_free_items",
    name: "Equip random free items",
    description: "Swap in a few free items to look active and normal.",
    enabled: true,
  },
  {
    id: "friends_tab",
    name: "Open friends tab",
    description: "Open the friend list so the account looks active.",
    enabled: true,
  },
];

interface WarmingModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedAccounts: Account[];
}

export const WarmingModal = ({
  isOpen,
  onClose,
  selectedAccounts,
}: WarmingModalProps) => {
  const { showNotification } = useNotification();
  const [isWarming, setIsWarming] = useState(false);
  const [warmingProgress, setWarmingProgress] = useState({
    completed: 0,
    total: 0,
  });
  const [warmingTasks, setWarmingTasks] = useState<WarmingTask[]>(
    DEFAULT_WARMING_TASKS,
  );

  const handleToggleTask = useCallback((taskId: string) => {
    setWarmingTasks((prev) =>
      prev.map((task) =>
        task.id === taskId ? { ...task, enabled: !task.enabled } : task,
      ),
    );
  }, []);

  const handleStartWarming = useCallback(async () => {
    if (selectedAccounts.length === 0) {
      showNotification("No accounts selected", "warning");
      return;
    }

    const enabledTasks = warmingTasks.filter((task) => task.enabled);
    if (enabledTasks.length === 0) {
      showNotification("Select at least one warming task", "warning");
      return;
    }

    setIsWarming(true);
    setWarmingProgress({ completed: 0, total: selectedAccounts.length });

    try {
      for (let index = 0; index < selectedAccounts.length; index += 1) {
        const account = selectedAccounts[index];
        setWarmingProgress((prev) => ({ ...prev, completed: index + 1 }));

        if (account.cookie) {
          await new Promise((resolve) => setTimeout(resolve, 900));
        } else {
          await new Promise((resolve) => setTimeout(resolve, 500));
        }
      }

      showNotification(
        `Warm cycle complete for ${selectedAccounts.length} account${selectedAccounts.length === 1 ? "" : "s"}`,
        "success",
      );
      setIsWarming(false);
      setWarmingProgress({ completed: 0, total: 0 });
      onClose();
    } catch (error) {
      console.error(error);
      showNotification("Warm cycle failed", "error");
      setIsWarming(false);
      setWarmingProgress({ completed: 0, total: 0 });
    }
  }, [selectedAccounts, warmingTasks, showNotification, onClose]);

  const progressPercent =
    warmingProgress.total > 0
      ? (warmingProgress.completed / warmingProgress.total) * 100
      : 0;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        transition={{ duration: 0.2 }}
        className="w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl bg-[var(--color-surface)] border border-[var(--color-border)] shadow-2xl"
      >
        {/* Header */}
        <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[var(--color-border)] bg-[var(--color-surface-strong)] p-6">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg border border-orange-500/30 bg-orange-500/10 text-orange-400">
              <Flame className="h-5 w-5" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-[var(--color-text-primary)]">
                Warm Accounts
              </h2>
              <p className="text-xs text-[var(--color-text-secondary)]">
                Keep fresh accounts looking active
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] transition-colors p-1.5 hover:bg-[var(--color-surface-hover)] rounded-lg"
          >
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          <div className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-surface-hover)] p-4">
            <div className="grid gap-4 lg:grid-cols-[1fr_0.5fr]">
              <div>
                <div className="mb-3 flex items-center justify-between">
                  <label className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--color-text-muted)]">
                    Warming Tasks
                  </label>
                  <span className="text-xs text-[var(--color-text-muted)]">
                    {warmingTasks.filter((task) => task.enabled).length} enabled
                  </span>
                </div>

                <div className="space-y-2">
                  {warmingTasks.map((task) => (
                    <button
                      key={task.id}
                      type="button"
                      onClick={() => handleToggleTask(task.id)}
                      disabled={isWarming}
                      className="flex w-full items-center gap-3 rounded-xl border border-[var(--color-border)] bg-[var(--color-surface)] p-3 text-left transition-colors hover:border-[var(--color-border-strong)] disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <input
                        type="checkbox"
                        checked={task.enabled}
                        disabled={isWarming}
                        onChange={() => handleToggleTask(task.id)}
                        className="h-4 w-4 rounded border-[var(--color-border)] accent-[var(--accent-color)]"
                        onClick={(e) => e.stopPropagation()}
                      />
                      <div className="flex-1 min-w-0">
                        <div className="text-sm font-medium text-[var(--color-text-primary)]">
                          {task.name}
                        </div>
                        <div className="mt-0.5 text-xs text-[var(--color-text-muted)]">
                          {task.description}
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex flex-col gap-4 rounded-xl border border-[var(--color-border)] bg-[var(--color-surface)] p-4">
                <div>
                  <div className="text-xs font-bold text-[var(--color-text-muted)] uppercase tracking-wider mb-2">
                    Selected Accounts
                  </div>
                  <div className="text-3xl font-bold text-[var(--color-text-primary)]">
                    {selectedAccounts.length}
                  </div>
                  <div className="text-xs text-[var(--color-text-muted)]">
                    will be warmed
                  </div>
                </div>
                <div className="h-px bg-[var(--color-border)]" />
                <div className="flex-1 overflow-y-auto max-h-40">
                  <div className="space-y-1">
                    {selectedAccounts.map((account) => (
                      <div
                        key={account.id}
                        className="text-xs text-[var(--color-text-muted)] truncate px-2 py-1 rounded bg-[var(--color-surface-hover)]"
                        title={account.displayName || account.username}
                      >
                        {account.displayName || account.username}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Progress */}
          {isWarming && warmingProgress.total > 0 && (
            <div className="rounded-xl border border-[var(--color-border)] bg-[var(--color-surface-hover)] p-4 space-y-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-sm font-medium text-[var(--color-text-primary)]">
                  <Loader2 size={16} className="animate-spin" />
                  Warming in progress
                </div>
                <div className="text-xs text-[var(--color-text-muted)]">
                  {warmingProgress.completed} / {warmingProgress.total}
                </div>
              </div>
              <div className="w-full bg-[var(--color-surface)] rounded-full h-2 overflow-hidden">
                <motion.div
                  className="h-full bg-gradient-to-r from-orange-500 to-amber-500"
                  animate={{ width: `${progressPercent}%` }}
                  transition={{ duration: 0.3 }}
                />
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="sticky bottom-0 flex items-center justify-between border-t border-[var(--color-border)] bg-[var(--color-surface-strong)] p-6 gap-3">
          <Button variant="secondary" onClick={onClose} disabled={isWarming}>
            Cancel
          </Button>
          <Button
            variant="default"
            onClick={handleStartWarming}
            disabled={isWarming || selectedAccounts.length === 0}
            className="gap-2"
          >
            {isWarming ? (
              <>
                <Loader2 size={16} className="animate-spin" />
                Warming...
              </>
            ) : (
              <>
                <Play size={16} />
                Start Warming
              </>
            )}
          </Button>
        </div>
      </motion.div>
    </div>
  );
};

