interface AssetPricingProps {
  details: AssetDetails;
  onPurchaseSuccess?: (details: AssetDetails, price: number | string) => void;
  onPurchaseError?: (error: string) => void;
  cookie?: string;
  userId?: string;
}

export const AssetPricing: React.FC<AssetPricingProps> = ({
  details,
  onPurchaseSuccess,
  onPurchaseError,
  cookie,
  userId,
}) => {
  const [isPurchasing, setIsPurchasing] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [purchaseProgress, setPurchaseProgress] = useState<{
    current: number;
    total: number;
    success: number;
    failed: number;
  } | null>(null);

  const { accounts } = useAccountsManager();
  const selectedIds = useSelectedIds();
  const isBulkMode = selectedIds.size > 1;

  const targetAccounts = useMemo<PurchaseTargetAccount[]>(() => {
    if (isBulkMode) {
      return accounts
        .filter(
          (account): account is Account & { cookie: string } =>
            selectedIds.has(account.id) && Boolean(account.cookie),
        )
        .map((account) => ({
          id: account.id,
          userId: account.userId,
          username: account.username,
          cookie: account.cookie,
        }));
    }
    return cookie && userId
      ? [{ cookie, userId, id: userId, username: "You" }]
      : [];
  }, [isBulkMode, accounts, selectedIds, cookie, userId]);

  const [ownedAccounts, setOwnedAccounts] = useState<Set<string>>(new Set());
  const [userBalance, setUserBalance] = useState<number | null>(null);
  const purchaseInProgressRef = useRef(false); // Guard against double purchases

  // Logic for display price
  let displayPrice: string | number = "Off Sale";
  const isLimitedItem = details.isLimited || details.isLimitedUnique;

  // For limited/collectible items, prioritize the collectible resale price
  if (
    isLimitedItem &&
    details.collectibleLowestResalePrice &&
    details.collectibleLowestResalePrice > 0
  ) {
    displayPrice = details.collectibleLowestResalePrice;
  } else if (details.lowestPrice && details.lowestPrice > 0) {
    // Catalog API lowestPrice for limiteds
    displayPrice = details.lowestPrice;
  } else if (details.price != null) {
    if (details.price === 0 && details.isPurchasable && !isLimitedItem) {
      // Only show "Free" if it's actually purchasable and not a limited item
      displayPrice = "Free";
    } else if (details.price > 0) {
      displayPrice = details.price;
    } else if (!details.isPurchasable) {
      displayPrice = "Off Sale";
    }
  }

  // Check ownership and balance
  React.useEffect(() => {
    let isMounted = true;
    const checkStatus = async () => {
      if (targetAccounts.length === 0 || !details.id) return;

      try {
        const ownedSet = new Set<string>();
        await Promise.all(
          targetAccounts.map(async (acc) => {
            try {
              const owned = await window.api.checkAssetOwnership(
                acc.cookie,
                Number(acc.userId || acc.id),
                details.id!,
                "Asset",
              );
              if (owned) ownedSet.add(acc.id);
            } catch (err) {
              console.warn(`Failed ownership check for ${acc.id}:`, err);
            }
          }),
        );
        if (isMounted) setOwnedAccounts(ownedSet);

        // Get balance for the primary account to show in UI (only if single mode, for simplicity)
        if (
          !isBulkMode &&
          !ownedSet.has(targetAccounts[0]?.id) &&
          displayPrice !== "Off Sale"
        ) {
          const stats = await window.api.fetchAccountStats(
            targetAccounts[0].cookie,
          );
          if (isMounted && stats) setUserBalance(stats.robuxBalance);
        }
      } catch (err) {
        console.warn("Failed to check ownership or balance:", err);
      }
    };

    checkStatus();
    return () => {
      isMounted = false;
    };
  }, [targetAccounts, details.id, displayPrice, isBulkMode]);

  const accountsNeedingPurchase = targetAccounts.filter(
    (a) => !ownedAccounts.has(a.id),
  );
  const isFullyOwned =
    accountsNeedingPurchase.length === 0 && targetAccounts.length > 0;
  const totalCost =
    accountsNeedingPurchase.length *
    (typeof displayPrice === "number" ? displayPrice : 0);

  // Check if item can be purchased (has collectibleItemId and is purchasable)
  const canPurchase =
    !isFullyOwned &&
    displayPrice !== "Off Sale" &&
    !!details.collectibleItemId &&
    targetAccounts.length > 0;
  const needsLogin = targetAccounts.length === 0 && displayPrice !== "Off Sale";
  const isPurchaseUnavailable = !needsLogin && !canPurchase && !isFullyOwned;

  const handlePurchaseClick = () => {
    if (needsLogin) {
      // prompt user to login before purchasing
      alert("You must be logged in to purchase this item.");
      return;
    }
    if (!canPurchase) return;
    setShowConfirm(true);
  };

  const handleConfirmPurchase = async () => {
    // Guard against double purchases (React StrictMode can cause double calls)
    if (purchaseInProgressRef.current) return;
    if (
      !canPurchase ||
      !details.collectibleItemId ||
      targetAccounts.length === 0
    )
      return;

    purchaseInProgressRef.current = true;
    setShowConfirm(false);
    setIsPurchasing(true);
    try {
      const expectedPrice = typeof displayPrice === "number" ? displayPrice : 0;
      const expectedSellerId = details.creatorTargetId || 0;
      let successCount = 0;
      let lastError = "";
      let currentIdx = 0;
      const purchaseResults: Array<{
        accountId: string;
        success: boolean;
        error?: string;
      }> = [];

      // For bulk mode, execute purchases sequentially with rate limiting
      // For single account, execute normally but still with rate limiting to be safe
      if (isBulkMode) {
        setPurchaseProgress({
          current: 0,
          total: accountsNeedingPurchase.length,
          success: 0,
          failed: 0,
        });
        let currentSuccess = 0;
        let currentFailed = 0;
        // Sequential execution with rate limiting for bulk purchases
        for (const acc of accountsNeedingPurchase) {
          try {
            // Check cookie validity locally before attempting purchase
            const authCheck = await window.api
              .validateCookie(acc.cookie)
              .catch(() => null);
            if (!authCheck) {
              lastError = "Invalid cookie (Unauthenticated)";
              purchaseResults.push({
                accountId: acc.id,
                success: false,
                error: lastError,
              });
              currentFailed++;
            } else {
              const result = await executeWithRetry(
                catalogPurchaseLimiter,
                async () => {
                  return await window.api.purchaseCatalogItem(
                    acc.cookie,
                    details.collectibleItemId!,
                    expectedPrice,
                    expectedSellerId,
                    details.collectibleProductId || "",
                    acc.userId || acc.id,
                    crypto.randomUUID(),
                  );
                },
                { retryCondition: isRateLimitError },
              );

              if (result.purchased) {
                setOwnedAccounts((prev) => new Set(prev).add(acc.id));
                successCount++;
                currentSuccess++;
                purchaseResults.push({ accountId: acc.id, success: true });
              } else {
                const error =
                  result.errorMessage || result.reason || "Unknown error";
                lastError = error;
                purchaseResults.push({
                  accountId: acc.id,
                  success: false,
                  error,
                });
                currentFailed++;
              }
            }
          } catch (err: any) {
            let errorMsg = err.message || "An error occurred";
            if (errorMsg.includes("429")) errorMsg = "Rate Limited (429)";
            if (errorMsg.includes("403")) errorMsg = "Forbidden (403)";
            lastError = errorMsg;
            purchaseResults.push({
              accountId: acc.id,
              success: false,
              error: errorMsg,
            });
          }
          currentIdx++;
          setPurchaseProgress({
            current: currentIdx,
            total: accountsNeedingPurchase.length,
            success: currentSuccess,
            failed: currentFailed,
          });

          if (currentIdx < accountsNeedingPurchase.length) {
            await sleep(3000);
          }
        }

        // Show summary notification or success based on results
        if (currentSuccess > 0) {
          onPurchaseSuccess?.(
            details,
            isBulkMode ? currentSuccess * expectedPrice : displayPrice,
          );
        } else if (currentFailed > 0) {
          onPurchaseError?.(
            `Purchase failed for all. Last error: ${lastError}`,
          );
        }
      } else {
        // Single account purchase with rate limiting
        try {
          const result = await executeWithRetry(
            catalogPurchaseLimiter,
            async () => {
              return await window.api.purchaseCatalogItem(
                accountsNeedingPurchase[0].cookie,
                details.collectibleItemId!,
                expectedPrice,
                expectedSellerId,
                details.collectibleProductId || "",
                accountsNeedingPurchase[0].userId ||
                  accountsNeedingPurchase[0].id,
                crypto.randomUUID(),
              );
            },
            { retryCondition: isRateLimitError },
          );

          if (result.purchased) {
            setOwnedAccounts((prev) =>
              new Set(prev).add(accountsNeedingPurchase[0].id),
            );
            successCount++;
          } else {
            lastError = result.errorMessage || result.reason || "Unknown error";
          }
        } catch (err: any) {
          lastError = err.message || "An error occurred";
        }
      }

      if (!isBulkMode) {
        if (successCount > 0) {
          onPurchaseSuccess?.(details, displayPrice);
        } else if (lastError) {
          onPurchaseError?.(lastError);
        }
      }
    } catch (err: any) {
      console.error("Purchase error:", err);
      onPurchaseError?.(err.message || "An error occurred during purchase");
    } finally {
      setIsPurchasing(false);
      purchaseInProgressRef.current = false;
    }
  };

  return (
    <div className="p-4 bg-[var(--color-surface)]/50 border border-[var(--color-border)] rounded-xl flex items-center justify-between relative">
      <div>
        <div className="text-sm text-[var(--color-text-muted)] mb-1">Price</div>
        <div className="text-xl font-bold text-[var(--color-text-primary)] flex items-center gap-1">
          {typeof displayPrice === "number" ? (
            <>
              {displayPrice.toLocaleString()}
              <RobuxIcon className="w-4 h-4 ml-1" />
            </>
          ) : (
            <span
              className={
                displayPrice === "Free"
                  ? "text-[var(--color-text-primary)]"
                  : "text-[var(--color-text-secondary)]"
              }
            >
              {displayPrice}
            </span>
          )}
        </div>
      </div>
      <Button
        disabled={
          isFullyOwned ||
          displayPrice === "Off Sale" ||
          isPurchaseUnavailable ||
          isPurchasing
        }
        onClick={handlePurchaseClick}
        className={cn(
          "min-w-[120px]",
          isFullyOwned
            ? "bg-[var(--color-surface-hover)] text-[var(--color-text-secondary)] cursor-not-allowed hover:bg-[var(--color-surface-hover)]"
            : displayPrice === "Off Sale"
              ? "opacity-50 cursor-not-allowed bg-transparent text-[var(--color-text-secondary)] border-2 border-dashed border-[var(--color-border-strong)] hover:bg-transparent"
              : "bg-emerald-600 hover:bg-emerald-500 text-[var(--color-text-primary)]",
        )}
      >
        {isPurchasing ? (
          <Loader2 size={18} className="mr-2 animate-spin" />
        ) : isFullyOwned ? (
          <span className="flex items-center">
            <span className="mr-2">✓</span>{" "}
            {isBulkMode ? `Owned by All (${targetAccounts.length})` : "Owned"}
          </span>
        ) : needsLogin ? (
          <span className="flex items-center">
            <ShoppingCart size={18} className="mr-2" />
            Log in to purchase
          </span>
        ) : isPurchaseUnavailable ? (
          <span className="flex items-center">
            <ShoppingCart size={18} className="mr-2" />
            Unavailable
          </span>
        ) : (
          <span className="flex items-center flex-col py-1">
            <span className="flex items-center">
              <ShoppingCart size={18} className="mr-2" />
              {isBulkMode
                ? `Buy for All (${accountsNeedingPurchase.length})`
                : "Buy"}
            </span>
            {isBulkMode && ownedAccounts.size > 0 && (
              <span className="text-[10px] text-emerald-200 opacity-80 font-normal">
                {ownedAccounts.size} already own it
              </span>
            )}
          </span>
        )}
      </Button>

      {/* Bulk Purchase Progress Bar */}
      {isPurchasing && purchaseProgress && isBulkMode && (
        <div className="absolute left-0 right-0 -bottom-[100px] bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg p-4 z-20 shadow-2xl flex flex-col gap-3 min-w-[300px]">
          <div className="flex justify-between items-center">
            <span className="text-sm font-semibold text-[var(--color-text-primary)]">
              Purchasing...
            </span>
            <span className="text-xs text-[var(--color-text-secondary)]">
              {purchaseProgress.current} / {purchaseProgress.total}
            </span>
          </div>

          <div className="w-full bg-[var(--color-surface-hover)] rounded-full h-2 overflow-hidden flex">
            <div
              className="bg-emerald-500 h-full transition-all duration-300"
              style={{
                width: `${(purchaseProgress.success / purchaseProgress.total) * 100}%`,
              }}
            />
            <div
              className="bg-red-500 h-full transition-all duration-300"
              style={{
                width: `${(purchaseProgress.failed / purchaseProgress.total) * 100}%`,
              }}
            />
          </div>

          <div className="flex justify-between text-xs mt-1">
            <div className="flex items-center gap-1.5 text-emerald-400 font-medium">
              <CheckCircle2 size={12} />
              {purchaseProgress.success} Bought
            </div>
            {purchaseProgress.failed > 0 && (
              <div className="flex items-center gap-1.5 text-red-400 font-medium">
                <AlertTriangle size={12} />
                {purchaseProgress.failed} Failed
              </div>
            )}
          </div>

          {purchaseProgress.failed > 0 && (
            <div className="text-[10px] text-[var(--color-text-muted)] bg-[var(--color-app-bg)] p-2 rounded truncate">
              Errors occurred. See console for details.
            </div>
          )}
        </div>
      )}

      {/* Confirm Dialog */}
      <PurchaseConfirmDialog
        isOpen={showConfirm}
        onClose={() => setShowConfirm(false)}
        onConfirm={handleConfirmPurchase}
        assetName={details.name || "Unknown Asset"}
        price={isBulkMode ? totalCost : displayPrice}
        userBalance={userBalance}
        accountCount={isBulkMode ? accountsNeedingPurchase.length : 1}
      />
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from "react";
import {
  ShieldAlert,
  RotateCcw,
  X,
  Loader2,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import { Account } from "@renderer/types";

interface AvatarResetGateProps {
  selectedAccounts: Account[];
  onResetDone: () => void;
  onCancel: () => void;
}

const BLACK_BODY_COLORS = {
  headColor3: "1b2a35",
  torsoColor3: "1b2a35",
  rightArmColor3: "1b2a35",
  leftArmColor3: "1b2a35",
  rightLegColor3: "1b2a35",
  leftLegColor3: "1b2a35",
};

// Key for localStorage
const getResetKey = (accountIds: string[]) =>
  `avatar-reset-done:${[...accountIds].sort().join(",")}`;

export function hasAvatarResetBeenDone(accountIds: string[]): boolean {
  if (accountIds.length === 0) return true;
  try {
    return localStorage.getItem(getResetKey(accountIds)) === "yes";
  } catch {
    return false;
  }
}

export function markAvatarResetDone(accountIds: string[]) {
  try {
    localStorage.setItem(getResetKey(accountIds), "yes");
  } catch {}
}

const HOLD_DURATION = 1500; // ms

export const AvatarResetGate: React.FC<AvatarResetGateProps> = ({
  selectedAccounts,
  onResetDone,
  onCancel,
}) => {
  const [holding, setHolding] = useState(false);
  const [holdProgress, setHoldProgress] = useState(0);
  const [isResetting, setIsResetting] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0 });
  const [results, setResults] = useState<
    Array<{ username: string; success: boolean }>
  >([]);
  const [done, setDone] = useState(false);

  const holdStartRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const holdActiveRef = useRef(false);

  const startHold = useCallback(() => {
    holdActiveRef.current = true;
    holdStartRef.current = Date.now();
    setHolding(true);

    const tick = () => {
      if (!holdActiveRef.current || holdStartRef.current === null) return;
      const elapsed = Date.now() - holdStartRef.current;
      const pct = Math.min(1, elapsed / HOLD_DURATION);
      setHoldProgress(pct);
      if (pct < 1) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        triggerReset();
      }
    };
    rafRef.current = requestAnimationFrame(tick);
  }, []);

  const endHold = useCallback(() => {
    if (holdProgress < 1) {
      holdActiveRef.current = false;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      setHolding(false);
      setHoldProgress(0);
      holdStartRef.current = null;
    }
  }, [holdProgress]);

  const triggerReset = async () => {
    holdActiveRef.current = false;
    setHolding(false);
    setIsResetting(true);
    setProgress({ current: 0, total: selectedAccounts.length });
    const ops: Array<{ username: string; success: boolean }> = [];

    for (const account of selectedAccounts) {
      if (!account.cookie) {
        ops.push({ username: account.username, success: false });
        setProgress((prev) => ({ ...prev, current: prev.current + 1 }));
        continue;
      }
      try {
        await window.api.setWearingAssets(account.cookie, []);
        await window.api.setBodyColors(account.cookie, BLACK_BODY_COLORS);
        ops.push({ username: account.username, success: true });
      } catch {
        ops.push({ username: account.username, success: false });
      }
      setProgress((prev) => ({ ...prev, current: prev.current + 1 }));
      await new Promise((r) => setTimeout(r, 500));
    }

    setIsResetting(false);
    setResults(ops);
    setDone(true);

    // Persist reset state
    markAvatarResetDone(selectedAccounts.map((a) => a.id));
  };

  const successCount = results.filter((r) => r.success).length;

  if (done) {
    return (
      <div className="flex h-full items-center justify-center p-8">
        <div className="max-w-md w-full rounded-2xl border border-emerald-500/30 bg-emerald-500/10 backdrop-blur-xl p-8 flex flex-col items-center text-center gap-4">
          <div className="w-16 h-16 rounded-full bg-emerald-500/20 flex items-center justify-center">
            <CheckCircle2 className="h-8 w-8 text-emerald-400" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-[var(--color-text-primary)] mb-1">
              Reset Complete
            </h2>
            <p className="text-sm text-[var(--color-text-secondary)]">
              {successCount}/{selectedAccounts.length} accounts reset
              successfully. The avatar editor is now unlocked.
            </p>
          </div>
          <button
            onClick={onResetDone}
            className="mt-2 rounded-xl bg-[var(--accent-color)] px-8 py-2.5 font-bold text-[var(--accent-color-foreground)] hover:opacity-90 transition-opacity shadow-[0_0_20px_var(--accent-color-faint)]"
          >
            Open Avatar Editor →
          </button>
        </div>
      </div>
    );
  }

  if (isResetting) {
    return (
      <div className="flex h-full items-center justify-center p-8">
        <div className="max-w-md w-full rounded-2xl border border-white/10 bg-black/60 backdrop-blur-xl p-8 flex flex-col items-center text-center gap-4">
          <Loader2 className="h-12 w-12 text-[var(--accent-color)] animate-spin" />
          <div>
            <h2 className="text-lg font-bold text-[var(--color-text-primary)] mb-1">
              Resetting Avatars...
            </h2>
            <p className="text-sm text-[var(--color-text-secondary)]">
              {progress.current} / {progress.total} accounts
            </p>
          </div>
          <div className="w-full h-2 rounded-full bg-white/10 overflow-hidden">
            <div
              className="h-full bg-[var(--accent-color)] transition-all duration-300"
              style={{
                width: `${(progress.current / Math.max(1, progress.total)) * 100}%`,
              }}
            />
          </div>
          <div className="w-full space-y-1 max-h-32 overflow-y-auto custom-scrollbar">
            {results.map((r, i) => (
              <div
                key={i}
                className={`flex items-center gap-2 rounded-lg px-3 py-1 text-xs ${r.success ? "text-emerald-400" : "text-red-400"}`}
              >
                {r.success ? (
                  <CheckCircle2 className="h-3 w-3 shrink-0" />
                ) : (
                  <XCircle className="h-3 w-3 shrink-0" />
                )}
                {r.username}
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-full items-center justify-center p-8">
      <div className="max-w-md w-full rounded-2xl border border-amber-500/30 bg-black/60 backdrop-blur-xl p-8 flex flex-col items-center text-center gap-5">
        {/* Icon */}
        <div className="w-16 h-16 rounded-full bg-amber-500/15 border border-amber-500/30 flex items-center justify-center">
          <ShieldAlert className="h-8 w-8 text-amber-400" />
        </div>

        {/* Text */}
        <div>
          <h2 className="text-xl font-bold text-[var(--color-text-primary)] mb-2">
            Reset Required
          </h2>
          <p className="text-sm text-[var(--color-text-secondary)] leading-relaxed">
            You have{" "}
            <span className="text-[var(--color-text-primary)] font-semibold">
              {selectedAccounts.length} accounts
            </span>{" "}
            selected. To use the bulk avatar editor, all selected accounts must
            first be reset to default (no accessories, black body color).
          </p>
        </div>

        {/* Accounts preview */}
        <div className="flex flex-wrap justify-center gap-1.5 max-w-xs">
          {selectedAccounts.slice(0, 8).map((a) => (
            <span
              key={a.id}
              className="rounded-full bg-white/10 px-2.5 py-0.5 text-[11px] font-medium text-[var(--color-text-secondary)]"
            >
              {a.username}
            </span>
          ))}
          {selectedAccounts.length > 8 && (
            <span className="rounded-full bg-white/10 px-2.5 py-0.5 text-[11px] text-[var(--color-text-muted)]">
              +{selectedAccounts.length - 8} more
            </span>
          )}
        </div>

        {/* Hold button */}
        <div className="flex flex-col items-center gap-2 w-full">
          <div className="relative w-full overflow-hidden rounded-xl">
            {/* Progress fill behind button */}
            <div
              className="absolute inset-0 bg-amber-500/30 transition-none"
              style={{ width: `${holdProgress * 100}%` }}
            />
            <button
              onMouseDown={startHold}
              onMouseUp={endHold}
              onMouseLeave={endHold}
              onTouchStart={startHold}
              onTouchEnd={endHold}
              className="relative w-full flex items-center justify-center gap-2 rounded-xl border border-amber-500/40 bg-amber-500/10 px-6 py-3 font-bold text-amber-300 select-none cursor-pointer hover:bg-amber-500/20 transition-colors"
            >
              <RotateCcw className="h-4 w-4" />
              {holding
                ? `Resetting... ${Math.round(holdProgress * 100)}%`
                : "Hold to Reset All Avatars"}
            </button>
          </div>
          <p className="text-[11px] text-[var(--color-text-muted)]">
            Hold the button for 1.5 seconds to confirm
          </p>
        </div>

        {/* Cancel */}
        <button
          onClick={onCancel}
          className="flex items-center gap-1.5 text-sm text-[var(--color-text-muted)] hover:text-[var(--color-text-secondary)] transition-colors"
        >
          <X className="h-4 w-4" />
          Cancel — go back
        </button>
      </div>
    </div>
  );
};

import { useState, useRef, useCallback, useEffect } from "react";
import { useNotification } from "@renderer/features/system/stores/useSnackbarStore";
import {
  useAddFavoriteItem,
  useRemoveFavoriteItem,
  useSetWearingAssets,
  useWearOutfit,
  useUpdateOutfit,
  useDeleteOutfit,
} from "@renderer/hooks/queries";
import { SUB_CATEGORY_IDS } from "../utils/categoryUtils";
import type { MainCategory } from "../utils/categoryUtils";
import type { Account } from "@renderer/types";

interface InventoryItem {
  id: number;
  name: string;
  type: string;
  imageUrl: string;
}

interface AvatarAsset {
  id: number;
  name: string;
  assetType: { id: number; name: string };
  currentVersionId?: number;
  meta?: { order?: number; puffiness?: number; version?: number };
}

interface UseAvatarActionsOptions {
  account: Account | null;
  accounts?: Account[];
  isBulkMode?: boolean;
  mainCategory: MainCategory;
  subCategory: string;
  inventoryItems: InventoryItem[];
  currentAvatarAssets: AvatarAsset[];
  equippedIds: Set<number>;
  favoriteIds: Set<number>;
  renderAvatar: (userId: string) => Promise<void>;
  refetchCurrentAvatar: () => Promise<any>;
}

export const useAvatarActions = ({
  account,
  accounts = [],
  isBulkMode = false,
  mainCategory,
  subCategory,
  inventoryItems,
  currentAvatarAssets,
  equippedIds,
  favoriteIds,
  renderAvatar,
  refetchCurrentAvatar,
}: UseAvatarActionsOptions) => {
  const { showNotification } = useNotification();
  const [isUpdatingAvatar, setIsUpdatingAvatar] = useState(false);
  const [loadingItemId, setLoadingItemId] = useState<number | null>(null);
  const favoriteBurstTimeouts = useRef<Map<number, number>>(new Map());
  const [favoriteBurstKeys, setFavoriteBurstKeys] = useState<
    Record<number, number>
  >({});

  const addFavoriteMutation = useAddFavoriteItem();
  const removeFavoriteMutation = useRemoveFavoriteItem();
  const setWearingAssetsMutation = useSetWearingAssets(account);
  const wearOutfitMutation = useWearOutfit(account);
  const updateOutfitMutation = useUpdateOutfit(account);
  const deleteOutfitMutation = useDeleteOutfit(account);

  const triggerFavoriteBurst = useCallback((id: number) => {
    setFavoriteBurstKeys((prev) => ({
      ...prev,
      [id]: (prev[id] ?? 0) + 1,
    }));

    const existingTimeout = favoriteBurstTimeouts.current.get(id);
    if (existingTimeout) {
      clearTimeout(existingTimeout);
    }

    const timeoutId = window.setTimeout(() => {
      setFavoriteBurstKeys((prev) => {
        const { [id]: _, ...rest } = prev;
        return rest;
      });
      favoriteBurstTimeouts.current.delete(id);
    }, 900);

    favoriteBurstTimeouts.current.set(id, timeoutId);
  }, []);

  useEffect(() => {
    const timeouts = favoriteBurstTimeouts.current;
    return () => {
      timeouts.forEach((timeoutId) => clearTimeout(timeoutId));
      timeouts.clear();
    };
  }, []);

  const handleFavorite = useCallback(
    async (id: number, name: string) => {
      const item = inventoryItems.find((i) => i.id === id);
      const type = item?.type || subCategory;
      const isFav = favoriteIds.has(id);

      try {
        if (isFav) {
          await removeFavoriteMutation.mutateAsync(id);
          showNotification("Removed from favorites", "info");
        } else {
          await addFavoriteMutation.mutateAsync({ id, name, type });
          triggerFavoriteBurst(id);
          showNotification("Added to favorites", "success");
        }
      } catch (error) {
        console.error("Failed to update favorites:", error);
        showNotification("Failed to update favorites", "error");
      }
    },
    [
      inventoryItems,
      subCategory,
      favoriteIds,
      addFavoriteMutation,
      removeFavoriteMutation,
      triggerFavoriteBurst,
      showNotification,
    ],
  );

  const toggleEquip = useCallback(
    async (itemId: number) => {
      const targetAccounts = isBulkMode ? accounts : account ? [account] : [];
      if (targetAccounts.length === 0 || isUpdatingAvatar) return;

      const isRemoving = equippedIds.has(itemId);

      if (isBulkMode && !isRemoving) {
        const wantsToEquip = window.confirm(
          `Do you want to equip this item for all ${targetAccounts.length} selected accounts? (It will be purchased if they don't own it and it's free)`,
        );
        if (!wantsToEquip) return;
      }

      if (mainCategory === "Characters") {
        setIsUpdatingAvatar(true);
        setLoadingItemId(itemId);
        try {
          // Wear outfit sequentially
          for (const target of targetAccounts) {
            if (target.cookie) {
              await window.api.wearOutfit(target.cookie, itemId);
              if (target.userId) await renderAvatar(target.userId);
            }
          }
          showNotification(
            `Outfit ${isRemoving ? "removed" : "worn"} successfully`,
            "success",
          );
          await refetchCurrentAvatar();
        } catch (error) {
          console.error("Error wearing outfit:", error);
          showNotification("Error wearing outfit", "error");
        } finally {
          setIsUpdatingAvatar(false);
          setLoadingItemId(null);
        }
        return;
      }

      setIsUpdatingAvatar(true);
      setLoadingItemId(itemId);

      try {
        const item = inventoryItems.find((i) => i.id === itemId);
        const itemName = item?.name || "Unknown Item";

        let assetTypeId = SUB_CATEGORY_IDS[subCategory];
        let assetTypeName = subCategory;

        if (
          !isRemoving &&
          (mainCategory === "Favorites" || mainCategory === "Currently Wearing")
        ) {
          const typeName = item?.type || "";
          const foundTypeId = Object.entries(SUB_CATEGORY_IDS).find(
            ([name]) => name.toLowerCase() === typeName.toLowerCase(),
          );
          if (foundTypeId) {
            assetTypeId = foundTypeId[1];
            assetTypeName = foundTypeId[0];
          } else {
            try {
              const firstTarget = targetAccounts[0];
              const details = await (window as any).api.getAssetDetails(
                firstTarget.cookie,
                itemId,
              );
              assetTypeId = details.AssetTypeId || details.assetType || 8;
              assetTypeName = typeName || "Hat";
            } catch (e) {
              console.warn(
                "Could not fetch asset details, using default type",
                e,
              );
              assetTypeId = 8;
            }
          }
        }

        const newAsset: AvatarAsset = {
          id: itemId,
          name: itemName,
          assetType: {
            id: assetTypeId,
            name: assetTypeName,
          },
        };

        // Apply changes to all target accounts sequentially with a 3s delay
        for (let i = 0; i < targetAccounts.length; i++) {
          const targetAcc = targetAccounts[i];
          if (!targetAcc.cookie || !targetAcc.userId) continue;

          try {
            // First get their current avatar
            const avatarData = await window.api.getCurrentAvatar(
              targetAcc.cookie,
              parseInt(targetAcc.userId),
            );

            let newAssets: any[];
            if (isRemoving) {
              newAssets = avatarData.assets.filter((a: any) => a.id !== itemId);
            } else {
              newAssets = [...avatarData.assets, newAsset];
            }

            await window.api.setWearingAssets(targetAcc.cookie, newAssets);
            await renderAvatar(targetAcc.userId);
          } catch (e) {
            console.error(
              `Failed to update avatar for ${targetAcc.username}`,
              e,
            );
          }

          // 3 second delay between accounts (skip after the last one)
          if (i < targetAccounts.length - 1) {
            await new Promise((resolve) => setTimeout(resolve, 3000));
          }
        }

        await refetchCurrentAvatar();
      } catch (error) {
        console.error("Error setting wearing assets:", error);
        await refetchCurrentAvatar();
      } finally {
        setIsUpdatingAvatar(false);
        setLoadingItemId(null);
      }
    },
    [
      account,
      accounts,
      isBulkMode,
      mainCategory,
      subCategory,
      inventoryItems,
      currentAvatarAssets,
      equippedIds,
      isUpdatingAvatar,
      setWearingAssetsMutation,
      wearOutfitMutation,
      renderAvatar,
      refetchCurrentAvatar,
      showNotification,
    ],
  );

  const handleRename = useCallback(
    async (outfitId: number, newName: string) => {
      if (!account?.cookie) return;

      try {
        const result = await updateOutfitMutation.mutateAsync({
          outfitId,
          details: { name: newName },
        });
        if (result.success) {
          showNotification("Outfit renamed successfully", "success");
        } else {
          showNotification("Failed to rename outfit", "error");
        }
      } catch (error) {
        console.error("Failed to rename outfit:", error);
        showNotification("Error renaming outfit", "error");
      }
    },
    [account, updateOutfitMutation, showNotification],
  );

  const handleUpdateWithWorn = useCallback(
    async (outfitId: number, name: string) => {
      if (!account?.cookie) return;

      try {
        const avatarData = await window.api.getCurrentAvatar(account.cookie);
        const payload = {
          name: name,
          bodyColors: avatarData.bodyColors,
          assets: avatarData.assets,
          scale: avatarData.scales,
          playerAvatarType: avatarData.playerAvatarType,
        };

        const result = await updateOutfitMutation.mutateAsync({
          outfitId,
          details: payload,
        });
        if (result.success) {
          showNotification("Outfit updated with current avatar", "success");
        } else {
          showNotification("Failed to update outfit", "error");
        }
      } catch (error) {
        console.error("Failed to update outfit:", error);
        showNotification("Error updating outfit", "error");
      }
    },
    [account, updateOutfitMutation, showNotification],
  );

  const handleDeleteOutfit = useCallback(
    async (outfitId: number) => {
      if (!account?.cookie) return;

      try {
        const result = await deleteOutfitMutation.mutateAsync(outfitId);
        if (result.success) {
          showNotification("Outfit deleted successfully", "success");
        } else {
          showNotification("Failed to delete outfit", "error");
        }
      } catch (error) {
        console.error("Failed to delete outfit:", error);
        showNotification("Error deleting outfit", "error");
      }
    },
    [account, deleteOutfitMutation, showNotification],
  );

  return {
    isUpdatingAvatar,
    loadingItemId,
    favoriteBurstKeys,
    handleFavorite,
    toggleEquip,
    handleRename,
    handleUpdateWithWorn,
    handleDeleteOutfit,
  };
};

import { useQuery } from "@tanstack/react-query";
import { queryKeys } from "@shared/queryKeys";
import { Account } from "@renderer/types";

const ASSET_TYPE_MAP: Record<number, string> = {
  2: "TShirt",
  8: "Hat",
  11: "Shirt",
  12: "Pants",
  17: "Head",
  18: "Face",
  19: "Gear",
  41: "HairAccessory",
  42: "FaceAccessory",
  43: "NeckAccessory",
  44: "ShoulderAccessory",
  45: "FrontAccessory",
  46: "BackAccessory",
  47: "WaistAccessory",
  61: "EmoteAnimation",
  64: "TShirtAccessory",
  65: "ShirtAccessory",
  66: "PantsAccessory",
  67: "JacketAccessory",
  68: "SweaterAccessory",
  69: "ShortsAccessory",
  72: "DressSkirtAccessory",
};

const mapAssetTypeIds = (ids: number[]): string[] => {
  return ids.map((id) => ASSET_TYPE_MAP[id]).filter(Boolean);
};

export interface BulkInventoryItem {
  id: number;
  name: string;
  type: string;
  imageUrl: string;
  ownershipCount: number;
}

export function useBulkInventory(
  accounts: Account[],
  assetTypeIds: number[],
  options?: { enabled?: boolean },
) {
  const accountIds = accounts
    .map((a) => a.id)
    .sort()
    .join(",");
  const primaryAssetTypeId = assetTypeIds[0] || 0;

  return useQuery({
    queryKey: ["avatar", "bulk-inventory", accountIds, primaryAssetTypeId],
    queryFn: async (): Promise<BulkInventoryItem[]> => {
      const validAccounts = accounts.filter((a) => a.cookie && a.userId);
      if (validAccounts.length === 0) return [];

      const assetTypes = mapAssetTypeIds(assetTypeIds);
      if (assetTypes.length === 0) return [];

      const itemCounts = new Map<number, { count: number; item: any }>();

      for (const acc of validAccounts) {
        try {
          const userId = parseInt(acc.userId!);
          const result = await window.api.getInventoryV2(
            acc.cookie!,
            userId,
            assetTypes,
            undefined, // cursor
            100, // limit
            "Desc", // sortOrder
          );

          if (result?.data) {
            result.data.forEach((asset: any) => {
              const id = asset.assetId;
              const current = itemCounts.get(id);
              if (current) {
                current.count++;
              } else {
                itemCounts.set(id, { count: 1, item: asset });
              }
            });
          }
          // Small delay to prevent rate limits
          await new Promise((r) => setTimeout(r, 250));
        } catch (error) {
          console.error(`Failed to fetch inventory for ${acc.username}`, error);
        }
      }

      if (itemCounts.size === 0) return [];

      const uniqueAssetIds = Array.from(itemCounts.keys());
      let thumbMap = new Map<number, string>();

      try {
        const thumbResponse =
          await window.api.getBatchThumbnails(uniqueAssetIds);
        thumbMap = new Map(
          thumbResponse.data.map((t: any) => [t.targetId, t.imageUrl]),
        );
      } catch (error) {
        console.error("[useBulkInventory] Failed to fetch thumbnails:", error);
      }

      const results: BulkInventoryItem[] = [];
      itemCounts.forEach(({ count, item }) => {
        results.push({
          id: item.assetId,
          name: item.name || item.assetName || item.Name || "Unknown Item",
          type: item.assetType?.name || "Unknown",
          imageUrl: (thumbMap.get(item.assetId) as string) || "",
          ownershipCount: count,
        });
      });

      return results.sort((a, b) => b.ownershipCount - a.ownershipCount);
    },
    enabled:
      accounts.length >= 2 &&
      assetTypeIds.length > 0 &&
      (options?.enabled ?? true),
    staleTime: 60 * 1000, // 1 minute
  });
}

