                  <SkeletonGameGrid count={15} gridStyle={gridStyle} />
                ) : games.length === 0 ? (
                  <motion.div
                    key="empty"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="flex items-center justify-center py-20"
                  >
                    <EmptyState
                      icon={Gamepad2}
                      title="No games found"
