                        onGameSelect={onGameSelect}
                        onContextMenu={(e, currentGame) => {
                          e.preventDefault();
                          setActiveContextMenu({
                            id: currentGame.id,
                            placeId: currentGame.placeId,
                            universeId: currentGame.universeId,
                            isFavorite: Boolean(
                              currentGame.placeId &&
                              favorites.includes(currentGame.placeId),
