                        }}
                        formatPlayerCount={formatPlayerCount}
                        isFavorite={Boolean(
                          game.placeId && favorites.includes(game.placeId),
                        )}
                        favoriteBurst={Boolean(
                          game.placeId && favoriteGameBurstKeys[game.placeId],
