        onJoinGame={(placeId, jobId, userId) => {
          if (!placeId) return;
          const placeTarget =
            typeof placeId === "number" ? placeId.toString() : placeId;

          if (jobId) {
            onLaunch({
              method: JoinMethod.JobId,
              target: `${placeTarget}:${jobId}`,
            });
            return;
          }

          if (userId) {
            onLaunch({
              method: JoinMethod.Friend,
              target: `${userId}:${placeTarget}`,
            });
