    </>
  );
};

// Game Pass Card Component
const GamePassCard: React.FC<{
  pass: GamePass;
  account?: Account | null;
  showNotification: (
    message: string,
    type: "success" | "error" | "warning" | "info",
  ) => void;
}> = ({ pass, account, showNotification }) => {
  const [imageUrl, setImageUrl] = useState<string>("");
  const [isPurchasing, setIsPurchasing] = useState(false);
  const [isOwned, setIsOwned] = useState(pass.isOwned);
  const [showConfirm, setShowConfirm] = useState(false);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{
    name: string;
    creator: string;
    price: number | string;
    thumbnailUrl: string;
  } | null>(null);
  const [purchaseError, setPurchaseError] = useState<string | null>(null);

  useEffect(() => {
    if (pass.displayIconImageAssetId) {
      fetch(
        `https://thumbnails.roblox.com/v1/assets?assetIds=${pass.displayIconImageAssetId}&size=150x150&format=Png&isCircular=false`,
      )
        .then((res) => res.json())
        .then((data) => {
          if (data.data && data.data.length > 0 && data.data[0].imageUrl) {
            setImageUrl(data.data[0].imageUrl);
          }
        })
        .catch(() => {
          console.error("Failed to load game pass thumbnail");
        });
    }
  }, [pass.displayIconImageAssetId]);

  const handleOpenConfirm = () => {
    if (isOwned) return;
    if (pass.productId === null) {
      showNotification(
        "This game pass is unavailable for purchase right now",
        "warning",
      );
      return;
    }
    if (pass.price === null) {
      showNotification("This game pass is not currently for sale", "warning");
      return;
    }
    if (!account?.cookie) {
      showNotification(
        "Select an account with a valid cookie to purchase",
        "error",
      );
      return;
    }
    setPurchaseError(null);
    setShowConfirm(true);
  };

  const handleConfirmPurchase = async () => {
    if (!account?.cookie || pass.price === null || pass.productId === null)
      return;

    setIsPurchasing(true);
    setPurchaseError(null);

    const sellerId = pass.creator?.creatorId;
    if (!sellerId) {
      const message = "Unable to determine seller for this game pass";
      setPurchaseError(message);
      showNotification(message, "error");
      setIsPurchasing(false);
      setShowConfirm(false);
      return;
    }
    const idempotencyKey =
      typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
        ? crypto.randomUUID()
        : undefined;

    try {
      const result = await window.api.purchaseGamePass(
        account.cookie,
        pass.productId,
        pass.price,
        sellerId,
        account.userId,
        idempotencyKey,
      );

      if (result?.purchased) {
        setIsOwned(true);
        setPurchaseSuccess({
          name: pass.displayName || pass.name,
          creator: pass.creator?.name || "Unknown Creator",
          price: pass.price,
          thumbnailUrl: imageUrl,
        });
        showNotification("Game pass purchased successfully", "success");
      } else {
        const message =
          result?.reason ||
          result?.errorMessage ||
          result?.shortMessage ||
          result?.purchaseResult ||
          "Failed to purchase game pass";
        setPurchaseError(message);
        showNotification(message, "error");
      }
    } catch (error: any) {
      const message = error?.message || "Failed to purchase game pass";
      setPurchaseError(message);
      showNotification(message, "error");
    } finally {
      setIsPurchasing(false);
      setShowConfirm(false);
    }
  };

  return (
    <div className="bg-[var(--color-surface)]/50 border border-[var(--color-border)]/50 rounded-lg p-3 flex gap-3 hover:bg-[var(--color-surface)] transition-colors">
      <div className="w-16 h-16 rounded-lg bg-[var(--color-surface-hover)] overflow-hidden flex-shrink-0">
        {imageUrl ? (
          <img
            src={imageUrl}
            alt={pass.displayName}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <ShoppingBag size={24} className="text-[var(--color-text-muted)]" />
          </div>
        )}
      </div>

      <div className="flex-1 min-w-0 flex flex-col justify-center">
        <h4 className="text-sm font-semibold text-[var(--color-text-primary)] truncate">
          {pass.displayName}
        </h4>
        {pass.displayDescription && (
          <p className="text-xs text-[var(--color-text-secondary)] line-clamp-2 mt-0.5">
            {pass.displayDescription}
          </p>
        )}
      </div>

      <div className="flex flex-col items-end justify-center gap-1 flex-shrink-0">
        {isOwned ? (
          <div className="flex items-center gap-1 px-3 py-1.5 bg-emerald-500/20 border border-emerald-500/30 rounded-lg text-emerald-400">
            <Check size={14} />
            <span className="text-xs font-medium">Owned</span>
          </div>
        ) : pass.price !== null ? (
          <button
            onClick={handleOpenConfirm}
            disabled={isPurchasing}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-[rgba(var(--accent-color-rgb),0.15)] hover:bg-[rgba(var(--accent-color-rgb),0.25)] border border-[var(--accent-color-border)] rounded-lg text-[var(--accent-color)] transition-colors disabled:opacity-50"
          >
            <RobuxIcon className="w-4 h-4" />
            <span className="text-sm font-semibold">
              {pass.price.toLocaleString()}
            </span>
          </button>
        ) : (
          <span className="text-xs text-[var(--color-text-muted)]">
            Not for sale
          </span>
        )}
      </div>

      <Dialog
        isOpen={showConfirm}
        onClose={() => !isPurchasing && setShowConfirm(false)}
      >
        <DialogContent className="max-w-sm">
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-lg overflow-hidden bg-[var(--color-surface)] border border-[var(--color-border)] flex items-center justify-center">
                {imageUrl ? (
                  <img
                    src={imageUrl}
                    alt={pass.displayName}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <ShoppingBag
                    size={24}
                    className="text-[var(--color-text-muted)]"
                  />
                )}
              </div>
              <div>
                <p className="text-sm text-[var(--color-text-secondary)]">
                  Confirm Purchase
                </p>
                <p className="text-base font-semibold text-[var(--color-text-primary)] truncate">
                  {pass.displayName}
                </p>
              </div>
            </div>

            <div className="text-sm text-[var(--color-text-secondary)]">
              Buy this game pass for{" "}
              <span className="inline-flex items-center gap-1 font-semibold text-emerald-400">
                {pass.price?.toLocaleString()}
                <RobuxIcon className="w-4 h-4" />
              </span>
              ?
            </div>

            <div className="flex gap-3 pt-2">
              <Button
                variant="outline"
                className="flex-1"
                disabled={isPurchasing}
                onClick={() => setShowConfirm(false)}
              >
                Cancel
              </Button>
              <Button
                className="flex-1"
                disabled={isPurchasing}
                onClick={handleConfirmPurchase}
              >
                {isPurchasing && (
                  <Loader2 className="w-4 h-4 animate-spin mr-2" />
                )}
                {isPurchasing ? "Purchasing..." : "Confirm"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {purchaseSuccess && (
        <PurchaseSuccessDialog
          isOpen={!!purchaseSuccess}
          onClose={() => setPurchaseSuccess(null)}
          assetName={purchaseSuccess.name}
          creatorName={purchaseSuccess.creator}
          price={purchaseSuccess.price}
          thumbnailUrl={purchaseSuccess.thumbnailUrl}
        />
      )}

      <PurchaseErrorDialog
        isOpen={!!purchaseError}
        onClose={() => setPurchaseError(null)}
        errorMessage={purchaseError || ""}
      />
    </div>
  );
};

export default GameDetailsModal;

import React, { useState, useEffect, useRef } from "react";
import { Button } from "@renderer/components/UI/buttons/Button";
import {
  Wand2,
  Trash2,
  Settings,
  Clipboard,
  Key,
  Zap,
  Check,
  UserPlus,
  X,
} from "lucide-react";
import { useAccountsManager } from "../auth/api/useAccounts";
import { AccountStatus } from "@renderer/types";
import { v4 as uuidv4 } from "uuid";
import { motion, AnimatePresence } from "framer-motion";
import { GeneratorSettingsModal } from "./GeneratorSettingsModal";

interface GeneratedAccountData {
  id: string;
  username: string;
  password: string;
  email?: string;
  birthDate?: string;
  createdAt: number;
}

interface GeneratorConfig {
  usernamePrefix: string;
  passwordLength: number;
  includeSpecialChars: boolean;
  selectedClient?: string;
  multiGenerateCount: number;
  autoSwapBrowser: boolean;
}

const CLIENT_NAMES = [
  "Chrome Desktop",
  "Firefox Desktop",
  "Safari macOS",
  "Edge Windows",
  "Opera",
  "Brave",
  "Vivaldi",
  "Google Bot",
  "Custom",
];

export const GeneratorTab = () => {
  const [config, setConfig] = useState<GeneratorConfig>({
    usernamePrefix: "sentra_",
    passwordLength: 16,
    includeSpecialChars: true,
    selectedClient: "Chrome Desktop",
    multiGenerateCount: 1,
    autoSwapBrowser: false,
  });

  const [createdAccounts, setCreatedAccounts] = useState<
    GeneratedAccountData[]
  >([]);
  const [isCreating, setIsCreating] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [isAddingToAccounts, setIsAddingToAccounts] = useState<string | null>(
    null,
  );
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [generationProgress, setGenerationProgress] = useState<{
    current: number;
    total: number;
  } | null>(null);
  const cancelGenerationRef = useRef(false);
  const [isCancelling, setIsCancelling] = useState(false);
  const [customInputActive, setCustomInputActive] = useState(false);

  const { addAccount } = useAccountsManager();

  useEffect(() => {
    loadConfig();
    loadAccounts();
  }, []);

  const loadConfig = async () => {
    try {
      const result = await window.api.generator.getConfig();
      if (result.success) setConfig(result.config);
    } catch (err) {
      console.error("Failed to load config:", err);
    }
  };

  const loadAccounts = async () => {
    try {
      const response = await window.api.generator.getAccounts();
      setCreatedAccounts((response?.accounts || []) as GeneratedAccountData[]);
    } catch (err) {
      console.error("Failed to load generator accounts:", err);
      setCreatedAccounts([]);
    }
  };

  const handleCancelGeneration = () => {
    cancelGenerationRef.current = true;
    setIsCancelling(true);
  };

  const handleCreateAccount = async () => {
    cancelGenerationRef.current = false;
    setIsCancelling(false);
    setIsCreating(true);
    const countToGenerate = config.multiGenerateCount;
    const originalClient = config.selectedClient;
    setGenerationProgress({ current: 0, total: countToGenerate });
    try {
      let clientIndex = CLIENT_NAMES.indexOf(
        originalClient || "Chrome Desktop",
      );
      for (let i = 0; i < countToGenerate; i++) {
        if (cancelGenerationRef.current) break;

        if (config.autoSwapBrowser && i > 0) {
          clientIndex = (clientIndex + 1) % CLIENT_NAMES.length;
          setConfig((prev) => ({
            ...prev,
            selectedClient: CLIENT_NAMES[clientIndex],
          }));
        }
        try {
          // Race the createAccount call against a cancellation signal so
          // Cancel feels instant even mid-request
          const cancelPromise = new Promise<never>((_, reject) => {
            const interval = setInterval(() => {
              if (cancelGenerationRef.current) {
                clearInterval(interval);
                reject(new Error("cancelled"));
              }
            }, 100);
          });
          const result = await Promise.race([
            window.api.generator.createAccount(),
            cancelPromise,
          ]);
          if (result.success && result.accountId) {
            // Refresh list to get the newly created account
            await loadAccounts();
            // Auto-add to main accounts list in progress
            const freshAccounts = await window.api.generator.getAccounts();
            const newAcc = (freshAccounts?.accounts || []).find(
              (a: GeneratedAccountData) => a.id === result.accountId,
            );
            if (newAcc) await handleAddToAccounts(newAcc);
            await new Promise((resolve) => setTimeout(resolve, 300));
          }
        } catch (err: any) {
          if (err?.message === "cancelled" || cancelGenerationRef.current)
            break;
          console.error(`Failed to create account ${i + 1}:`, err);
        }
        if (cancelGenerationRef.current) break;
        setGenerationProgress({ current: i + 1, total: countToGenerate });
      }

      setConfig((prev) => ({ ...prev, selectedClient: originalClient }));
      await loadAccounts();
    } catch (err) {
      console.error("Failed to create accounts:", err);
    } finally {
      setIsCreating(false);
      setIsCancelling(false);
      setGenerationProgress(null);
      cancelGenerationRef.current = false;
    }
  };

  const handleAddToAccounts = async (account: GeneratedAccountData) => {
    setIsAddingToAccounts(account.id);
    try {
      const cookieResult = await window.api.generator.getCookie(account.id);
      const cookie = cookieResult.success ? cookieResult.cookie : "";
      let userId = "";
      let displayName = account.username;
      let avatarUrl = "";

      try {
        const userResult = await window.api.user.getUserByUsername(
          account.username,
        );
        if (userResult) {
          userId = String(userResult.id || "");
          displayName = userResult.displayName || account.username;
        }
      } catch (err) {}

      try {
        const avatarResult = await window.api.user.getAvatarUrlByUsername(
          account.username,
        );
        avatarUrl = avatarResult?.url || "";
      } catch (err) {}

      addAccount({
        id: uuidv4(),
        username: account.username,
        displayName: displayName,
        userId: userId,
        cookie: cookie || undefined,
        status: AccountStatus.Offline,
        avatarUrl: avatarUrl,
        lastActive: new Date().toISOString(),
        robuxBalance: 0,
        friendCount: 0,
        followerCount: 0,
        followingCount: 0,
        notes: "",
      });
    } catch (err) {
      console.error("Failed to add account:", err);
    } finally {
      setIsAddingToAccounts(null);
    }
  };

  const handleUpdateConfig = async () => {
    setIsSavingConfig(true);
    try {
      await window.api.generator.updateConfig(config);
      setShowSettings(false);
    } catch (err) {
      console.error("Failed to update config:", err);
    } finally {
      setIsSavingConfig(false);
    }
  };

  const handleClearAccounts = async () => {
    if (
      confirm(
        "Are you sure you want to clear all generated accounts from your inventory?",
      )
    ) {
      try {
        await window.api.generator.clearAccounts();
        setCreatedAccounts([]);
      } catch (err) {}
    }
  };

  const triggerCopyFeedback = (id: string) => {
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 1500);
  };

  const handleBulkCopy = async () => {
    try {
      const bulkData: string[] = [];
      for (const account of createdAccounts) {
        try {
          const passwordResult = await window.api.generator.getPassword(
            account.id,
          );
          const cookieResult = await window.api.generator.getCookie(account.id);
          bulkData.push(
            `${account.username}:${passwordResult?.password || ""}:${cookieResult?.cookie || ""}`,
          );
        } catch (err) {
          bulkData.push(`${account.username}::`);
        }
      }
      await navigator.clipboard.writeText(bulkData.join("\n"));
      triggerCopyFeedback("bulk");
    } catch (err) {}
  };

  const presets = [1, 5, 10, 25];
  const isPresetSelected =
    presets.includes(config.multiGenerateCount) && !customInputActive;

  return (
    <div className="h-full flex flex-col p-6 overflow-y-auto space-y-6 bg-[var(--color-background)]">
      {/* Mini Top Row Bar Header */}
      <div className="flex items-center justify-between border-b border-[var(--color-border)] pb-4 max-w-4xl mx-auto w-full">
        <div className="flex items-center gap-2.5">
          <Wand2 className="w-4 h-4 text-[var(--accent-color)]" />
          <h1 className="text-md font-bold tracking-tight text-[var(--color-text-primary)]">
            Account Generator
          </h1>
        </div>
      </div>

      {/* Futuristic Consolidated Console Control Dock */}
      <motion.div
        initial={{ opacity: 0, y: 5 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-4xl mx-auto flex items-center justify-between bg-[var(--color-surface)] border border-[var(--color-border)] p-2.5 rounded-xl shadow-sm gap-4"
      >
        {/* Count Segment Picker Unit */}
        <div className="flex items-center gap-1.5 bg-[var(--color-surface-strong)]/60 p-1 rounded-lg border border-[var(--color-border)]/60">
          <span className="text-[10px] font-bold text-[var(--color-text-muted)] uppercase tracking-wider px-2">
            Batch
          </span>
          <div className="flex items-center gap-1">
            {presets.map((num) => (
              <button
                key={num}
                onClick={() => {
                  setCustomInputActive(false);
                  setConfig((prev) => ({ ...prev, multiGenerateCount: num }));
                }}
                className={`px-3 h-7 rounded-md text-xs font-mono font-bold transition-all ${
                  config.multiGenerateCount === num && !customInputActive
                    ? "bg-[var(--accent-color)] text-[var(--color-text-primary)] shadow-sm"
                    : "text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-surface-hover)]"
                }`}
              >
                {num}
              </button>
            ))}

            {/* Inline Custom Input Selector Toggler */}
            <div
              className={`flex items-center h-7 px-1.5 rounded-md transition-all ${
                customInputActive || !isPresetSelected
                  ? "bg-[var(--color-background)] border border-[var(--accent-color)]/30"
                  : "hover:bg-[var(--color-surface-hover)]"
              }`}
            >
              <input
                type="number"
                min="1"
                max="100"
                placeholder="Custom"
                value={
                  customInputActive || !isPresetSelected
                    ? config.multiGenerateCount
                    : ""
                }
                onFocus={() => setCustomInputActive(true)}
                onChange={(e) => {
                  const val = parseInt(e.target.value) || 1;
                  setConfig((prev) => ({
                    ...prev,
                    multiGenerateCount: Math.min(100, Math.max(1, val)),
                  }));
                }}
                className="w-14 text-center bg-transparent border-0 text-xs font-mono font-bold focus:outline-none text-[var(--color-text-primary)] placeholder-[var(--color-text-muted)]/60 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              />
            </div>
          </div>
        </div>

        {/* Console Action Segment */}
        <div className="flex items-center gap-2">
          {isCreating ? (
            <>
              {/* Progress indicator */}
              {generationProgress && (
                <span className="text-[10px] font-mono text-[var(--color-text-muted)] tabular-nums">
                  {generationProgress.current}/{generationProgress.total}
                </span>
              )}
              <div className="w-3 h-3 rounded-full border-2 border-[var(--accent-color)]/20 border-t-[var(--accent-color)] animate-spin" />
              <Button
                onClick={handleCancelGeneration}
                disabled={isCancelling}
                className={`h-10 px-5 rounded-lg font-medium text-xs transition-all shadow-sm border-0 flex items-center gap-2 text-[var(--color-text-primary)] ${
                  isCancelling
                    ? "bg-red-800 opacity-60 cursor-not-allowed"
                    : "bg-red-600 hover:bg-red-500"
                }`}
              >
                <X className="w-3.5 h-3.5" />
                <span>{isCancelling ? "Cancelling..." : "Cancel"}</span>
              </Button>
            </>
          ) : (
            <Button
              onClick={handleCreateAccount}
              className="h-10 px-5 rounded-lg bg-[var(--accent-color)] hover:bg-[var(--accent-color)] text-[var(--color-text-primary)] font-medium text-xs transition-all shadow-sm border-0 flex items-center gap-2"
            >
              <Zap className="w-3.5 h-3.5 fill-white/10" />
              <span>Generate ({config.multiGenerateCount})</span>
            </Button>
          )}

          <Button
            onClick={() => setShowSettings(true)}
            disabled={isCreating}
            variant="outline"
            className="h-10 w-10 p-0 rounded-lg border-[var(--color-border)] bg-[var(--color-surface-strong)]/40 hover:bg-[var(--color-surface-hover)] transition-all disabled:opacity-50"
            title="Open Advanced Customization Panel"
          >
            <Settings className="w-3.5 h-3.5 text-[var(--color-text-muted)]" />
          </Button>
        </div>
      </motion.div>

      {/* Generated Accounts Space Log */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className="w-full max-w-4xl mx-auto flex-1 flex flex-col"
      >
        <div className="bg-[var(--color-surface)]/30 border border-[var(--color-border)] rounded-xl overflow-hidden flex flex-col h-full min-h-[420px]">
          {/* Header Panel */}
          <div className="p-4 border-b border-[var(--color-border)] flex items-center justify-between bg-[var(--color-surface-strong)]/20">
            <h2 className="text-xs font-bold flex items-center gap-2 text-[var(--color-text-primary)] uppercase tracking-wider">
              Generated accounts
              <span className="bg-[var(--accent-color)]/10 text-[var(--accent-color)] text-[10px] px-2 py-0.5 rounded font-mono font-bold">
                {createdAccounts.length} Units
              </span>
            </h2>
            {createdAccounts.length > 0 && (
              <div className="flex gap-2">
                <Button
                  onClick={handleBulkCopy}
                  size="sm"
                  variant="outline"
                  className="h-7 border-[var(--accent-color)]/20 text-[var(--accent-color)] text-[11px] hover:bg-[var(--accent-color)]/5"
                >
                  {copiedId === "bulk" ? (
                    <Check className="w-3 h-3 mr-1 text-emerald-500" />
                  ) : (
                    <Clipboard className="w-3 h-3 mr-1" />
                  )}
                  Bulk Export Full Log
                </Button>
                <Button
                  onClick={handleClearAccounts}
                  size="sm"
                  variant="ghost"
                  className="h-7 text-red-500 text-[11px] hover:bg-red-500/5"
                >
                  Flush Table
                </Button>
              </div>
            )}
          </div>

          {/* Output Card Matrix */}
          <div className="p-4 flex-1 overflow-y-auto">
            {createdAccounts.length === 0 ? (
              <div className="h-full min-h-[300px] flex flex-col items-center justify-center text-[var(--color-text-muted)] space-y-2">
                <Wand2 className="w-6 h-6 opacity-20" />
                <p className="text-xs font-medium">
                  No accounts generated in memory output.
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2.5">
                <AnimatePresence>
                  {createdAccounts.map((account) => (
                    <motion.div
                      initial={{ opacity: 0, y: 5 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.99 }}
                      key={account.id}
                      className="border border-[var(--accent-color)]/20 bg-[var(--accent-color)]/5 rounded-lg p-3 hover:border-[var(--accent-color)]/40 transition-colors flex flex-col gap-2.5 shadow-sm"
                    >
                      <div className="flex justify-between items-start">
                        <div className="truncate max-w-[75%]">
                          <div className="font-mono text-xs font-bold text-[var(--color-text-primary)] truncate">
                            {account.username}
                          </div>
                          <div className="text-[9px] font-mono text-[var(--color-text-muted)] mt-0.5">
                            {new Date(account.createdAt).toLocaleTimeString()}
                          </div>
                        </div>

                        <div className="flex bg-[var(--color-background)] border border-[var(--color-border)] rounded p-0.5 gap-0.5">
                          <button
                            onClick={async () => {
                              try {
                                const pr =
                                  await window.api.generator.getPassword(
                                    account.id,
                                  );
                                const cr = await window.api.generator.getCookie(
                                  account.id,
                                );
                                await navigator.clipboard.writeText(
                                  `${account.username}:${pr?.password || ""}:${cr?.cookie || ""}`,
                                );
                                triggerCopyFeedback(account.id + "-all");
                              } catch (err) {}
                            }}
                            className="p-1 text-[var(--color-text-muted)] hover:text-[var(--accent-color)] rounded transition-colors"
                          >
                            {copiedId === account.id + "-all" ? (
                              <Check className="w-3 h-3 text-emerald-500" />
                            ) : (
                              <Clipboard className="w-3 h-3" />
                            )}
                          </button>
                          <button
                            onClick={async () => {
                              try {
                                const result =
                                  await window.api.generator.getPassword(
                                    account.id,
                                  );
                                if (result?.success) {
                                  await navigator.clipboard.writeText(
                                    result.password,
                                  );
                                  triggerCopyFeedback(account.id + "-pass");
                                }
                              } catch (err) {}
                            }}
                            className="p-1 text-[var(--color-text-muted)] hover:text-[var(--accent-color)] rounded transition-colors"
                          >
                            {copiedId === account.id + "-pass" ? (
                              <Check className="w-3 h-3 text-emerald-500" />
                            ) : (
                              <Key className="w-3 h-3" />
                            )}
                          </button>
                        </div>
                      </div>

                      <div className="flex justify-between items-center pt-2 border-t border-[var(--color-border)]/40">
                        {account.birthDate ? (
                          <span className="text-[9px] font-mono bg-[var(--color-background)] text-[var(--color-text-muted)] px-1.5 py-0.5 rounded border border-[var(--color-border)]">
                            {account.birthDate}
                          </span>
                        ) : (
                          <div />
                        )}

                        <div className="flex items-center gap-1.5">
                          <Button
                            onClick={() => handleAddToAccounts(account)}
                            disabled={isAddingToAccounts === account.id}
                            size="sm"
                            className="h-6 px-2.5 bg-emerald-500/10 hover:bg-emerald-600 text-emerald-600 dark:text-emerald-400 hover:text-[var(--color-text-primary)] border-0 text-[10px] font-semibold rounded transition-colors flex items-center gap-1"
                          >
                            <UserPlus className="w-2.5 h-2.5" />
                            {isAddingToAccounts === account.id
                              ? "Importing..."
                              : "Add to Sentra"}
                          </Button>
                          <button
                            onClick={async () => {
                              if (
                                confirm(
                                  `Purge data item for "${account.username}"?`,
                                )
                              ) {
                                await window.api.generator.deleteAccount(
                                  account.id,
                                );
                                await loadAccounts();
                              }
                            }}
                            className="p-1 text-[var(--color-text-muted)] hover:text-red-500 hover:bg-red-500/10 rounded transition-colors"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </AnimatePresence>
              </div>
            )}
          </div>
        </div>
      </motion.div>

      <GeneratorSettingsModal
        isOpen={showSettings}
        onClose={() => setShowSettings(false)}
        config={config}
        setConfig={setConfig}
        handleUpdateConfig={handleUpdateConfig}
        isSavingConfig={isSavingConfig}
      />
    </div>
  );
};

import { useState, useMemo, useEffect, useRef } from "react";
import { useQueryClient, useQueries } from "@tanstack/react-query";
import { motion, AnimatePresence } from "framer-motion";
import { Search, Users, Clock, User, RefreshCw } from "lucide-react";
import { Virtuoso } from "react-virtuoso";
import { Account } from "@renderer/types";
import { Button } from "@renderer/components/UI/buttons/Button";
import { Input } from "@renderer/components/UI/inputs/Input";
import {
  Avatar,
  AvatarImage,
  AvatarFallback,
} from "@renderer/components/UI/display/Avatar";
import {
  Tooltip,
  TooltipTrigger,
  TooltipContent,
  TooltipProvider,
} from "@renderer/components/UI/display/Tooltip";
import { EmptyState } from "@renderer/components/UI/feedback/EmptyState";
import { ErrorMessage } from "@renderer/components/UI/feedback/ErrorMessage";
import VerifiedIcon from "@renderer/components/UI/icons/VerifiedIcon";
import { formatNumber } from "@renderer/utils/numberUtils";
import {
  useActiveGroupsTab,
  useSetActiveGroupsTab,
  useSelectedGroupId,
  useSetSelectedGroupId,
  useGroupsSearchQuery,
  useSetGroupsSearchQuery,
} from "./stores/useGroupsStore";
import { useSelectedIds } from "@renderer/stores/useSelectionStore";
import { useAccountsManager } from "@renderer/hooks/queries";
import { queryKeys } from "@shared/queryKeys";
import {
  type GroupMembership,
  type PendingGroupRequest,
} from "./api/useGroups";
import type { ChangeEvent } from "react";
import UniversalProfileModal from "@renderer/components/Modals/UniversalProfileModal";
import { GroupDetailsPanel } from "./components/GroupDetailsPanel";
import AccessoryDetailsModal from "@renderer/features/avatar/Modals/AccessoryDetailsModal";

interface GroupsTabProps {
  selectedAccount: Account | null;
}

// Sidebar Group Item Component
interface GroupItemProps {
  group: {
    id: number;
    name: string;
    memberCount?: number;
    hasVerifiedBadge?: boolean;
  };
  role?: {
    name: string;
    rank: number;
  };
  thumbnail?: string;
  isSelected: boolean;
  isPending?: boolean;
  created?: string;
  selectedAccountsCount?: number;
  onClick: () => void;
}

const GroupItem = ({
  group,
  role,
  thumbnail,
  isSelected,
  isPending,
  selectedAccountsCount,
  onClick,
}: GroupItemProps) => {
  return (
    <motion.div
      initial={{ opacity: 0, x: -8 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.18 }}
      className="px-2 py-0.5"
    >
      <button
        onClick={onClick}
        className={[
          "relative w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all duration-200 text-left group overflow-hidden",
          isSelected
            ? "bg-[rgba(var(--accent-color-rgb),0.12)] border border-[var(--accent-color-border)] shadow-sm"
            : "hover:bg-[var(--color-surface-hover)] border border-transparent",
        ].join(" ")}
      >
        {/* Accent left bar */}
        {isSelected && (
          <span className="absolute left-0 top-3 bottom-3 w-[3px] rounded-r-full bg-[var(--accent-color)] shadow-[0_0_8px_var(--accent-color-glow)]" />
        )}

        {/* Avatar */}
        <div className="relative shrink-0">
          <Avatar className="w-10 h-10 rounded-xl border border-[var(--color-border)] group-hover:border-[var(--color-border-strong)] transition-colors">
            <AvatarImage src={thumbnail} alt={group.name} />
            <AvatarFallback className="rounded-xl bg-[var(--color-surface-hover)] text-xs font-bold text-[var(--color-text-secondary)]">
              {group.name.slice(0, 2).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          {isPending && (
            <span className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-yellow-500/90 border-2 border-[var(--color-app-bg)] flex items-center justify-center">
              <Clock size={8} className="text-white" />
            </span>
          )}
        </div>

        {/* Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5 mb-0.5">
            <span className="font-semibold text-sm text-[var(--color-text-primary)] truncate leading-none">
              {group.name}
            </span>
            {group.hasVerifiedBadge && (
              <VerifiedIcon width={13} height={13} className="shrink-0" />
            )}
          </div>
          <div className="flex items-center gap-1.5 flex-wrap">
            {role && !isPending && (
              <span className="text-[10px] font-medium bg-[var(--color-surface-hover)] border border-[var(--color-border)] rounded-md px-1.5 py-0.5 text-[var(--color-text-muted)] truncate max-w-[100px]">
                {role.name}
              </span>
            )}
            {group.memberCount && (
              <span className="text-[10px] text-[var(--color-text-muted)] flex items-center gap-0.5">
                <Users size={9} />
                {formatNumber(group.memberCount)}
              </span>
            )}
            {selectedAccountsCount && selectedAccountsCount > 1 ? (
              <span className="text-[10px] font-bold text-emerald-400 flex items-center gap-0.5">
                <User size={9} />
                {selectedAccountsCount}
              </span>
            ) : null}
          </div>
        </div>
      </button>
    </motion.div>
  );
};

// Main Groups Tab Component
const GroupsTab = ({ selectedAccount }: GroupsTabProps) => {
  // Store state
  const activeTab = useActiveGroupsTab();
  const setActiveTab = useSetActiveGroupsTab();
  const selectedGroupId = useSelectedGroupId();
  const setSelectedGroupId = useSetSelectedGroupId();
  const searchQuery = useGroupsSearchQuery();
  const setSearchQuery = useSetGroupsSearchQuery();

  // Profile modal state
  const [profileUserId, setProfileUserId] = useState<number | null>(null);
  const [selectedStoreItem, setSelectedStoreItem] = useState<{
    id: number;
    name: string;
    imageUrl?: string;
  } | null>(null);

  const selectedIds = useSelectedIds();
  const { accounts } = useAccountsManager();
  const targetAccounts = useMemo(() => {
    if (selectedIds.size > 0) {
      return accounts.filter((a) => selectedIds.has(a.id) && a.cookie);
    }
    return selectedAccount && selectedAccount.cookie ? [selectedAccount] : [];
  }, [selectedAccount, selectedIds, accounts]);
  const [sidebarWidth, setSidebarWidth] = useState(320); // default to 80 * 4
  const [isResizing, setIsResizing] = useState(false);
  const sidebarWidthRef = useRef(sidebarWidth);
  const MIN_SIDEBAR_WIDTH = 240;
  const MAX_SIDEBAR_WIDTH = 480;
  const sidebarRef = useRef<HTMLDivElement | null>(null);
  const resizeOriginRef = useRef(0);

  const clampWidth = (width: number) =>
    Math.min(Math.max(width, MIN_SIDEBAR_WIDTH), MAX_SIDEBAR_WIDTH);

  // Keep ref in sync
  useEffect(() => {
    sidebarWidthRef.current = sidebarWidth;
  }, [sidebarWidth]);

  // Restore saved width
  useEffect(() => {
    try {
      const saved = window.localStorage.getItem("groupsSidebarWidth");
      if (saved) {
        const parsed = parseInt(saved, 10);
        if (!Number.isNaN(parsed)) {
          setSidebarWidth(clampWidth(parsed));
        }
      }
    } catch (error) {
      console.error("Failed to load groups sidebar width", error);
    }
  }, []);

  // Handle drag-to-resize lifecycle
  useEffect(() => {
    if (!isResizing) return;

    const handleMouseMove = (event: MouseEvent) => {
      const newWidth = clampWidth(event.clientX - resizeOriginRef.current);
      setSidebarWidth(newWidth);
      sidebarWidthRef.current = newWidth;
    };

    const handleMouseUp = () => {
      setIsResizing(false);
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
      try {
        window.localStorage.setItem(
          "groupsSidebarWidth",
          sidebarWidthRef.current.toString(),
        );
      } catch (error) {
        console.error("Failed to save groups sidebar width", error);
      }
    };

    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";
    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
    };
  }, [isResizing]);

  // Get user ID
  const userId = selectedAccount?.userId
    ? parseInt(selectedAccount.userId, 10)
    : null;

  // Queries
  const joinedQueries = useQueries({
    queries: targetAccounts.map((acc) => ({
      queryKey: queryKeys.groups.userGroups(
        acc.userId ? parseInt(acc.userId) : 0,
      ),
      queryFn: async (): Promise<GroupMembership[]> => {
        const uid = acc.userId ? parseInt(acc.userId) : null;
        if (!uid) return [];
        const groups = await window.api.getUserGroupsFull(uid);
        if (groups.length === 0) return [];
        const groupIds = groups.map((g: any) => g.group.id);
        const thumbnails = await window.api.getGroupThumbnails(groupIds);
        return groups.map((g: any) => ({
          ...g,
          thumbnail: thumbnails[g.group.id] || "",
        }));
      },
      staleTime: 60 * 1000,
    })),
  });

  const pendingQueries = useQueries({
    queries: targetAccounts.map((acc) => ({
      queryKey: queryKeys.groups.pending(acc.id),
      queryFn: async (): Promise<PendingGroupRequest[]> => {
        if (!acc.cookie) return [];
        const pending = await window.api.getPendingGroupRequests(acc.cookie);
        if (pending.length === 0) return [];
        const groupIds = pending.map((g: any) => g.group.id);
        const thumbnails = await window.api.getGroupThumbnails(groupIds);
        return pending.map((g: any) => ({
          ...g,
          thumbnail: thumbnails[g.group.id] || "",
        }));
      },
      staleTime: 30 * 1000,
    })),
  });

  const joinedGroups = useMemo(() => {
    const all = joinedQueries.flatMap((q) => q.data || []);
    const unique = new Map<
      number,
      GroupMembership & { selectedAccountsCount?: number }
    >();
    const counts = new Map<number, number>();

    all.forEach((g) => {
      counts.set(g.group.id, (counts.get(g.group.id) || 0) + 1);
      if (!unique.has(g.group.id)) {
        unique.set(g.group.id, g);
      }
    });

    return Array.from(unique.values()).map((g) => ({
      ...g,
      selectedAccountsCount: counts.get(g.group.id),
    }));
  }, [joinedQueries]);

  const pendingGroups = useMemo(() => {
    const all = pendingQueries.flatMap((q) => q.data || []);
    const unique = new Map<
      number,
      PendingGroupRequest & { selectedAccountsCount?: number }
    >();
    const counts = new Map<number, number>();

    all.forEach((g) => {
      counts.set(g.group.id, (counts.get(g.group.id) || 0) + 1);
      if (!unique.has(g.group.id)) {
        unique.set(g.group.id, g);
      }
    });

    return Array.from(unique.values()).map((g) => ({
      ...g,
      selectedAccountsCount: counts.get(g.group.id),
    }));
  }, [pendingQueries]);

  // Map of groupId -> accounts that have a pending request for that group
  const pendingAccountMap = useMemo(() => {
    const map = new Map<number, Account[]>();
    targetAccounts.forEach((acc, idx) => {
      const data = pendingQueries[idx]?.data || [];
      (data as PendingGroupRequest[]).forEach((p) => {
        const gId = p.group?.id;
        if (!gId) return;
        const arr = map.get(gId) || [];
        arr.push(acc);
        map.set(gId, arr);
      });
    });
    return map;
  }, [pendingQueries, targetAccounts]);

  const joinedLoading = joinedQueries.some((q) => q.isLoading);
  const pendingLoading = pendingQueries.some((q) => q.isLoading);
  const joinedFetching = joinedQueries.some((q) => q.isFetching);
  const pendingFetching = pendingQueries.some((q) => q.isFetching);
  const joinedError = joinedQueries.some((q) => q.error);
  const pendingError = pendingQueries.some((q) => q.error);

  // Filter groups by search
  const filteredJoinedGroups = useMemo(() => {
    if (!searchQuery.trim()) return joinedGroups;
    const query = searchQuery.toLowerCase();
    return joinedGroups.filter(
      (g: GroupMembership) =>
        g.group.name.toLowerCase().includes(query) ||
        g.role.name.toLowerCase().includes(query),
    );
  }, [joinedGroups, searchQuery]);

  const filteredPendingGroups = useMemo(() => {
    if (!searchQuery.trim()) return pendingGroups;
    const query = searchQuery.toLowerCase();
    return pendingGroups.filter((g: PendingGroupRequest) =>
      g.group.name.toLowerCase().includes(query),
    );
  }, [pendingGroups, searchQuery]);

  const displayGroups =
    activeTab === "joined" ? filteredJoinedGroups : filteredPendingGroups;
  const isLoading = activeTab === "joined" ? joinedLoading : pendingLoading;
  const isFetching = activeTab === "joined" ? joinedFetching : pendingFetching;
  const error = activeTab === "joined" ? joinedError : pendingError;

  // Get the selected group's user role (for joined groups)
  const selectedGroupMembership = useMemo(() => {
    if (activeTab !== "joined" || !selectedGroupId) return null;
    return joinedGroups.find((g) => g.group.id === selectedGroupId);
  }, [activeTab, selectedGroupId, joinedGroups]);

  const handleRefresh = () => {
    if (activeTab === "joined") {
      joinedQueries.forEach((q) => q.refetch());
    } else {
      pendingQueries.forEach((q) => q.refetch());
    }
  };

  // Auto-select first group when data loads or tab changes
  useEffect(() => {
    if (!isLoading && displayGroups.length > 0 && !selectedGroupId) {
      setSelectedGroupId(displayGroups[0].group.id);
    }
  }, [isLoading, displayGroups, selectedGroupId, setSelectedGroupId]);

  // Clear selection when changing tabs
  useEffect(() => {
    setSelectedGroupId(null);
    setSearchQuery("");
  }, [activeTab, setSelectedGroupId, setSearchQuery]);

  return (
    <TooltipProvider>
      <div
        className="flex flex-col h-full"
        style={{ background: "var(--color-app-bg)" }}
      >
        {/* Premium Header */}
        <div className="shrink-0 px-6 pt-5 pb-4 border-b border-[var(--color-border)] bg-[var(--color-surface-strong)]">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-xl font-bold text-[var(--color-text-primary)] leading-none">
                Groups
              </h1>
              <p className="text-xs text-[var(--color-text-muted)] mt-0.5">
                {joinedGroups.length > 0
                  ? `${joinedGroups.length} joined`
                  : "Select an account to view groups"}
                {pendingGroups.length > 0 &&
                  ` · ${pendingGroups.length} pending`}
              </p>
            </div>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="outline"
                  size="icon"
                  onClick={handleRefresh}
                  disabled={isLoading || isFetching || !selectedAccount}
                  className="h-10 w-10"
                >
                  <RefreshCw
                    size={15}
                    className={isLoading || isFetching ? "animate-spin" : ""}
                  />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Refresh Groups</TooltipContent>
            </Tooltip>
          </div>
        </div>

        {/* Main Content */}
        {targetAccounts.length === 0 ? (
          <div className="flex-1 flex items-center justify-center">
            <EmptyState
              icon={Users}
              title="No Accounts Selected"
              description="Select one or more accounts to view their groups."
            />
          </div>
        ) : (
          <div className="flex-1 flex min-h-0">
            {/* Premium Sidebar */}
            <div
              ref={sidebarRef}
              className={`relative flex flex-col shrink-0 border-r border-[var(--color-border)] ${!isResizing ? "transition-[width] duration-150 ease-in-out" : ""}`}
              style={{
                width: `${sidebarWidth}px`,
                background: "var(--color-surface)",
              }}
            >
              {/* Tab pills */}
              <div className="flex items-center gap-1.5 px-3 py-3 border-b border-[var(--color-border)]">
                {[
                  {
                    id: "joined",
                    label: "Joined",
                    count: filteredJoinedGroups.length,
                  },
                  {
                    id: "pending",
                    label: "Pending",
                    count: filteredPendingGroups.length,
                  },
                ].map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as "joined" | "pending")}
                    className={[
                      "flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all duration-200",
                      activeTab === tab.id
                        ? "bg-[var(--accent-color)] text-white shadow-sm"
                        : "text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-surface-hover)]",
                    ].join(" ")}
                  >
                    {tab.label}
                    {tab.count > 0 && (
                      <span
                        className={[
                          "px-1.5 py-0.5 rounded-md text-[10px] font-bold",
                          activeTab === tab.id
                            ? "bg-white/20 text-white"
                            : "bg-[var(--color-surface-hover)] text-[var(--color-text-muted)]",
                        ].join(" ")}
                      >
                        {tab.count}
                      </span>
                    )}
                  </button>
                ))}
              </div>

              {/* Search */}
              <div className="px-3 py-2 border-b border-[var(--color-border)]">
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Search
                      size={13}
                      className="text-[var(--color-text-muted)]"
                    />
                  </div>
                  <Input
                    type="text"
                    placeholder="Search groups…"
                    value={searchQuery}
                    onChange={(e: ChangeEvent<HTMLInputElement>) =>
                      setSearchQuery(e.target.value)
                    }
                    className="pl-8 h-10 text-xs rounded-lg"
                  />
                </div>
              </div>

              {/* Groups List */}
              <div className="flex-1 overflow-hidden py-1.5">
                <AnimatePresence mode="wait">
                  {isLoading ? (
                    <div className="space-y-0.5 px-2 py-1">
                      {[1, 2, 3, 4, 5].map((i) => (
                        <div
                          key={i}
                          className="flex items-center gap-3 px-3 py-2.5"
                        >
                          <div className="w-10 h-10 rounded-xl bg-[var(--color-surface-hover)] animate-pulse" />
                          <div className="flex-1 space-y-1.5">
                            <div className="h-3.5 w-28 bg-[var(--color-surface-hover)] rounded-md animate-pulse" />
                            <div className="h-2.5 w-16 bg-[var(--color-surface-hover)] rounded-md animate-pulse" />
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : error ? (
                    <div className="p-4">
                      <ErrorMessage
                        message="There was an error communicating with Roblox."
                        onRetry={handleRefresh}
                      />
                    </div>
                  ) : displayGroups.length === 0 ? (
                    <motion.div
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      className="flex flex-col items-center justify-center h-full text-center p-6"
                    >
                      <div className="w-12 h-12 rounded-2xl bg-[var(--color-surface-hover)] border border-[var(--color-border)] flex items-center justify-center mb-3">
                        <Users
                          size={20}
                          className="text-[var(--color-text-muted)]"
                        />
                      </div>
                      <p className="text-sm font-medium text-[var(--color-text-secondary)]">
                        {searchQuery
                          ? "No matches"
                          : activeTab === "joined"
                            ? "No groups joined"
                            : "No pending requests"}
                      </p>
                      <p className="text-xs text-[var(--color-text-muted)] mt-1">
                        {searchQuery ? "Try a different search term" : ""}
                      </p>
                    </motion.div>
                  ) : (
                    <Virtuoso
                      data={
                        displayGroups as (
                          | GroupMembership
                          | PendingGroupRequest
                        )[]
                      }
                      overscan={200}
                      itemContent={(_index, item) => {
                        if (activeTab === "joined") {
                          const joinedItem = item as GroupMembership & {
                            selectedAccountsCount?: number;
                          };
                          return (
                            <GroupItem
                              key={joinedItem.group.id}
                              group={joinedItem.group}
                              role={joinedItem.role}
                              thumbnail={joinedItem.thumbnail}
                              isSelected={
                                selectedGroupId === joinedItem.group.id
                              }
                              selectedAccountsCount={
                                joinedItem.selectedAccountsCount
                              }
                              onClick={() =>
                                setSelectedGroupId(joinedItem.group.id)
                              }
                            />
                          );
                        } else {
                          const pendingItem = item as PendingGroupRequest & {
                            selectedAccountsCount?: number;
                          };
                          return (
                            <GroupItem
                              key={pendingItem.group.id}
                              group={pendingItem.group}
                              thumbnail={pendingItem.thumbnail}
                              isSelected={
                                selectedGroupId === pendingItem.group.id
                              }
                              isPending
                              created={pendingItem.created}
                              selectedAccountsCount={
                                pendingItem.selectedAccountsCount
                              }
                              onClick={() =>
                                setSelectedGroupId(pendingItem.group.id)
                              }
                            />
                          );
                        }
                      }}
                    />
                  )}
                </AnimatePresence>
              </div>

              {/* Resize Handle */}
              <div
                className="absolute top-0 right-0 h-full cursor-col-resize z-20"
                style={{
                  right: "-2px",
                  width: "4px",
                  background: isResizing
                    ? "rgba(var(--accent-color-rgb),0.4)"
                    : "transparent",
                }}
                onMouseDown={() => {
                  const left =
                    sidebarRef.current?.getBoundingClientRect().left ?? 0;
                  resizeOriginRef.current = left;
                  setIsResizing(true);
                }}
              >
                <div className="absolute inset-0 hover:bg-[var(--accent-color)]/20 transition-colors" />
              </div>
            </div>

            {/* Details Panel */}
            <GroupDetailsPanel
              groupId={selectedGroupId}
              selectedAccount={selectedAccount}
              pendingAccounts={
                selectedGroupId !== null
                  ? (pendingAccountMap.get(selectedGroupId) ?? [])
                  : []
              }
              isPending={activeTab === "pending"}
              userRole={selectedGroupMembership?.role}
              onViewProfile={(userId) => setProfileUserId(userId)}
              onStoreItemSelect={(item) => setSelectedStoreItem(item)}
            />
          </div>
        )}
      </div>

      <UniversalProfileModal
        isOpen={!!profileUserId}
        onClose={() => setProfileUserId(null)}
