                >
                  <span className="flex items-center gap-2.5">
                    <Copy size={16} />
                    <span className="font-medium">Copy User ID</span>
                  </span>
                  <span
                    className="text-xs text-[var(--color-text-muted)] font-mono"
                    style={blurIdentity ? { filter: "blur(16px)" } : undefined}
                  >
