              </div>
            </motion.div>
          </AnimatePresence>,
          document.body,
        )}

      <Suspense fallback={null}>
        <PlayerInventorySheet
          isOpen={isInventoryOpen}
          onClose={() => setIsInventoryOpen(false)}
          userId={userIdNum}
          username={profile?.username || profile?.displayName || String(userId)}
          cookie={requestCookie}
        />
