        ...meta,
        id: meta.filename,
        createdAt: dateObj.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
        formattedSize: formatBytes(meta.size),
        date: dateObj.toLocaleDateString(),
      };
    });
  }, [logsMetadata]);

