                  <div className="flex items-center justify-center h-full text-[var(--color-text-muted)]">
                    Loading content...
                  </div>
                ) : (
                  <Virtuoso
                    style={{ height: "100%" }}
                    data={logItemsWithTimestamps}
                    overscan={200}
                    computeItemKey={(index, item) => {
                      if (item.type === "timestamp") {
                        return `${selectedLog?.id ?? "log"}-timestamp-${item.timestamp}`;
                      } else {
                        return `${selectedLog?.id ?? "log"}-entry-${index}-${item.entry.source}`;
                      }
                    }}
                    itemContent={(_, item) => {
                      if (item.type === "timestamp") {
                        return (
                          <div className="sticky top-0 bg-[var(--color-app-bg)] border-y border-[var(--color-border)] py-2 px-3 z-10">
                            <div className="text-xs font-mono font-bold text-[var(--color-text-secondary)] tracking-wider">
                              {item.timestamp}
                            </div>
                          </div>
                        );
                      }

                      const entry = item.entry;
                      return (
                        <div className="flex flex-col gap-1 py-1.5 px-3 hover:bg-[var(--color-surface)]/50 rounded transition-colors group/line">
                          <div className="flex items-center gap-1.5">
                            {entry.level !== "INFO" && (
                              <span
                                className={`shrink-0 w-16 text-[10px] font-bold px-1.5 py-0.5 rounded text-center select-none flex items-center justify-center gap-1 ${
                                  entry.level === "WARN"
                                    ? "bg-yellow-500/10 text-yellow-400"
                                    : entry.level === "ERROR"
                                      ? "bg-red-500/10 text-red-400"
                                      : "bg-[var(--color-surface-muted)] text-[var(--color-text-secondary)]"
                                }`}
                              >
                                {entry.level === "ERROR" && <Bug size={10} />}
                                {entry.level === "WARN" && (
                                  <AlertTriangle size={10} />
                                )}
                                {entry.level}
                              </span>
                            )}
                            <span className="text-purple-400/60 shrink-0 select-none w-auto max-w-[120px] truncate text-xs">
                              [{entry.source}]
                            </span>
                          </div>
                          <span className="text-[var(--color-text-secondary)] break-all whitespace-pre-wrap flex-1 text-xs pl-1">
                            {entry.message}
                          </span>
                        </div>
                      );
                    }}
                    components={{
                      Footer: () => (
                        <div className="mt-8 pt-4 border-t border-[var(--color-border)]/50 text-center text-xs text-[var(--color-text-muted)] italic select-none flex items-center justify-center gap-2 pb-4">
                          <CheckCircle2 size={12} /> End of log file
                        </div>
                      ),
                    }}
                  />
                )}
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-[var(--color-text-muted)]">
              <div className="w-20 h-20 rounded-full bg-[var(--color-surface)] border border-[var(--color-border)] flex items-center justify-center mb-6 shadow-2xl">
                <FileClock size={40} className="opacity-50" />
              </div>
              <p className="text-xl font-bold text-[var(--color-text-primary)]">
                No Log Selected
              </p>
              <p className="text-sm mt-2 max-w-xs text-center text-[var(--color-text-secondary)]">
                Select a log file from the sidebar to view detailed session
                information.
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Context Menu */}
      {contextMenu &&
        createPortal(
          <div
            ref={contextMenuRef}
            className="fixed z-50 w-48 bg-[var(--color-surface)] border border-[var(--color-border)] rounded-lg shadow-xl py-1"
            style={{
              top: Math.min(contextMenu.y, window.innerHeight - 100),
              left: Math.min(contextMenu.x, window.innerWidth - 200),
            }}
          >
            <button
              onClick={() => handleOpenInNotepad(contextMenu.logId)}
              className="pressable w-full text-left px-4 py-2.5 text-sm text-[var(--color-text-secondary)] hover:bg-[var(--color-surface-hover)] hover:text-[var(--color-text-primary)] flex items-center gap-2"
            >
              <ExternalLink size={16} />
              <span>Open in Notepad</span>
            </button>
            <button
              onClick={() => handleRefreshLog(contextMenu.logId)}
              className="pressable w-full text-left px-4 py-2.5 text-sm text-[var(--color-text-secondary)] hover:bg-[var(--color-surface-hover)] hover:text-[var(--color-text-primary)] flex items-center gap-2"
            >
              <RefreshCw size={16} />
              <span>Refresh Log</span>
            </button>
            <div className="h-px bg-[var(--color-surface-hover)] my-1"></div>
            <button
              onClick={() => handleDeleteLog(contextMenu.logId)}
              className="pressable w-full text-left px-4 py-2.5 text-sm text-red-400 hover:bg-red-500/10 flex items-center gap-2"
            >
              <Trash2 size={16} />
              <span>Delete Log</span>
            </button>
          </div>,
          document.body,
        )}
      {logPendingDeletion && (
        <ConfirmModal
          isOpen={!!logPendingDeletion}
          onClose={() => setLogPendingDeletion(null)}
          onConfirm={confirmDeleteLog}
          title="Delete log file"
          message={`Are you sure you want to delete ${logPendingDeletion.filename}? This cannot be undone.`}
          confirmText="Delete"
          isDangerous
        />
      )}
      {isClearAllModalOpen && (
        <ConfirmModal
          isOpen={isClearAllModalOpen}
          onClose={() => setIsClearAllModalOpen(false)}
          onConfirm={confirmClearAllLogs}
          title="Delete all logs"
          message="Are you sure you want to delete all log files? This cannot be undone."
          confirmText="Delete All"
          isDangerous
        />
      )}
    </div>
  );
};

