  },
];

export default function WarmerTab() {
  const { accounts = [] } = useAccountsManager();
  const { showNotification } = useNotification();

  const [selectedGroupId, setSelectedGroupId] = useState<string | null>("all");
  const [isWarming, setIsWarming] = useState(false);
  const [warmingProgress, setWarmingProgress] = useState({
    completed: 0,
    total: 0,
  });
  const [warmingTasks, setWarmingTasks] = useState<WarmingTask[]>(
    DEFAULT_WARMING_TASKS,
  );

  const groupOptions: DropdownOption[] = [
    { value: "all", label: "All accounts" },
    ...accounts.map((acc) => ({
      value: acc.id,
      label: acc.displayName || acc.username,
      subLabel: `@${acc.username}`,
    })),
  ];

  const selectedAccounts =
    selectedGroupId === "all"
      ? accounts
      : accounts.filter((account) => account.id === selectedGroupId);

  const handleToggleTask = useCallback((taskId: string) => {
    setWarmingTasks((prev) =>
      prev.map((task) =>
        task.id === taskId ? { ...task, enabled: !task.enabled } : task,
      ),
    );
  }, []);

  const handleStartWarming = useCallback(async () => {
    if (selectedAccounts.length === 0) {
      showNotification("No accounts selected", "warning");
      return;
    }

    const enabledTasks = warmingTasks.filter((task) => task.enabled);
    if (enabledTasks.length === 0) {
      showNotification("Select at least one warming task", "warning");
      return;
    }

    setIsWarming(true);
    setWarmingProgress({ completed: 0, total: selectedAccounts.length });

    try {
      for (let index = 0; index < selectedAccounts.length; index += 1) {
        const account = selectedAccounts[index];
        setWarmingProgress((prev) => ({ ...prev, completed: index + 1 }));

        if (account.cookie) {
          await new Promise((resolve) => setTimeout(resolve, 900));
        } else {
          await new Promise((resolve) => setTimeout(resolve, 500));
        }
      }

      showNotification(
        `Warm cycle complete for ${selectedAccounts.length} account${selectedAccounts.length === 1 ? "" : "s"}`,
        "success",
      );
    } catch (error) {
      console.error(error);
      showNotification("Warm cycle failed", "error");
    } finally {
      setIsWarming(false);
      setWarmingProgress({ completed: 0, total: selectedAccounts.length });
    }
  }, [selectedAccounts, warmingTasks, showNotification]);

  const progressPercent =
    warmingProgress.total > 0
      ? (warmingProgress.completed / warmingProgress.total) * 100
      : 0;

  return (
    <div className="flex h-full flex-col overflow-y-auto p-6">
      <div className="mx-auto w-full max-w-4xl space-y-6">
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.25 }}
          className="space-y-6"
        >
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="flex h-11 w-11 items-center justify-center rounded-xl border border-orange-500/30 bg-orange-500/10 text-orange-400">
                <Flame className="h-5 w-5" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--color-text-primary)]">
                  Warmer
                </h1>
                <p className="text-sm text-[var(--color-text-secondary)]">
                  Keep fresh accounts looking active without forcing anything
                  risky.
                </p>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-2 rounded-full border border-[var(--color-border)] bg-[var(--color-surface)] px-3 py-1.5 text-xs text-[var(--color-text-muted)]">
              <Sparkles className="h-3.5 w-3.5 text-amber-400" />
              low-noise activity
            </div>
          </div>

          <div className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-surface)] p-5 shadow-[0_8px_24px_rgba(0,0,0,0.08)]">
            <div className="grid gap-5 lg:grid-cols-[1.3fr_0.7fr]">
              <div className="space-y-5">
                <div>
                  <label className="mb-2 block text-xs font-semibold uppercase tracking-[0.12em] text-[var(--color-text-muted)]">
                    Target accounts
                  </label>
                  <CustomDropdown
                    options={groupOptions}
                    value={selectedGroupId || "all"}
                    onChange={(value) =>
                      setSelectedGroupId(value === "all" ? "all" : value)
                    }
                    placeholder="Select accounts"
                  />
                </div>

                <div>
                  <div className="mb-3 flex items-center justify-between">
                    <label className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--color-text-muted)]">
                      Warm steps
                    </label>
                    <span className="text-xs text-[var(--color-text-muted)]">
                      {warmingTasks.filter((task) => task.enabled).length}{" "}
                      enabled
                    </span>
                  </div>

                  <div className="space-y-2">
                    {warmingTasks.map((task) => (
                      <button
                        key={task.id}
                        type="button"
                        onClick={() => handleToggleTask(task.id)}
                        className="flex w-full items-center gap-3 rounded-xl border border-[var(--color-border)] bg-[var(--color-surface-hover)] p-3 text-left transition-colors hover:border-[var(--color-border-strong)]"
                      >
                        <input
                          type="checkbox"
                          checked={task.enabled}
                          onChange={() => handleToggleTask(task.id)}
                          className="h-4 w-4 rounded border-[var(--color-border)] accent-[var(--accent-color)]"
                          onClick={(e) => e.stopPropagation()}
                        />
                        <div className="flex-1 min-w-0">
                          <div className="text-sm font-medium text-[var(--color-text-primary)]">
                            {task.name}
                          </div>
                          <div className="mt-0.5 text-xs text-[var(--color-text-muted)]">
                            {task.description}
                          </div>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-surface-hover)] p-4">
                <div className="mb-3 text-xs font-semibold uppercase tracking-[0.12em] text-[var(--color-text-muted)]">
                  Queue summary
                </div>
                <div className="space-y-3">
                  <div>
                    <div className="text-3xl font-bold text-[var(--color-text-primary)]">
                      {selectedAccounts.length}
                    </div>
                    <div className="text-xs text-[var(--color-text-muted)]">
                      selected
                    </div>
                  </div>
                  <div className="h-px bg-[var(--color-border)]" />
                  <div>
                    <div className="text-sm text-[var(--color-text-primary)] font-medium">
                      {warmingTasks.filter((task) => task.enabled).length}{" "}
                      active steps
                    </div>
                    <div className="text-xs text-[var(--color-text-muted)]">
                      Safe, browser-driven activity only.
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {isWarming && (
              <div className="mt-5 rounded-xl border border-orange-500/30 bg-orange-500/5 p-4">
                <div className="mb-2 flex items-center justify-between text-xs text-[var(--color-text-muted)]">
                  <span>Progress</span>
                  <span>
                    {warmingProgress.completed} / {warmingProgress.total}
                  </span>
                </div>
                <div className="h-2.5 overflow-hidden rounded-full bg-[var(--color-surface-hover)]">
                  <motion.div
                    className="h-full rounded-full bg-gradient-to-r from-orange-500 to-amber-400"
                    animate={{ width: `${progressPercent}%` }}
                    transition={{ duration: 0.25 }}
                  />
                </div>
              </div>
            )}

            <div className="mt-5 flex gap-3">
              <Button
                onClick={handleStartWarming}
                disabled={isWarming}
                className="flex-1 rounded-xl bg-[var(--accent-color)] text-[var(--accent-color-foreground)] hover:opacity-90"
              >
                {isWarming ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Running warm cycle
                  </>
                ) : (
                  <>
                    <Play className="mr-2 h-4 w-4" />
                    Start warm cycle
                  </>
                )}
              </Button>
              <Button
                onClick={() =>
                  setWarmingProgress({
                    completed: 0,
                    total: selectedAccounts.length,
                  })
                }
                variant="ghost"
                className="rounded-xl"
              >
                <RotateCcw className="mr-2 h-4 w-4" />
                Reset
              </Button>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from "react";

export interface WatcherSession {
  id: string;
  accountId: string;
  username: string;
  displayName?: string;
  userId: string;
  avatarUrl?: string;
  placeId: number;
  jobId?: string;
  friendId?: string;
  pid: number;
  logFile: string;
  lastLogSize: number;
  lastUpdate: number;
  status: "running" | "crashed" | "restarting";
  restartCount: number;
  restartAttempts: number;
  lastCrashTime?: number;
  lastCrashReason?: string;
  lastStartTime?: number;
  launchConfig?: {
    cookie: string;
    placeId: number | string;
    jobId?: string;
    friendId?: string | number;
    installPath?: string;
  };
}

export interface WatcherConfig {
  enabled: boolean;
  autoRestart: boolean;
  restartDelaySeconds: number;
  checkIntervalMs: number;
  logCheckIntervalMs: number;
  enableRAMLimiter?: boolean;
  ramLimitMB?: number;
  enableClientTimeout?: boolean;
  clientTimeoutSeconds?: number;
  enableCPULimiter?: boolean;
  cpuLimitPercent?: number;
}

export interface WatcherEvent {
  timestamp: number;
  type:
    | "session-started"
    | "session-crashed"
    | "session-restarted"
    | "session-stopped"
    | "error";
  sessionId: string;
  username: string;
  message: string;
  details?: any;
}

/**
 * useWatcher - Custom hook for managing Watcher state and API interactions
 */
export function useWatcher() {
  const [sessions, setSessions] = useState<WatcherSession[]>([]);
  const [config, setConfig] = useState<WatcherConfig>({
    enabled: false,
    autoRestart: true,
    restartDelaySeconds: 5,
    checkIntervalMs: 5000,
    logCheckIntervalMs: 2000,
  });
  const [events, setEvents] = useState<WatcherEvent[]>([]);
  const [isWatching, setIsWatching] = useState(false);
  const [currentStatus, setCurrentStatus] = useState<string>("loading");
  const cleanupListenersRef = useRef<Array<() => void>>([]);

  const normalizeSessions = useCallback((sessionList: WatcherSession[]) => {
    const sessionsById = new Map<string, WatcherSession>();
    for (const session of sessionList) {
      sessionsById.set(session.id, session);
    }
    return Array.from(sessionsById.values());
  }, []);

  // Initialize watcher on mount
  useEffect(() => {
    const initializeWatcher = async () => {
      try {
        // Fetch initial state from backend
        const [initialSessions, initialConfig, initialEvents] =
          await Promise.all([
            window.api.getSessions(),
            window.api.getConfig(),
            window.api.getEvents(),
          ]);

        console.log(
          "[useWatcher] Initialized with sessions:",
          initialSessions.length,
        );
        setSessions(normalizeSessions(initialSessions));
        setConfig(initialConfig);
        setEvents(initialEvents);
        setIsWatching(initialConfig.enabled);
        setCurrentStatus("ready");
      } catch (error) {
        console.error("[Watcher] Error initializing:", error);
        setCurrentStatus("error");
      }
    };

    initializeWatcher();

    // Set up listeners for real-time updates
    const unlistenEvent = window.api.onEvent((event: WatcherEvent) => {
      setEvents((prev) => [...prev, event].slice(-1000)); // Keep last 1000 events
    });

    const unlistenSessionsUpdated = window.api.onSessionsUpdated(
      (updatedSessions: WatcherSession[]) => {
        setSessions(normalizeSessions(updatedSessions));
      },
    );

    const unlistenCrashed = window.api.onSessionCrashed(
      (data: { sessionId: string; username: string; reason: string }) => {
        setSessions((prev) =>
          prev.map((s) =>
            s.id === data.sessionId
              ? { ...s, status: "crashed", lastCrashTime: Date.now() }
              : s,
          ),
        );
      },
    );

    const unlistenRestarted = window.api.onSessionRestarted(
      (data: { sessionId: string; username: string; restartCount: number }) => {
        setSessions((prev) =>
          prev.map((s) =>
            s.id === data.sessionId
              ? { ...s, status: "running", restartCount: data.restartCount }
              : s,
          ),
        );
      },
    );

    cleanupListenersRef.current = [
      unlistenEvent,
      unlistenSessionsUpdated,
      unlistenCrashed,
      unlistenRestarted,
    ];

    return () => {
      cleanupListenersRef.current.forEach((fn) => fn());
    };
  }, []);

  const startWatching = useCallback(async () => {
    try {
      await window.api.start();
      setIsWatching(true);
    } catch (error) {
      console.error("[Watcher] Error starting watcher:", error);
    }
  }, []);

  const stopWatching = useCallback(async () => {
    try {
      await window.api.stop();
      setIsWatching(false);
    } catch (error) {
      console.error("[Watcher] Error stopping watcher:", error);
    }
  }, []);

  const addSession = useCallback(
    async (sessionData: Omit<WatcherSession, "id">) => {
      try {
        const newSession = await window.api.addSession(
          sessionData.accountId,
          sessionData.username,
          sessionData.userId,
          sessionData.pid,
          sessionData.placeId,
          sessionData.logFile,
        );
        setSessions((prev) => normalizeSessions([...prev, newSession]));
        return newSession;
      } catch (error) {
        console.error("[Watcher] Error adding session:", error);
        throw error;
      }
    },
    [normalizeSessions],
  );

  const removeSession = useCallback(
    async (sessionId: string, killProcess?: boolean) => {
      try {
        await window.api.removeSession(sessionId, killProcess);
        setSessions((prev) => prev.filter((s) => s.id !== sessionId));
      } catch (error) {
        console.error("[Watcher] Error removing session:", error);
        throw error;
      }
    },
    [],
  );

  const updateConfig = useCallback(
    async (newConfig: Partial<WatcherConfig>) => {
      try {
        const updated = await window.api.setConfig(newConfig);
        setConfig(updated);
      } catch (error) {
        console.error("[Watcher] Error updating config:", error);
        throw error;
      }
    },
    [],
  );

  const clearEvents = useCallback(async () => {
    try {
      await window.api.clearEvents();
      setEvents([]);
    } catch (error) {
      console.error("[Watcher] Error clearing events:", error);
      throw error;
    }
  }, []);

  return {
    sessions,
    config,
    events,
    isWatching,
    currentStatus,
    startWatching,
    stopWatching,
    addSession,
    removeSession,
    updateConfig,
    clearEvents,
  };
}

