        setBackupStep("pin");
        setBackupPin(Array(6).fill(""));
        setBackupPinConfirm(Array(6).fill(""));
        setBackupError(null);
        setBackupLocationMode("auto");
        setStoredBackupPin("");
      } catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        addNotification({
          type: "error",
          title: "Backup failed",
          message: msg,
