  // PIN input handler with proper ref management (matches PinSetupDialog)
  const handlePinInputChange = useCallback(
    (
      index: number,
      value: string,
      setter: any,
      refs: React.MutableRefObject<(HTMLInputElement | null)[]>,
    ) => {
      const digit = value.slice(-1);
      if (!/^\d?$/.test(digit)) return;

      setter((prev: string[]) => {
        const newPin = [...prev];
        newPin[index] = digit;
        return newPin;
      });

      if (digit && index < 5) {
        refs.current[index + 1]?.focus();
      }
    },
    [],
  );

  const handlePinKeyDown = useCallback(
    (
      index: number,
      e: React.KeyboardEvent<HTMLInputElement>,
      currentPin: string[],
      setter: any,
      refs: React.MutableRefObject<(HTMLInputElement | null)[]>,
    ) => {
      // Handle Backspace
      if (e.key === "Backspace") {
        e.preventDefault();
        if (!currentPin[index] && index > 0) {
          refs.current[index - 1]?.focus();
          setter((prev: string[]) => {
            const newPin = [...prev];
            newPin[index - 1] = "";
            return newPin;
          });
        } else {
          setter((prev: string[]) => {
            const newPin = [...prev];
            newPin[index] = "";
            return newPin;
          });
        }
        return;
      }

      // Allow arrow navigation
      if (e.key === "ArrowLeft" && index > 0) {
        refs.current[index - 1]?.focus();
        return;
      } else if (e.key === "ArrowRight" && index < 5) {
        refs.current[index + 1]?.focus();
        return;
      }

      // Fallback: accept direct digit key presses (including numpad)
      if (/^\d$/.test(e.key) || /^Numpad/.test((e as any).code || "")) {
        e.preventDefault();
        const digit = e.key.match(/\d/)?.[0] ?? "";
        if (!digit) return;
        setter((prev: string[]) => {
          const newPin = [...prev];
          newPin[index] = digit;
          return newPin;
        });
        if (index < 5) refs.current[index + 1]?.focus();
        return;
      }
    },
    [],
  );

