        <input
          key={index}
          ref={(el) => {
            refs.current[index] = el;
          }}
          type="password"
          inputMode="numeric"
          maxLength={1}
          value={digit}
          onChange={(e) =>
            handlePinInputChange(index, e.target.value, setter, refs)
          }
          onKeyDown={(e) => handlePinKeyDown(index, e, values, setter, refs)}
          onPaste={(e) => {
            try {
              const text = e.clipboardData?.getData("text") || "";
              const digits = text.replace(/\D/g, "").split("");
              if (digits.length === 0) return;
              setter((prev: string[]) => {
                const next = [...prev];
                for (
                  let i = 0;
                  i < digits.length && index + i < next.length;
                  i++
                ) {
                  next[index + i] = digits[i];
                }
                return next;
              });
              // focus the last pasted digit (or next available)
              requestAnimationFrame(() => {
                const lastIndex = Math.min(
                  index + digits.length - 1,
                  refs.current.length - 1,
                );
                refs.current[lastIndex]?.focus();
              });
            } catch (err) {
              // ignore
            }
          }}
          onPointerDown={() => {
            // Ensure input receives focus on pointer interaction; do not stop propagation
            try {
              refs.current[index]?.focus();
            } catch (err) {
              /* ignore */
            }
          }}
          onTouchStart={() => {
            try {
              refs.current[index]?.focus();
            } catch (err) {
              /* ignore */
            }
          }}
          onClick={() => {
            try {
              refs.current[index]?.focus();
