                              : "hover:bg-[var(--color-surface-hover)] border border-transparent"
                          }`}
                        >
                          {isSelected && (
                            <span className="absolute left-0 top-2 bottom-2 w-[3px] rounded-full bg-[var(--accent-color)]" />
