              ))
            ) : (
              <div className="text-center py-10 text-[var(--color-text-muted)] text-sm">
                No logs found.
              </div>
            )}
          </div>
        </div>

        <div className="flex-1 flex flex-col bg-[var(--color-app-bg)] min-w-0">
          {selectedLog ? (
