                            className={`shrink-0 w-16 text-[10px] font-bold px-1.5 py-0.5 rounded text-center select-none flex items-center justify-center gap-1 ${
                              entry.level === "WARN"
                                ? "bg-yellow-500/10 text-yellow-400"
                                : entry.level === "ERROR"
                                  ? "bg-red-500/10 text-red-400"
