import React, { useEffect, useMemo, useState } from "react";
import { applyTheme, availableThemes, ThemeName } from "./theme";
import { ThemePreference } from "../types";
import { ThemeContext, CustomThemeName } from "./ThemeContext";

interface ThemeProviderProps {
  initialTheme?: ThemePreference;
  children: React.ReactNode;
}

export const ThemeProvider: React.FC<ThemeProviderProps> = ({
  initialTheme = "dark", // Always default to dark theme
  children,
}) => {
  const getSystemTheme = () => {
    if (typeof window === "undefined" || !window.matchMedia) return "dark";
    return window.matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light";
  };

  const [themePreference, setThemePreference] =
    useState<ThemePreference>(initialTheme);
  const [systemTheme, setSystemTheme] = useState<ThemeName>("dark");
  const [customTheme, setCustomTheme] = useState<CustomThemeName>("default");

  const resolvedThemeName: ThemeName = "dark";

  const theme = useMemo(
    () => availableThemes[resolvedThemeName] ?? availableThemes.dark,
    [resolvedThemeName],
  );

  useEffect(() => {
    applyTheme(theme);
  }, [theme]);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mql = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = (event: MediaQueryListEvent) =>
      setSystemTheme(event.matches ? "dark" : "dark");
    mql.addEventListener("change", handleChange);
    return () => mql.removeEventListener("change", handleChange);
  }, []);

  // Load customTheme from persisted settings on mount
  useEffect(() => {
    if ((window as any).api?.getSettings) {
      (window as any).api
        .getSettings()
        .then((settings: any) => {
          if (
            settings?.customTheme &&
            [
              "default",
              "hearts",
              "aurora",
              "ocean",
              "forest",
              "sunset",
              "cosmic",
              "ember",
              "pixel",
              "breeze",
              "comet",
              "petals",
            ].includes(settings.customTheme)
          ) {
            setCustomTheme(settings.customTheme as CustomThemeName);
          }
        })
        .catch(() => {
          // Keep default if API call fails
        });
    }
  }, []);

  const handleSetCustomTheme = (name: CustomThemeName) => {
    setCustomTheme(name);
    // Save to settings
    if ((window as any).api?.setSettings) {
      (window as any).api
        .setSettings({ customTheme: name })
        .catch((err: any) => {
          console.error("[ThemeProvider] Failed to save customTheme:", err);
        });
    }
    console.log("[ThemeProvider] Set customTheme to:", name);
  };

  const value = useMemo(
    () => ({
      theme,
      themeName: resolvedThemeName,
      themePreference,
      setTheme: setThemePreference,
      customTheme,
      setCustomTheme: handleSetCustomTheme,
    }),
    [theme, resolvedThemeName, themePreference, customTheme],
  );

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
};

export interface SalesItem {
  id: number;
  sales: number;
}

/**
 * Get sales data for a single asset from the database
 */
export async function getSalesData(assetId: number): Promise<SalesItem | null> {
  try {
    const result = await window.api.getSalesData(assetId);
    return result;
  } catch (error) {
    return null;
  }
}

/**
 * Get sales data for multiple assets from the database
 */
export async function getBatchSalesData(
  assetIds: number[],
): Promise<Map<number, SalesItem>> {
  try {
    const result = await window.api.getBatchSalesData(assetIds);
    const salesMap = new Map<number, SalesItem>();
    for (const [assetIdStr, sales] of Object.entries(result)) {
      const assetId = parseInt(assetIdStr, 10);
      if (!isNaN(assetId)) {
        salesMap.set(assetId, { id: assetId, sales: sales as number });
      }
    }
    return salesMap;
  } catch (error) {
    return new Map();
  }
}

/**
 * Check if sales data exists for an asset
 * Note: This now requires an async call to the database
 */
export async function hasSalesData(assetId: number): Promise<boolean> {
  const data = await getSalesData(assetId);
  return data !== null;
}

export function formatNumber(num: number): string {
  return num.toLocaleString();
}

